/// In-memory replay backend with bounded TTL retention.
#[derive(Clone, Debug, Default)]
pub struct InMemoryReplayBackend {
    claims: Arc<RwLock<HashMap<String, OffsetDateTime>>>,
}

#[async_trait]
impl ReplayBackend for InMemoryReplayBackend {
    async fn claim(&self, message_id: &str, expires_at: OffsetDateTime) -> RuntimeResult<bool> {
        let now = OffsetDateTime::now_utc();
        let mut claims = self.claims.write().await;
        claims.retain(|_, expiry| *expiry > now);
        if claims.contains_key(message_id) {
            return Ok(false);
        }
        claims.insert(message_id.to_owned(), expires_at);
        Ok(true)
    }
}

/// Replay registry backed by a pluggable atomic backend.
#[derive(Clone)]
pub struct ReplayStore {
    backend: Arc<dyn ReplayBackend>,
}

impl Default for ReplayStore {
    fn default() -> Self {
        Self::new(Arc::new(InMemoryReplayBackend::default()))
    }
}

impl ReplayStore {
    /// Creates a replay registry from an atomic backend.
    #[must_use]
    pub fn new(backend: Arc<dyn ReplayBackend>) -> Self {
        Self { backend }
    }

    /// Atomically claims one message id for a bounded replay window.
    pub async fn claim(&self, message_id: &str, expires_at: OffsetDateTime) -> RuntimeResult<bool> {
        self.backend.claim(message_id, expires_at).await
    }
}

/// Versioned compatibility-profile state persisted alongside native runtime state.
///
/// Native AIP remains the source of truth for actions and lifecycle events. This
/// record stores only profile-owned projections and bindings that cannot be
/// reconstructed from a native action id, such as an A2A task alias or webhook
/// registration. The monotonically increasing revision provides a fencing value
/// for concurrent profile workers.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct ProfileStateEntry {
    /// Profile namespace, for example `aip.a2a.tasks.v1`.
    pub namespace: String,
    /// Stable key within the namespace.
    pub key: String,
    /// Profile-owned JSON value. Raw credentials must never be stored here.
    pub value: Value,
    /// Monotonic compare-and-set revision, starting at one.
    pub revision: u64,
    /// Last successful mutation time.
    pub updated_at: OffsetDateTime,
}

/// Result of one atomic profile-state compare-and-set operation.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub enum ProfileStateCasOutcome {
    /// The requested mutation was committed.
    Applied(ProfileStateEntry),
    /// The expected revision did not match. `None` means the key is absent.
    Conflict(Option<ProfileStateEntry>),
}

/// Durable atomic state contract for compatibility profiles.
#[async_trait]
pub trait ProfileStateBackend: Send + Sync {
    /// Atomically creates or replaces a value when `expected_revision` matches.
    ///
    /// `None` means the key must not exist. `Some(n)` means the current record
    /// must have revision `n`. Implementations must increment revisions without
    /// gaps for each successfully written key.
    async fn compare_and_set(
        &self,
        namespace: &str,
        key: &str,
        expected_revision: Option<u64>,
        value: Value,
    ) -> RuntimeResult<ProfileStateCasOutcome>;

    /// Returns one profile-state record.
    async fn get(&self, namespace: &str, key: &str) -> RuntimeResult<Option<ProfileStateEntry>>;

    /// Lists records in stable key order, optionally restricted by a key prefix.
    async fn list(
        &self,
        namespace: &str,
        key_prefix: Option<&str>,
    ) -> RuntimeResult<Vec<ProfileStateEntry>>;

    /// Deletes a record only when its current revision matches.
    async fn delete(
        &self,
        namespace: &str,
        key: &str,
        expected_revision: u64,
    ) -> RuntimeResult<bool>;
}

/// In-memory atomic profile-state backend.
#[derive(Clone, Debug, Default)]
pub struct InMemoryProfileStateBackend {
    entries: Arc<RwLock<BTreeMap<(String, String), ProfileStateEntry>>>,
}

#[async_trait]
impl ProfileStateBackend for InMemoryProfileStateBackend {
    async fn compare_and_set(
        &self,
        namespace: &str,
        key: &str,
        expected_revision: Option<u64>,
        value: Value,
    ) -> RuntimeResult<ProfileStateCasOutcome> {
        validate_profile_state_selector(namespace, key)?;
        let mut entries = self.entries.write().await;
        let map_key = (namespace.to_owned(), key.to_owned());
        let current = entries.get(&map_key).cloned();
        if current.as_ref().map(|entry| entry.revision) != expected_revision {
            return Ok(ProfileStateCasOutcome::Conflict(current));
        }
        let entry = ProfileStateEntry {
            namespace: namespace.to_owned(),
            key: key.to_owned(),
            value,
            revision: expected_revision.unwrap_or(0).saturating_add(1),
            updated_at: OffsetDateTime::now_utc(),
        };
        entries.insert(map_key, entry.clone());
        Ok(ProfileStateCasOutcome::Applied(entry))
    }

    async fn get(&self, namespace: &str, key: &str) -> RuntimeResult<Option<ProfileStateEntry>> {
        validate_profile_state_selector(namespace, key)?;
        Ok(self
            .entries
            .read()
            .await
            .get(&(namespace.to_owned(), key.to_owned()))
            .cloned())
    }

    async fn list(
        &self,
        namespace: &str,
        key_prefix: Option<&str>,
    ) -> RuntimeResult<Vec<ProfileStateEntry>> {
        validate_profile_state_namespace(namespace)?;
        let mut records = self
            .entries
            .read()
            .await
            .values()
            .filter(|entry| entry.namespace == namespace)
            .filter(|entry| key_prefix.is_none_or(|prefix| entry.key.starts_with(prefix)))
            .cloned()
            .collect::<Vec<_>>();
        records.sort_by(|left, right| left.key.cmp(&right.key));
        Ok(records)
    }

    async fn delete(
        &self,
        namespace: &str,
        key: &str,
        expected_revision: u64,
    ) -> RuntimeResult<bool> {
        validate_profile_state_selector(namespace, key)?;
        let mut entries = self.entries.write().await;
        let map_key = (namespace.to_owned(), key.to_owned());
        if entries
            .get(&map_key)
            .is_none_or(|entry| entry.revision != expected_revision)
        {
            return Ok(false);
        }
        entries.remove(&map_key);
        Ok(true)
    }
}

/// Profile-state service backed by a pluggable atomic backend.
#[derive(Clone)]
pub struct ProfileStateStore {
    backend: Arc<dyn ProfileStateBackend>,
}

impl Default for ProfileStateStore {
    fn default() -> Self {
        Self::new(Arc::new(InMemoryProfileStateBackend::default()))
    }
}

impl ProfileStateStore {
    /// Creates a profile-state service.
    #[must_use]
    pub fn new(backend: Arc<dyn ProfileStateBackend>) -> Self {
        Self { backend }
    }

    /// Atomically applies a compare-and-set mutation.
    pub async fn compare_and_set(
        &self,
        namespace: &str,
        key: &str,
        expected_revision: Option<u64>,
        value: Value,
    ) -> RuntimeResult<ProfileStateCasOutcome> {
        self.backend
            .compare_and_set(namespace, key, expected_revision, value)
            .await
    }

    /// Creates a record and returns a conflict without overwriting an existing value.
    pub async fn create(
        &self,
        namespace: &str,
        key: &str,
        value: Value,
    ) -> RuntimeResult<ProfileStateCasOutcome> {
        self.compare_and_set(namespace, key, None, value).await
    }

    /// Upserts a record using optimistic concurrency.
    pub async fn put(
        &self,
        namespace: &str,
        key: &str,
        value: Value,
    ) -> RuntimeResult<ProfileStateEntry> {
        for _ in 0..32 {
            let expected = self.get(namespace, key).await?.map(|entry| entry.revision);
            match self
                .compare_and_set(namespace, key, expected, value.clone())
                .await?
            {
                ProfileStateCasOutcome::Applied(entry) => return Ok(entry),
                ProfileStateCasOutcome::Conflict(_) => tokio::task::yield_now().await,
            }
        }
        Err(RuntimeError::Storage(format!(
            "profile state `{namespace}/{key}` remained contended after 32 CAS attempts"
        )))
    }

    /// Returns one profile-state record.
    pub async fn get(
        &self,
        namespace: &str,
        key: &str,
    ) -> RuntimeResult<Option<ProfileStateEntry>> {
        self.backend.get(namespace, key).await
    }

    /// Lists records in stable key order.
    pub async fn list(
        &self,
        namespace: &str,
        key_prefix: Option<&str>,
    ) -> RuntimeResult<Vec<ProfileStateEntry>> {
        self.backend.list(namespace, key_prefix).await
    }

    /// Deletes a record with revision fencing.
    pub async fn delete(
        &self,
        namespace: &str,
        key: &str,
        expected_revision: u64,
    ) -> RuntimeResult<bool> {
        self.backend.delete(namespace, key, expected_revision).await
    }
}

fn validate_profile_state_namespace(namespace: &str) -> RuntimeResult<()> {
    if namespace.trim().is_empty() || namespace.contains('\0') || namespace.len() > 255 {
        return Err(RuntimeError::Storage(
            "profile state namespace must be 1..=255 characters without NUL".to_owned(),
        ));
    }
    Ok(())
}

fn validate_profile_state_selector(namespace: &str, key: &str) -> RuntimeResult<()> {
    validate_profile_state_namespace(namespace)?;
    if key.trim().is_empty() || key.contains('\0') || key.len() > 1_024 {
        return Err(RuntimeError::Storage(
            "profile state key must be 1..=1024 characters without NUL".to_owned(),
        ));
    }
    Ok(())
}

/// Durable session record containing no bearer token material.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct SessionRecord {
    /// Protocol-visible session.
    pub session: Session,
    /// Principal that owns lifecycle and resume operations.
    pub owner: PrincipalId,
    /// Hex-encoded SHA-256 hash of the current single-use resume token.
    pub resume_token_hash: String,
    /// Resume token expiration.
    pub resume_token_expires_at: OffsetDateTime,
    /// Monotonic token rotation revision.
    pub token_revision: u64,
    /// Whether further resume attempts are revoked.
    pub resume_revoked: bool,
    /// Last durable session update.
    pub updated_at: OffsetDateTime,
}

impl SessionRecord {
    /// Validates a principal-bound token hash without mutating the record.
    pub fn validate_resume(
        &self,
        owner: &PrincipalId,
        presented_hash: &str,
        now: OffsetDateTime,
    ) -> RuntimeResult<()> {
        validate_session_resume(self, owner, presented_hash, now)
    }
}

/// Session and its one-time plaintext resume credential.
#[derive(Clone, Debug, PartialEq)]
pub struct CreatedSession {
    /// Created or resumed session.
    pub session: Session,
    /// Single-use resume token returned only at creation or rotation.
    pub resume_token: String,
    /// Token expiration.
    pub resume_token_expires_at: OffsetDateTime,
}

/// Durable session store contract used by the runtime.
#[async_trait]
pub trait SessionStore: Send + Sync {
    /// Persists a session.
    async fn insert(&self, record: SessionRecord) -> RuntimeResult<()>;
    /// Returns a session by id.
    async fn get(&self, id: &SessionId) -> RuntimeResult<Option<SessionRecord>>;
    /// Returns all known sessions for the operational read model.
    async fn list(&self) -> RuntimeResult<Vec<SessionRecord>>;
    /// Persists an updated session state and returns the new session.
    async fn transition(&self, id: &SessionId, next: SessionState) -> RuntimeResult<SessionRecord>;
    /// Atomically validates and rotates a principal-bound resume token hash.
    async fn rotate_resume_token(
        &self,
        id: &SessionId,
        owner: &PrincipalId,
        presented_hash: &str,
        replacement_hash: String,
        replacement_expires_at: OffsetDateTime,
        now: OffsetDateTime,
    ) -> RuntimeResult<SessionRecord>;
    /// Revokes all current and future resume attempts for a session.
    async fn revoke_resume_token(
        &self,
        id: &SessionId,
        owner: &PrincipalId,
    ) -> RuntimeResult<SessionRecord>;
}

/// In-memory session store for tests, examples, and single-process deployments.
#[derive(Clone, Debug, Default)]
pub struct InMemorySessionStore {
    sessions: Arc<RwLock<HashMap<SessionId, SessionRecord>>>,
}

#[async_trait]
impl SessionStore for InMemorySessionStore {
    async fn insert(&self, record: SessionRecord) -> RuntimeResult<()> {
        let mut sessions = self.sessions.write().await;
        if sessions.contains_key(&record.session.id) {
            return Err(RuntimeError::Storage(format!(
                "session `{}` already exists",
                record.session.id
            )));
        }
        sessions.insert(record.session.id.clone(), record);
        Ok(())
    }

    async fn get(&self, id: &SessionId) -> RuntimeResult<Option<SessionRecord>> {
        Ok(self.sessions.read().await.get(id).cloned())
    }

    async fn list(&self) -> RuntimeResult<Vec<SessionRecord>> {
        let mut sessions = self
            .sessions
            .read()
            .await
            .values()
            .cloned()
            .collect::<Vec<_>>();
        sessions.sort_by_key(|record| record.session.created_at);
        Ok(sessions)
    }

    async fn transition(&self, id: &SessionId, next: SessionState) -> RuntimeResult<SessionRecord> {
        let mut sessions = self.sessions.write().await;
        let record = sessions
            .get_mut(id)
            .ok_or_else(|| RuntimeError::SessionNotFound(id.to_string()))?;
        if !record.session.state.can_transition_to(next) {
            return Err(RuntimeError::Handler(format!(
                "invalid transition from {} to {}",
                record.session.state.as_str(),
                next.as_str()
            )));
        }
        record.session.state = next;
        record.updated_at = OffsetDateTime::now_utc();
        Ok(record.clone())
    }

    async fn rotate_resume_token(
        &self,
        id: &SessionId,
        owner: &PrincipalId,
        presented_hash: &str,
        replacement_hash: String,
        replacement_expires_at: OffsetDateTime,
        now: OffsetDateTime,
    ) -> RuntimeResult<SessionRecord> {
        let mut sessions = self.sessions.write().await;
        let record = sessions
            .get_mut(id)
            .ok_or_else(|| RuntimeError::SessionNotFound(id.to_string()))?;
        validate_session_resume(record, owner, presented_hash, now)?;
        record.resume_token_hash = replacement_hash;
        record.resume_token_expires_at = replacement_expires_at;
        record.token_revision = record.token_revision.saturating_add(1);
        record.updated_at = now;
        Ok(record.clone())
    }

    async fn revoke_resume_token(
        &self,
        id: &SessionId,
        owner: &PrincipalId,
    ) -> RuntimeResult<SessionRecord> {
        let mut sessions = self.sessions.write().await;
        let record = sessions
            .get_mut(id)
            .ok_or_else(|| RuntimeError::SessionNotFound(id.to_string()))?;
        if &record.owner != owner {
            return Err(RuntimeError::Authorization(
                "session owner does not match authenticated principal".to_owned(),
            ));
        }
        record.resume_revoked = true;
        record.token_revision = record.token_revision.saturating_add(1);
        record.updated_at = OffsetDateTime::now_utc();
        Ok(record.clone())
    }
}

/// Session manager backed by a pluggable session store.
#[derive(Clone)]
pub struct SessionManager {
    store: Arc<dyn SessionStore>,
    resume_token_ttl_ms: u64,
}

impl Default for SessionManager {
    fn default() -> Self {
        Self::new(Arc::new(InMemorySessionStore::default()))
    }
}

impl SessionManager {
    /// Creates a session manager backed by the supplied store.
    #[must_use]
    pub fn new(store: Arc<dyn SessionStore>) -> Self {
        Self {
            store,
            resume_token_ttl_ms: 86_400_000,
        }
    }

    /// Overrides the resume-token TTL for a deployment profile.
    #[must_use]
    pub fn with_resume_token_ttl(mut self, ttl_ms: u64) -> Self {
        self.resume_token_ttl_ms = ttl_ms.max(1);
        self
    }

    /// Creates and stores a new active session.
    pub async fn create(
        &self,
        initiator: Principal,
        responder: Principal,
    ) -> RuntimeResult<Session> {
        self.create_secure(initiator, responder)
            .await
            .map(|created| created.session)
    }

    /// Creates a session and returns its initial single-use resume token.
    pub async fn create_secure(
        &self,
        initiator: Principal,
        responder: Principal,
    ) -> RuntimeResult<CreatedSession> {
        let now = OffsetDateTime::now_utc();
        let session = Session {
            id: SessionId::new(),
            state: SessionState::Active,
            created_at: now,
            initiator,
            responder,
        };
        let resume_token = generate_resume_token();
        let resume_token_expires_at = now
            + time::Duration::milliseconds(self.resume_token_ttl_ms.min(i64::MAX as u64) as i64);
        self.store
            .insert(SessionRecord {
                owner: session.initiator.id.clone(),
                session: session.clone(),
                resume_token_hash: hash_resume_token(&resume_token),
                resume_token_expires_at,
                token_revision: 0,
                resume_revoked: false,
                updated_at: now,
            })
            .await?;
        Ok(CreatedSession {
            session,
            resume_token,
            resume_token_expires_at,
        })
    }

    /// Returns a session by id.
    pub async fn get(&self, id: &SessionId) -> RuntimeResult<Option<Session>> {
        Ok(self.store.get(id).await?.map(|record| record.session))
    }

    /// Returns the durable session record including ownership metadata.
    pub async fn get_record(&self, id: &SessionId) -> RuntimeResult<Option<SessionRecord>> {
        self.store.get(id).await
    }

    /// Returns all sessions visible to the runtime store.
    pub async fn list(&self) -> RuntimeResult<Vec<Session>> {
        Ok(self
            .store
            .list()
            .await?
            .into_iter()
            .map(|record| record.session)
            .collect())
    }

    /// Returns all durable records for authorization-aware read APIs.
    pub async fn list_records(&self) -> RuntimeResult<Vec<SessionRecord>> {
        self.store.list().await
    }

    /// Updates a session state if the transition is valid.
    pub async fn transition(&self, id: &SessionId, next: SessionState) -> RuntimeResult<Session> {
        self.store
            .transition(id, next)
            .await
            .map(|record| record.session)
    }

    /// Transitions a session after verifying its authenticated owner.
    pub async fn transition_owned(
        &self,
        id: &SessionId,
        owner: &PrincipalId,
        next: SessionState,
    ) -> RuntimeResult<Session> {
        let record = self
            .store
            .get(id)
            .await?
            .ok_or_else(|| RuntimeError::SessionNotFound(id.to_string()))?;
        if &record.owner != owner {
            return Err(RuntimeError::Authorization(
                "session owner does not match authenticated principal".to_owned(),
            ));
        }
        self.store
            .transition(id, next)
            .await
            .map(|record| record.session)
    }

    /// Verifies and atomically rotates a single-use resume token.
    pub async fn resume(
        &self,
        id: &SessionId,
        owner: &PrincipalId,
        presented_token: &str,
    ) -> RuntimeResult<CreatedSession> {
        if presented_token.trim().is_empty() {
            return Err(RuntimeError::Authorization(
                "session resume token is required".to_owned(),
            ));
        }
        let now = OffsetDateTime::now_utc();
        let replacement = generate_resume_token();
        let replacement_expires_at = now
            + time::Duration::milliseconds(self.resume_token_ttl_ms.min(i64::MAX as u64) as i64);
        let record = self
            .store
            .rotate_resume_token(
                id,
                owner,
                &hash_resume_token(presented_token),
                hash_resume_token(&replacement),
                replacement_expires_at,
                now,
            )
            .await?;
        Ok(CreatedSession {
            session: record.session,
            resume_token: replacement,
            resume_token_expires_at: replacement_expires_at,
        })
    }

    /// Revokes the current resume credential.
    pub async fn revoke_resume(
        &self,
        id: &SessionId,
        owner: &PrincipalId,
    ) -> RuntimeResult<Session> {
        self.store
            .revoke_resume_token(id, owner)
            .await
            .map(|record| record.session)
    }
}

fn generate_resume_token() -> String {
    let mut bytes = [0_u8; 32];
    OsRng.fill_bytes(&mut bytes);
    URL_SAFE_NO_PAD.encode(bytes)
}

fn hash_resume_token(token: &str) -> String {
    hex::encode(Sha256::digest(token.as_bytes()))
}

fn validate_session_resume(
    record: &SessionRecord,
    owner: &PrincipalId,
    presented_hash: &str,
    now: OffsetDateTime,
) -> RuntimeResult<()> {
    if &record.owner != owner {
        return Err(RuntimeError::Authorization(
            "session owner does not match authenticated principal".to_owned(),
        ));
    }
    if record.resume_revoked {
        return Err(RuntimeError::Authorization(
            "session resume credential is revoked".to_owned(),
        ));
    }
    if record.resume_token_expires_at <= now {
        return Err(RuntimeError::Authorization(
            "session resume credential has expired".to_owned(),
        ));
    }
    if !constant_time_eq::constant_time_eq(
        record.resume_token_hash.as_bytes(),
        presented_hash.as_bytes(),
    ) {
        return Err(RuntimeError::Authorization(
            "session resume credential is invalid or already used".to_owned(),
        ));
    }
    Ok(())
}

fn authenticated_session_actor(context: &MessageContext) -> RuntimeResult<PrincipalId> {
    let authenticated = context.authenticated.as_ref().ok_or_else(|| {
        RuntimeError::Authorization(
            "session operations require transport-established identity".to_owned(),
        )
    })?;
    authenticated
        .validate(&BTreeSet::new())
        .map_err(|error| RuntimeError::Authorization(error.to_string()))?;
    Ok(authenticated.principal.id.clone())
}

fn session_record_visible(
    record: &SessionRecord,
    context: &MessageContext,
    actor: &PrincipalId,
) -> bool {
    &record.owner == actor
        || context.authenticated.as_ref().is_some_and(|authenticated| {
            authenticated.scopes.contains("session:read:any") || authenticated.scopes.contains("*")
        })
}

/// Durable metadata for one idempotent action settlement.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct IdempotencyRecord {
    /// Runtime-normalized idempotency key including its declared scope.
    pub key: String,
    /// Scope used to normalize the caller-supplied key.
    pub key_scope: IdempotencyKeyScope,
    /// Action that first claimed the key.
    pub action_id: ActionId,
    /// Capability guarded by the key.
    pub capability_id: CapabilityId,
    /// Principal that first claimed the key.
    pub principal_id: PrincipalId,
    /// Tenant partition, when the scope is tenant-aware.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tenant_id: Option<String>,
    /// External account partition, when the scope is account-aware.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub external_account_id: Option<String>,
    /// Canonical SHA-256 hash of the original action input.
    pub input_hash: String,
    /// Stored result returned or compared on duplicate delivery.
    pub result: ActionResult,
    /// Creation timestamp.
    pub created_at: OffsetDateTime,
    /// Optional expiration timestamp derived from the capability contract.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub expires_at: Option<OffsetDateTime>,
}

/// Durable ownership claim acquired before an idempotent side effect executes.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct IdempotencyReservation {
    /// Fully scoped idempotency key.
    pub key: String,
    /// Unique fencing token for this ownership epoch.
    pub reservation_id: String,
    /// Action that owns the in-flight execution.
    pub action_id: ActionId,
    /// Canonical input hash protected by this reservation.
    pub input_hash: String,
    /// Allows the same action to atomically replace its pending approval settlement.
    #[serde(default)]
    pub resume_pending: bool,
    /// Time when a crashed owner may be replaced.
    pub expires_at: OffsetDateTime,
}

/// Result of an atomic idempotency reservation attempt.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub enum IdempotencyReservationOutcome {
    /// The caller exclusively owns execution for the key.
    Acquired,
    /// A terminal settlement already exists.
    Settled(Box<IdempotencyRecord>),
    /// Another action still owns a live execution reservation.
    InProgress(IdempotencyReservation),
}

impl IdempotencyRecord {
    /// Creates a metadata-light idempotency record for legacy backends.
    #[must_use]
    pub fn legacy(key: String, result: ActionResult) -> Self {
        Self {
            key,
            key_scope: IdempotencyKeyScope::Action,
            action_id: result.action_id.clone(),
            capability_id: CapabilityId::trusted("cap:aip:legacy_idempotency"),
            principal_id: PrincipalId::trusted("system:aip:legacy_idempotency"),
            tenant_id: None,
            external_account_id: None,
            input_hash: String::new(),
            result,
            created_at: OffsetDateTime::now_utc(),
            expires_at: None,
        }
    }
}

/// Idempotency backend for replay-safe action results.
#[async_trait]
pub trait IdempotencyBackend: Send + Sync {
    /// Gets a cached idempotency settlement with scope metadata.
    async fn get_record(&self, key: &str) -> RuntimeResult<Option<IdempotencyRecord>>;
    /// Stores a cached idempotency settlement with scope metadata.
    async fn insert_record(&self, record: IdempotencyRecord) -> RuntimeResult<()>;
    /// Atomically reserves an idempotency key before external execution.
    async fn reserve(
        &self,
        reservation: IdempotencyReservation,
    ) -> RuntimeResult<IdempotencyReservationOutcome>;
    /// Extends a live reservation when the fencing token still owns the key.
    async fn renew_reservation(
        &self,
        reservation: &IdempotencyReservation,
        expires_at: OffsetDateTime,
    ) -> RuntimeResult<bool>;
    /// Atomically replaces a reservation with its terminal settlement.
    async fn settle_reservation(
        &self,
        reservation: &IdempotencyReservation,
        record: IdempotencyRecord,
    ) -> RuntimeResult<()>;
    /// Releases a reservation after an execution failed before producing a result.
    async fn release_reservation(&self, reservation: &IdempotencyReservation) -> RuntimeResult<()>;
}

/// In-memory idempotency backend.
#[derive(Clone, Debug, Default)]
pub struct InMemoryIdempotencyBackend {
    records: Arc<RwLock<HashMap<String, IdempotencyRecord>>>,
    reservations: Arc<RwLock<HashMap<String, IdempotencyReservation>>>,
}

#[async_trait]
impl IdempotencyBackend for InMemoryIdempotencyBackend {
    async fn get_record(&self, key: &str) -> RuntimeResult<Option<IdempotencyRecord>> {
        let Some(record) = self.records.read().await.get(key).cloned() else {
            return Ok(None);
        };
        if idempotency_record_expired(&record) {
            return Ok(None);
        }
        Ok(Some(record))
    }

    async fn insert_record(&self, record: IdempotencyRecord) -> RuntimeResult<()> {
        self.records
            .write()
            .await
            .insert(record.key.clone(), record);
        Ok(())
    }

    async fn reserve(
        &self,
        reservation: IdempotencyReservation,
    ) -> RuntimeResult<IdempotencyReservationOutcome> {
        let mut reservations = self.reservations.write().await;
        let mut records = self.records.write().await;
        if let Some(record) = records.get(&reservation.key).cloned() {
            if idempotency_record_expired(&record) {
                records.remove(&reservation.key);
            } else if reservation_may_resume_pending(&reservation, &record) {
                records.remove(&reservation.key);
                reservations.insert(reservation.key.clone(), reservation);
                return Ok(IdempotencyReservationOutcome::Acquired);
            } else {
                return Ok(IdempotencyReservationOutcome::Settled(Box::new(record)));
            }
        }
        if let Some(existing) = reservations.get(&reservation.key)
            && existing.expires_at > OffsetDateTime::now_utc()
        {
            return Ok(IdempotencyReservationOutcome::InProgress(existing.clone()));
        }
        reservations.insert(reservation.key.clone(), reservation);
        Ok(IdempotencyReservationOutcome::Acquired)
    }

    async fn settle_reservation(
        &self,
        reservation: &IdempotencyReservation,
        record: IdempotencyRecord,
    ) -> RuntimeResult<()> {
        let mut reservations = self.reservations.write().await;
        let current = reservations.get(&reservation.key).ok_or_else(|| {
            RuntimeError::Storage(format!(
                "idempotency reservation `{}` is missing",
                reservation.key
            ))
        })?;
        if current.reservation_id != reservation.reservation_id {
            return Err(RuntimeError::Storage(format!(
                "idempotency reservation `{}` changed fencing token",
                reservation.key,
            )));
        }
        self.records
            .write()
            .await
            .insert(record.key.clone(), record);
        reservations.remove(&reservation.key);
        Ok(())
    }

    async fn renew_reservation(
        &self,
        reservation: &IdempotencyReservation,
        expires_at: OffsetDateTime,
    ) -> RuntimeResult<bool> {
        let mut reservations = self.reservations.write().await;
        let Some(current) = reservations.get_mut(&reservation.key) else {
            return Ok(false);
        };
        if current.reservation_id != reservation.reservation_id
            || current.action_id != reservation.action_id
        {
            return Ok(false);
        }
        current.expires_at = expires_at;
        Ok(true)
    }

    async fn release_reservation(&self, reservation: &IdempotencyReservation) -> RuntimeResult<()> {
        let mut reservations = self.reservations.write().await;
        if reservations
            .get(&reservation.key)
            .is_some_and(|current| current.reservation_id == reservation.reservation_id)
        {
            reservations.remove(&reservation.key);
        }
        Ok(())
    }
}

/// Idempotency store backed by a pluggable backend.
#[derive(Clone)]
pub struct IdempotencyStore {
    backend: Arc<dyn IdempotencyBackend>,
}

impl Default for IdempotencyStore {
    fn default() -> Self {
        Self::new(Arc::new(InMemoryIdempotencyBackend::default()))
    }
}

impl IdempotencyStore {
    /// Creates an idempotency store backed by the supplied backend.
    #[must_use]
    pub fn new(backend: Arc<dyn IdempotencyBackend>) -> Self {
        Self { backend }
    }

    /// Gets a cached idempotency settlement.
    pub async fn get_record(&self, key: &str) -> RuntimeResult<Option<IdempotencyRecord>> {
        let Some(record) = self.backend.get_record(key).await? else {
            return Ok(None);
        };
        if idempotency_record_expired(&record) {
            return Ok(None);
        }
        Ok(Some(record))
    }

    /// Stores a cached idempotency settlement.
    pub async fn insert_record(&self, record: IdempotencyRecord) -> RuntimeResult<()> {
        self.backend.insert_record(record).await
    }

    /// Gets a cached action result.
    pub async fn get(&self, key: &str) -> RuntimeResult<Option<ActionResult>> {
        Ok(self.get_record(key).await?.map(|record| record.result))
    }

    /// Stores a result for an idempotency key.
    pub async fn insert(&self, key: String, result: ActionResult) -> RuntimeResult<()> {
        self.insert_record(IdempotencyRecord::legacy(key, result))
            .await
    }

    /// Atomically reserves a key before execution.
    pub async fn reserve(
        &self,
        reservation: IdempotencyReservation,
    ) -> RuntimeResult<IdempotencyReservationOutcome> {
        self.backend.reserve(reservation).await
    }

    /// Atomically stores a settlement owned by a reservation.
    pub async fn settle_reservation(
        &self,
        reservation: &IdempotencyReservation,
        record: IdempotencyRecord,
    ) -> RuntimeResult<()> {
        self.backend.settle_reservation(reservation, record).await
    }

    /// Extends an owned reservation and returns `false` when fencing ownership was lost.
    pub async fn renew_reservation(
        &self,
        reservation: &IdempotencyReservation,
        expires_at: OffsetDateTime,
    ) -> RuntimeResult<bool> {
        self.backend
            .renew_reservation(reservation, expires_at)
            .await
    }

    /// Releases a reservation that did not reach a terminal result.
    pub async fn release_reservation(
        &self,
        reservation: &IdempotencyReservation,
    ) -> RuntimeResult<()> {
        self.backend.release_reservation(reservation).await
    }
}

/// Maximum compact JSON bytes retained for one event.
///
/// Storage implementations reject records above
/// [`MAX_EVENT_RECORD_BYTES`] and keep every returned page within
/// [`MAX_EVENT_PAGE_BYTES`]. These implementation limits do not change the AIP
/// wire schema or accept an untrusted client-supplied byte budget.
pub const MAX_EVENT_RECORD_BYTES: usize = 256 * 1024;
/// Maximum serialized event bytes materialized in one event page.
pub const MAX_EVENT_PAGE_BYTES: usize = 4 * 1024 * 1024;
/// Maximum event rows materialized in one event page.
pub const MAX_EVENT_PAGE_ROWS: usize = 1_000;

/// Validates and returns the compact JSON size of one retained event.
pub fn validate_event_record_size(event: &Event) -> RuntimeResult<usize> {
    let bytes = serde_json::to_vec(event).map_err(|error| {
        RuntimeError::Storage(format!(
            "event serialization failed before storage: {error}"
        ))
    })?;
    if bytes.len() > MAX_EVENT_RECORD_BYTES {
        return Err(RuntimeError::Protocol(ProtocolError {
            code: "stream.event_too_large".to_owned(),
            message: format!(
                "event `{}` is {} bytes; maximum is {MAX_EVENT_RECORD_BYTES}",
                event.id,
                bytes.len()
            ),
            category: ErrorCategory::Permanent,
            retryable: Some(false),
            retry_after_ms: None,
            details: Some(Box::new(json!({
                "event_id": event.id,
                "actual_bytes": bytes.len(),
                "maximum_bytes": MAX_EVENT_RECORD_BYTES
            }))),
            source: Some(Box::new(json!({ "component": "aip-runtime.events" }))),
        }));
    }
    Ok(bytes.len())
}

/// Result of one atomic append keyed by the event id.
#[derive(Clone, Debug, PartialEq)]
pub enum EventAppendOutcome {
    /// The event id was durably inserted for the first time.
    Inserted(Event),
    /// The event id already existed and the stored event was returned.
    Replayed(Event),
}

impl EventAppendOutcome {
    /// Borrows the durable event regardless of whether it was inserted or replayed.
    #[must_use]
    pub const fn event(&self) -> &Event {
        match self {
            Self::Inserted(event) | Self::Replayed(event) => event,
        }
    }

    /// Returns the durable event regardless of whether it was inserted or replayed.
    #[must_use]
    pub fn into_event(self) -> Event {
        match self {
            Self::Inserted(event) | Self::Replayed(event) => event,
        }
    }

    /// Reports whether this call inserted the durable event.
    #[must_use]
    pub const fn is_inserted(&self) -> bool {
        matches!(self, Self::Inserted(_))
    }
}

/// Append-only event store contract with cursor-based, byte-bounded reads.
#[async_trait]
pub trait EventStore: Send + Sync {
    /// Appends an event and returns the stored value.
    async fn append(&self, event: Event) -> RuntimeResult<Event>;
    /// Atomically appends an event or returns the value already stored under
    /// the same event id.
    ///
    /// Backends that support durable event-id uniqueness should override this
    /// method so callers can distinguish an insert from an idempotent replay.
    async fn append_with_outcome(&self, event: Event) -> RuntimeResult<EventAppendOutcome> {
        self.append(event).await.map(EventAppendOutcome::Inserted)
    }
    /// Returns events after the request cursor, applying kind filters and limit.
    async fn stream(&self, request: &EventStreamRequest) -> RuntimeResult<EventStream>;
    /// Returns events after validating cursor syntax and replay bounds.
    async fn stream_checked(&self, request: &EventStreamRequest) -> RuntimeResult<EventStream> {
        self.stream(request).await
    }
    /// Returns tenant-scoped events with filtering applied by the storage
    /// backend before response materialization.
    async fn stream_tenant_checked(
        &self,
        tenant_id: &str,
        request: &EventStreamRequest,
    ) -> RuntimeResult<EventStream>;
    /// Returns action-scoped events with filtering applied before pagination.
    async fn stream_action_checked(
        &self,
        action_id: &ActionId,
        request: &EventStreamRequest,
    ) -> RuntimeResult<EventStream>;
}

/// In-memory event store.
#[derive(Clone, Debug, Default)]
pub struct InMemoryEventStore {
    events: Arc<RwLock<Vec<Event>>>,
}

#[async_trait]
impl EventStore for InMemoryEventStore {
    async fn append(&self, event: Event) -> RuntimeResult<Event> {
        self.append_with_outcome(event)
            .await
            .map(EventAppendOutcome::into_event)
    }

    async fn append_with_outcome(&self, event: Event) -> RuntimeResult<EventAppendOutcome> {
        validate_event_record_size(&event)?;
        let mut events = self.events.write().await;
        if let Some(existing) = events.iter().find(|existing| existing.id == event.id) {
            return Ok(EventAppendOutcome::Replayed(existing.clone()));
        }
        events.push(event.clone());
        Ok(EventAppendOutcome::Inserted(event))
    }

    async fn stream(&self, request: &EventStreamRequest) -> RuntimeResult<EventStream> {
        let events = self.events.read().await;
        select_events(&events, request).map_err(|error| RuntimeError::Protocol(*error))
    }

    async fn stream_checked(&self, request: &EventStreamRequest) -> RuntimeResult<EventStream> {
        let events = self.events.read().await;
        select_events_checked(&events, request).map_err(|error| RuntimeError::Protocol(*error))
    }

    async fn stream_tenant_checked(
        &self,
        tenant_id: &str,
        request: &EventStreamRequest,
    ) -> RuntimeResult<EventStream> {
        let events = self.events.read().await;
        select_tenant_events_checked(&events, tenant_id, request)
            .map_err(|error| RuntimeError::Protocol(*error))
    }

    async fn stream_action_checked(
        &self,
        action_id: &ActionId,
        request: &EventStreamRequest,
    ) -> RuntimeResult<EventStream> {
        let events = self.events.read().await;
        select_action_events_checked(&events, action_id, request)
            .map_err(|error| RuntimeError::Protocol(*error))
    }
}

/// Append-only event log backed by a pluggable event store.
#[derive(Clone)]
pub struct EventLog {
    store: Arc<dyn EventStore>,
}

impl Default for EventLog {
    fn default() -> Self {
        Self::new(Arc::new(InMemoryEventStore::default()))
    }
}

impl EventLog {
    /// Creates an event log backed by the supplied store.
    #[must_use]
    pub fn new(store: Arc<dyn EventStore>) -> Self {
        Self { store }
    }

    /// Appends an event and returns the stored value.
    pub async fn append(&self, event: Event) -> RuntimeResult<Event> {
        self.store.append(event).await
    }

    /// Atomically appends an event and reports whether it was newly inserted
    /// or was an idempotent replay of an existing event id.
    pub async fn append_with_outcome(&self, event: Event) -> RuntimeResult<EventAppendOutcome> {
        self.store.append_with_outcome(event).await
    }

    /// Returns events after the request cursor, applying kind filters and limit.
    pub async fn stream(&self, request: &EventStreamRequest) -> RuntimeResult<EventStream> {
        self.store.stream(request).await
    }

    /// Returns events after validating cursor syntax and replay bounds.
    pub async fn stream_checked(&self, request: &EventStreamRequest) -> RuntimeResult<EventStream> {
        self.store.stream_checked(request).await
    }

    /// Returns tenant-scoped events with storage-native filtering.
    pub async fn stream_tenant_checked(
        &self,
        tenant_id: &str,
        request: &EventStreamRequest,
    ) -> RuntimeResult<EventStream> {
        self.store.stream_tenant_checked(tenant_id, request).await
    }

    /// Returns action-scoped events with storage-native pagination.
    pub async fn stream_action_checked(
        &self,
        action_id: &ActionId,
        request: &EventStreamRequest,
    ) -> RuntimeResult<EventStream> {
        self.store.stream_action_checked(action_id, request).await
    }
}

fn parse_cursor(cursor: &str) -> Option<usize> {
    cursor
        .strip_prefix("evt_cursor_")
        .unwrap_or(cursor)
        .parse::<usize>()
        .ok()
}

fn parse_event_cursor_checked(cursor: &str) -> Result<usize, Box<ProtocolError>> {
    let Some(value) = cursor.strip_prefix("evt_cursor_") else {
        return Err(Box::new(cursor_error(
            "query.invalid_cursor",
            format!("event cursor `{cursor}` must use `evt_cursor_<offset>` format"),
            Some(json!({ "cursor": cursor, "expected_prefix": "evt_cursor_" })),
        )));
    };
    value.parse::<usize>().map_err(|_| {
        Box::new(cursor_error(
            "query.invalid_cursor",
            format!("event cursor `{cursor}` contains a non-numeric offset"),
            Some(json!({ "cursor": cursor })),
        ))
    })
}

fn format_cursor(index: usize) -> String {
    format!("evt_cursor_{index}")
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct ActionEventsCursor {
    event_cursor: Option<String>,
    chunk_sequence: Option<u64>,
}

fn parse_action_events_cursor(cursor: Option<&str>) -> Result<ActionEventsCursor, ProtocolError> {
    let Some(cursor) = cursor else {
        return Ok(ActionEventsCursor::default());
    };
    if cursor.starts_with("evt_cursor_") {
        parse_event_cursor_checked(cursor).map_err(|error| *error)?;
        return Ok(ActionEventsCursor {
            event_cursor: Some(cursor.to_owned()),
            chunk_sequence: None,
        });
    }
    let rest = cursor.strip_prefix("aev_cursor_").ok_or_else(|| {
        cursor_error(
            "query.invalid_cursor",
            "action event cursor must use `aev_cursor_<event>_<chunk>` format".to_owned(),
            Some(json!({ "cursor": cursor })),
        )
    })?;
    let (event_offset, chunk_sequence) = rest.rsplit_once('_').ok_or_else(|| {
        cursor_error(
            "query.invalid_cursor",
            "action event cursor is missing its chunk sequence".to_owned(),
            Some(json!({ "cursor": cursor })),
        )
    })?;
    let event_offset = event_offset.parse::<usize>().map_err(|_| {
        cursor_error(
            "query.invalid_cursor",
            "action event cursor contains an invalid event offset".to_owned(),
            Some(json!({ "cursor": cursor })),
        )
    })?;
    let chunk_sequence = if chunk_sequence == "none" {
        None
    } else {
        Some(chunk_sequence.parse::<u64>().map_err(|_| {
            cursor_error(
                "query.invalid_cursor",
                "action event cursor contains an invalid chunk sequence".to_owned(),
                Some(json!({ "cursor": cursor })),
            )
        })?)
    };
    Ok(ActionEventsCursor {
        event_cursor: Some(format_cursor(event_offset)),
        chunk_sequence,
    })
}

fn format_action_events_cursor(event_cursor: Option<&str>, chunk_sequence: Option<u64>) -> String {
    let event_offset = event_cursor.and_then(parse_cursor).unwrap_or_default();
    let chunk_sequence =
        chunk_sequence.map_or_else(|| "none".to_owned(), |value| value.to_string());
    format!("aev_cursor_{event_offset}_{chunk_sequence}")
}

fn select_events(
    events: &[Event],
    request: &EventStreamRequest,
) -> Result<EventStream, Box<ProtocolError>> {
    let start = request
        .cursor
        .as_deref()
        .and_then(parse_cursor)
        .unwrap_or(0)
        .min(events.len());
    let limit = request
        .limit
        .unwrap_or(100)
        .clamp(1, MAX_EVENT_PAGE_ROWS as u32) as usize;
    let mut selected = Vec::new();
    let mut next_index = start;
    let mut page_bytes = 0_usize;
    for (index, event) in events.iter().enumerate().skip(start) {
        if !request.kinds.is_empty() && !request.kinds.contains(&event.kind) {
            next_index = index + 1;
            continue;
        }
        let event_bytes = validate_event_record_size(event).map_err(runtime_event_size_error)?;
        if page_bytes.saturating_add(event_bytes) > MAX_EVENT_PAGE_BYTES {
            break;
        }
        page_bytes = page_bytes.saturating_add(event_bytes);
        selected.push(event.clone());
        next_index = index + 1;
        if selected.len() == limit {
            break;
        }
    }
    Ok(EventStream {
        events: selected,
        next_cursor: Some(format_cursor(next_index)),
    })
}

fn select_events_checked(
    events: &[Event],
    request: &EventStreamRequest,
) -> Result<EventStream, Box<ProtocolError>> {
    if let Some(cursor) = request.cursor.as_deref() {
        let offset = parse_event_cursor_checked(cursor)?;
        if offset > events.len() {
            return Err(Box::new(cursor_error(
                "stream.cursor_expired",
                format!("event cursor `{cursor}` is outside the retained replay window"),
                Some(json!({
                    "cursor": cursor,
                    "available_events": events.len()
                })),
            )));
        }
    }
    select_events(events, request)
}

fn select_tenant_events_checked(
    events: &[Event],
    tenant_id: &str,
    request: &EventStreamRequest,
) -> Result<EventStream, Box<ProtocolError>> {
    let start = match request.cursor.as_deref() {
        Some(cursor) => parse_event_cursor_checked(cursor)?,
        None => 0,
    };
    if start > events.len() {
        return Err(Box::new(cursor_error(
            "stream.cursor_expired",
            "tenant event cursor is outside the retained replay window".to_owned(),
            Some(json!({ "cursor": request.cursor, "available_events": events.len() })),
        )));
    }
    let limit = request
        .limit
        .unwrap_or(100)
        .clamp(1, MAX_EVENT_PAGE_ROWS as u32) as usize;
    let mut selected = Vec::new();
    let mut next_index = start;
    let mut page_bytes = 0_usize;
    for (index, event) in events.iter().enumerate().skip(start) {
        if event
            .data
            .as_ref()
            .and_then(|data| data.pointer("/identity/tenant/id"))
            .and_then(Value::as_str)
            != Some(tenant_id)
        {
            next_index = index + 1;
            continue;
        }
        if !request.kinds.is_empty() && !request.kinds.contains(&event.kind) {
            next_index = index + 1;
            continue;
        }
        let event_bytes = validate_event_record_size(event).map_err(runtime_event_size_error)?;
        if page_bytes.saturating_add(event_bytes) > MAX_EVENT_PAGE_BYTES {
            break;
        }
        page_bytes = page_bytes.saturating_add(event_bytes);
        selected.push(event.clone());
        next_index = index + 1;
        if selected.len() == limit {
            break;
        }
    }
    Ok(EventStream {
        events: selected,
        next_cursor: Some(format_cursor(next_index)),
    })
}

fn select_action_events_checked(
    events: &[Event],
    action_id: &ActionId,
    request: &EventStreamRequest,
) -> Result<EventStream, Box<ProtocolError>> {
    let start = match request.cursor.as_deref() {
        Some(cursor) => parse_event_cursor_checked(cursor)?,
        None => 0,
    };
    if start > events.len() {
        return Err(Box::new(cursor_error(
            "stream.cursor_expired",
            "action event cursor is outside the retained replay window".to_owned(),
            Some(json!({ "cursor": request.cursor, "available_events": events.len() })),
        )));
    }
    let limit = request
        .limit
        .unwrap_or(100)
        .clamp(1, MAX_EVENT_PAGE_ROWS as u32) as usize;
    let mut selected = Vec::new();
    let mut next_index = start;
    let mut page_bytes = 0_usize;
    for (index, event) in events.iter().enumerate().skip(start) {
        if event.action_id.as_ref() != Some(action_id) {
            next_index = index + 1;
            continue;
        }
        if !request.kinds.is_empty() && !request.kinds.contains(&event.kind) {
            next_index = index + 1;
            continue;
        }
        let event_bytes = validate_event_record_size(event).map_err(runtime_event_size_error)?;
        if page_bytes.saturating_add(event_bytes) > MAX_EVENT_PAGE_BYTES {
            break;
        }
        page_bytes = page_bytes.saturating_add(event_bytes);
        selected.push(event.clone());
        next_index = index + 1;
        if selected.len() == limit {
            break;
        }
    }
    Ok(EventStream {
        events: selected,
        next_cursor: Some(format_cursor(next_index)),
    })
}

fn runtime_event_size_error(error: RuntimeError) -> Box<ProtocolError> {
    match error {
        RuntimeError::Protocol(error) => Box::new(error),
        other => Box::new(ProtocolError {
            code: "stream.event_encoding_failed".to_owned(),
            message: other.to_string(),
            category: ErrorCategory::Permanent,
            retryable: Some(false),
            retry_after_ms: None,
            details: None,
            source: Some(Box::new(json!({ "component": "aip-runtime.events" }))),
        }),
    }
}

/// Durable lifecycle backend used by the runtime for action, channel, audit, and settlement state.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StreamChunkRecordOutcome {
    /// The sequence was durably inserted for the first time.
    Inserted,
    /// The exact same sequence and content were already durable.
    Replayed,
}

/// Classifies a stream-chunk insert against one atomically locked action log.
pub fn classify_stream_chunk_record(
    existing_chunks: &[StreamChunk],
    chunk: &StreamChunk,
) -> RuntimeResult<StreamChunkRecordOutcome> {
    if let Some(existing) = existing_chunks
        .iter()
        .find(|existing| existing.sequence == chunk.sequence)
    {
        if existing == chunk {
            return Ok(StreamChunkRecordOutcome::Replayed);
        }
        return Err(RuntimeError::Authorization(format!(
            "stream sequence `{}` for action `{}` conflicts with an already recorded chunk",
            chunk.sequence, chunk.action_id
        )));
    }
    if let Some(previous) = existing_chunks
        .iter()
        .max_by_key(|existing| existing.sequence)
    {
        if matches!(
            previous.kind,
            StreamChunkKind::Done | StreamChunkKind::Error
        ) {
            return Err(RuntimeError::Authorization(format!(
                "stream for action `{}` is already terminal",
                chunk.action_id
            )));
        }
        if chunk.sequence <= previous.sequence {
            return Err(RuntimeError::Authorization(format!(
                "stream sequence `{}` for action `{}` is not greater than the previous sequence `{}`",
                chunk.sequence, chunk.action_id, previous.sequence
            )));
        }
    }
    Ok(StreamChunkRecordOutcome::Inserted)
}

#[async_trait]
/// Persists action lifecycle state behind the runtime's storage boundary.
pub trait LifecycleBackend: Send + Sync {
    /// Returns the last known result for an action.
    async fn action_result(&self, action_id: &ActionId) -> RuntimeResult<Option<ActionResult>>;
    /// Returns all persisted action results for the operational read model.
    async fn action_results(&self) -> RuntimeResult<Vec<ActionResult>>;
    /// Returns stored stream chunks for an action.
    async fn stream_chunks(&self, action_id: &ActionId) -> RuntimeResult<Vec<StreamChunk>>;
    /// Records a cancelled action.
    async fn cancel_action(&self, action_id: ActionId, reason: Option<String>)
    -> RuntimeResult<()>;
    /// Atomically records or identifies an idempotent stream-chunk replay.
    async fn record_stream_chunk(
        &self,
        chunk: StreamChunk,
    ) -> RuntimeResult<StreamChunkRecordOutcome>;
    /// Records an action result.
    async fn record_action_result(&self, result: ActionResult) -> RuntimeResult<()>;
    /// Records a human escalation request.
    async fn record_escalation(&self, escalation: Escalation) -> RuntimeResult<()>;
    /// Records a human escalation resolution.
    async fn record_escalation_resolution(
        &self,
        resolution: EscalationResolution,
    ) -> RuntimeResult<()>;
    /// Records a channel conversation.
    async fn record_conversation(&self, conversation: Conversation) -> RuntimeResult<()>;
    /// Records a receipt chain.
    async fn record_receipt_chain(&self, chain: ReceiptChain) -> RuntimeResult<()>;
    /// Returns one receipt chain by id.
    async fn receipt_chain(&self, chain_id: &str) -> RuntimeResult<Option<ReceiptChain>> {
        let _ = chain_id;
        Ok(None)
    }
    /// Returns all receipt chains for operational queries.
    async fn receipt_chains(&self) -> RuntimeResult<Vec<ReceiptChain>> {
        Ok(Vec::new())
    }
    /// Records an audit event.
    async fn record_audit_event(&self, audit: AuditEvent) -> RuntimeResult<()>;
    /// Returns one audit event by its stable id.
    async fn audit_event(&self, audit_id: &str) -> RuntimeResult<Option<AuditEvent>> {
        let _ = audit_id;
        Ok(None)
    }
    /// Returns all audit events for operational queries.
    async fn audit_events(&self) -> RuntimeResult<Vec<AuditEvent>> {
        Ok(Vec::new())
    }
    /// Records an economic settlement batch.
    async fn record_settlement(&self, settlement: BatchSettlement) -> RuntimeResult<()>;
}

/// In-memory lifecycle backend for tests, examples, and single-process deployments.
#[derive(Clone, Debug, Default)]
pub struct InMemoryLifecycleBackend {
    stream_chunks: Arc<RwLock<HashMap<ActionId, Vec<StreamChunk>>>>,
    action_results: Arc<RwLock<HashMap<ActionId, ActionResult>>>,
    cancelled_actions: Arc<RwLock<HashMap<ActionId, Option<String>>>>,
    escalations: Arc<RwLock<Vec<Escalation>>>,
    escalation_resolutions: Arc<RwLock<Vec<EscalationResolution>>>,
    conversations: Arc<RwLock<HashMap<ConversationId, Conversation>>>,
    receipt_chains: Arc<RwLock<HashMap<String, ReceiptChain>>>,
    audit_events: Arc<RwLock<HashMap<String, AuditEvent>>>,
    settlements: Arc<RwLock<HashMap<String, BatchSettlement>>>,
}

#[async_trait]
impl LifecycleBackend for InMemoryLifecycleBackend {
    async fn action_result(&self, action_id: &ActionId) -> RuntimeResult<Option<ActionResult>> {
        Ok(self.action_results.read().await.get(action_id).cloned())
    }

    async fn action_results(&self) -> RuntimeResult<Vec<ActionResult>> {
        let mut results = self
            .action_results
            .read()
            .await
            .values()
            .cloned()
            .collect::<Vec<_>>();
        results.sort_by(|left, right| left.action_id.cmp(&right.action_id));
        Ok(results)
    }

    async fn stream_chunks(&self, action_id: &ActionId) -> RuntimeResult<Vec<StreamChunk>> {
        Ok(self
            .stream_chunks
            .read()
            .await
            .get(action_id)
            .cloned()
            .unwrap_or_default())
    }

    async fn cancel_action(
        &self,
        action_id: ActionId,
        reason: Option<String>,
    ) -> RuntimeResult<()> {
        self.cancelled_actions
            .write()
            .await
            .insert(action_id, reason);
        Ok(())
    }

    async fn record_stream_chunk(
        &self,
        chunk: StreamChunk,
    ) -> RuntimeResult<StreamChunkRecordOutcome> {
        let mut stream_chunks = self.stream_chunks.write().await;
        let chunks = stream_chunks.entry(chunk.action_id.clone()).or_default();
        let outcome = classify_stream_chunk_record(chunks, &chunk)?;
        if outcome == StreamChunkRecordOutcome::Inserted {
            chunks.push(chunk);
        }
        Ok(outcome)
    }

    async fn record_action_result(&self, result: ActionResult) -> RuntimeResult<()> {
        self.action_results
            .write()
            .await
            .insert(result.action_id.clone(), result);
        Ok(())
    }

    async fn record_escalation(&self, escalation: Escalation) -> RuntimeResult<()> {
        self.escalations.write().await.push(escalation);
        Ok(())
    }

    async fn record_escalation_resolution(
        &self,
        resolution: EscalationResolution,
    ) -> RuntimeResult<()> {
        self.escalation_resolutions.write().await.push(resolution);
        Ok(())
    }

    async fn record_conversation(&self, conversation: Conversation) -> RuntimeResult<()> {
        self.conversations
            .write()
            .await
            .insert(conversation.id.clone(), conversation);
        Ok(())
    }

    async fn record_receipt_chain(&self, chain: ReceiptChain) -> RuntimeResult<()> {
        self.receipt_chains
            .write()
            .await
            .insert(chain.chain_id.clone(), chain);
        Ok(())
    }

    async fn receipt_chain(&self, chain_id: &str) -> RuntimeResult<Option<ReceiptChain>> {
        Ok(self.receipt_chains.read().await.get(chain_id).cloned())
    }

    async fn receipt_chains(&self) -> RuntimeResult<Vec<ReceiptChain>> {
        let mut chains = self
            .receipt_chains
            .read()
            .await
            .values()
            .cloned()
            .collect::<Vec<_>>();
        chains.sort_by(|left, right| left.chain_id.cmp(&right.chain_id));
        Ok(chains)
    }

    async fn record_audit_event(&self, audit: AuditEvent) -> RuntimeResult<()> {
        self.audit_events
            .write()
            .await
            .insert(audit.id.clone(), audit);
        Ok(())
    }

    async fn audit_event(&self, audit_id: &str) -> RuntimeResult<Option<AuditEvent>> {
        Ok(self.audit_events.read().await.get(audit_id).cloned())
    }

    async fn audit_events(&self) -> RuntimeResult<Vec<AuditEvent>> {
        let mut events = self
            .audit_events
            .read()
            .await
            .values()
            .cloned()
            .collect::<Vec<_>>();
        events.sort_by_key(|event| event.occurred_at);
        Ok(events)
    }

    async fn record_settlement(&self, settlement: BatchSettlement) -> RuntimeResult<()> {
        self.settlements
            .write()
            .await
            .insert(settlement.id.clone(), settlement);
        Ok(())
    }
}

/// Lifecycle store backed by a pluggable backend.
#[derive(Clone)]
pub struct LifecycleStore {
    backend: Arc<dyn LifecycleBackend>,
}

impl Default for LifecycleStore {
    fn default() -> Self {
        Self::new(Arc::new(InMemoryLifecycleBackend::default()))
    }
}

impl LifecycleStore {
    /// Creates a lifecycle store backed by the supplied backend.
    #[must_use]
    pub fn new(backend: Arc<dyn LifecycleBackend>) -> Self {
        Self { backend }
    }

    /// Returns the last known result for an action.
    pub async fn action_result(&self, action_id: &ActionId) -> RuntimeResult<Option<ActionResult>> {
        self.backend.action_result(action_id).await
    }

    /// Returns all persisted action results for the operational read model.
    pub async fn action_results(&self) -> RuntimeResult<Vec<ActionResult>> {
        self.backend.action_results().await
    }

    /// Returns the stored chunks for an action.
    pub async fn stream_chunks(&self, action_id: &ActionId) -> RuntimeResult<Vec<StreamChunk>> {
        self.backend.stream_chunks(action_id).await
    }

    /// Records a cancelled action.
    pub async fn cancel_action(
        &self,
        action_id: ActionId,
        reason: Option<String>,
    ) -> RuntimeResult<()> {
        self.backend.cancel_action(action_id, reason).await
    }

    /// Atomically records or identifies an idempotent stream-chunk replay.
    pub async fn record_stream_chunk(
        &self,
        chunk: StreamChunk,
    ) -> RuntimeResult<StreamChunkRecordOutcome> {
        self.backend.record_stream_chunk(chunk).await
    }

    /// Records an action result.
    pub async fn record_action_result(&self, result: ActionResult) -> RuntimeResult<()> {
        self.backend.record_action_result(result).await
    }

    /// Records a human escalation request.
    pub async fn record_escalation(&self, escalation: Escalation) -> RuntimeResult<()> {
        self.backend.record_escalation(escalation).await
    }

    /// Records a human escalation resolution.
    pub async fn record_escalation_resolution(
        &self,
        resolution: EscalationResolution,
    ) -> RuntimeResult<()> {
        self.backend.record_escalation_resolution(resolution).await
    }

    /// Records a channel conversation.
    pub async fn record_conversation(&self, conversation: Conversation) -> RuntimeResult<()> {
        self.backend.record_conversation(conversation).await
    }

    /// Records a receipt chain.
    pub async fn record_receipt_chain(&self, chain: ReceiptChain) -> RuntimeResult<()> {
        self.backend.record_receipt_chain(chain).await
    }

    /// Returns one receipt chain by id.
    pub async fn receipt_chain(&self, chain_id: &str) -> RuntimeResult<Option<ReceiptChain>> {
        self.backend.receipt_chain(chain_id).await
    }

    /// Returns all receipt chains.
    pub async fn receipt_chains(&self) -> RuntimeResult<Vec<ReceiptChain>> {
        self.backend.receipt_chains().await
    }

    /// Records an audit event.
    pub async fn record_audit_event(&self, audit: AuditEvent) -> RuntimeResult<()> {
        self.backend.record_audit_event(audit).await
    }

    /// Returns one audit event by its stable id.
    pub async fn audit_event(&self, audit_id: &str) -> RuntimeResult<Option<AuditEvent>> {
        self.backend.audit_event(audit_id).await
    }

    /// Returns all audit events.
    pub async fn audit_events(&self) -> RuntimeResult<Vec<AuditEvent>> {
        self.backend.audit_events().await
    }

    /// Records an economic settlement batch.
    pub async fn record_settlement(&self, settlement: BatchSettlement) -> RuntimeResult<()> {
        self.backend.record_settlement(settlement).await
    }
}

/// Durable delegation graph backend used by the runtime scheduler.
#[async_trait]
pub trait DelegationBackend: Send + Sync {
    /// Inserts or replaces a delegation graph record.
    async fn upsert(&self, record: DelegationRecord) -> RuntimeResult<()>;
    /// Returns a delegation record by id.
    async fn get(&self, delegation_id: &DelegationId) -> RuntimeResult<Option<DelegationRecord>>;
    /// Returns child delegations for a parent action.
    async fn children(&self, parent_action_id: &ActionId) -> RuntimeResult<Vec<DelegationRecord>>;
    /// Returns the delegation record that owns a child action.
    async fn by_child_action(
        &self,
        child_action_id: &ActionId,
    ) -> RuntimeResult<Option<DelegationRecord>>;
    /// Returns delegations that still need terminal settlement.
    async fn running(&self) -> RuntimeResult<Vec<DelegationRecord>>;
}

/// In-memory delegation graph backend for tests and single-process deployments.
#[derive(Clone, Debug, Default)]
pub struct InMemoryDelegationBackend {
    records: Arc<RwLock<HashMap<DelegationId, DelegationRecord>>>,
}

#[async_trait]
impl DelegationBackend for InMemoryDelegationBackend {
    async fn upsert(&self, record: DelegationRecord) -> RuntimeResult<()> {
        self.records
            .write()
            .await
            .insert(record.request.delegation_id.clone(), record);
        Ok(())
    }

    async fn get(&self, delegation_id: &DelegationId) -> RuntimeResult<Option<DelegationRecord>> {
        Ok(self.records.read().await.get(delegation_id).cloned())
    }

    async fn children(&self, parent_action_id: &ActionId) -> RuntimeResult<Vec<DelegationRecord>> {
        Ok(self
            .records
            .read()
            .await
            .values()
            .filter(|record| record.request.parent_action_id == *parent_action_id)
            .cloned()
            .collect())
    }

    async fn by_child_action(
        &self,
        child_action_id: &ActionId,
    ) -> RuntimeResult<Option<DelegationRecord>> {
        Ok(self
            .records
            .read()
            .await
            .values()
            .find(|record| record.request.child_action.id == *child_action_id)
            .cloned())
    }

    async fn running(&self) -> RuntimeResult<Vec<DelegationRecord>> {
        Ok(self
            .records
            .read()
            .await
            .values()
            .filter(|record| {
                matches!(
                    record.status,
                    DelegationStatus::Accepted | DelegationStatus::Running
                )
            })
            .cloned()
            .collect())
    }
}

/// Delegation graph store backed by a pluggable backend.
#[derive(Clone)]
pub struct DelegationStore {
    backend: Arc<dyn DelegationBackend>,
}

impl Default for DelegationStore {
    fn default() -> Self {
        Self::new(Arc::new(InMemoryDelegationBackend::default()))
    }
}

impl DelegationStore {
    /// Creates a delegation store backed by the supplied backend.
    #[must_use]
    pub fn new(backend: Arc<dyn DelegationBackend>) -> Self {
        Self { backend }
    }

    /// Inserts or replaces a delegation graph record.
    pub async fn upsert(&self, record: DelegationRecord) -> RuntimeResult<()> {
        self.backend.upsert(record).await
    }

    /// Returns a delegation record by id.
    pub async fn get(
        &self,
        delegation_id: &DelegationId,
    ) -> RuntimeResult<Option<DelegationRecord>> {
        self.backend.get(delegation_id).await
    }

    /// Returns child delegations for a parent action.
    pub async fn children(
        &self,
        parent_action_id: &ActionId,
    ) -> RuntimeResult<Vec<DelegationRecord>> {
        self.backend.children(parent_action_id).await
    }

    /// Returns the delegation record that owns a child action.
    pub async fn by_child_action(
        &self,
        child_action_id: &ActionId,
    ) -> RuntimeResult<Option<DelegationRecord>> {
        self.backend.by_child_action(child_action_id).await
    }

    /// Returns delegations that still need terminal settlement.
    pub async fn running(&self) -> RuntimeResult<Vec<DelegationRecord>> {
        self.backend.running().await
    }
}

const MANIFEST_CATALOG_NAMESPACE: &str = "aip.discovery.manifest-catalog.v1";
const MANIFEST_CATALOG_KEY: &str = "catalog";
const DELEGATION_OUTBOX_NAMESPACE: &str = "aip.delegation.outbox.v1";

#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
struct DurableManifestCatalog {
    entries: BTreeMap<String, DurableManifestAdmission>,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
struct DurableManifestAdmission {
    manifest: Manifest,
    digest: String,
    commit_event: Event,
    event_published: bool,
    updated_at: OffsetDateTime,
}

/// Durable delivery state for one remote delegation request.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum DelegationDispatchStatus {
    /// Delivery is waiting for its first attempt or a bounded retry.
    Pending,
    /// One worker owns a time-bounded delivery lease.
    Leased,
    /// The authenticated peer returned a correlated result.
    Delivered,
    /// The retry budget was exhausted and operator intervention is required.
    DeadLettered,
}

/// Durable, non-secret remote-delegation outbox record.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct DelegationDispatchRecord {
    /// Original request delivered to the remote peer.
    pub request: DelegationRequest,
    /// Trusted protocol context retained for recovery. Credential material is
    /// never stored; [`CredentialHandle`] contains only an opaque reference.
    pub context: MessageContext,
    /// Current outbox state.
    pub status: DelegationDispatchStatus,
    /// Number of leases acquired for delivery attempts.
    pub attempts: u32,
    /// Maximum total delivery attempts.
    pub max_attempts: u32,
    /// Earliest time at which another attempt may be leased.
    pub next_attempt_at: OffsetDateTime,
    /// Current worker id.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub lease_owner: Option<String>,
    /// Unpredictable fencing token for the current lease.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub lease_id: Option<String>,
    /// Current lease expiration.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub lease_expires_at: Option<OffsetDateTime>,
    /// Last redacted protocol error.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_error: Option<ProtocolError>,
    /// Correlated terminal result retained for idempotent replay.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub result: Option<DelegationResult>,
    /// Creation timestamp.
    pub created_at: OffsetDateTime,
    /// Last state transition timestamp.
    pub updated_at: OffsetDateTime,
}

#[derive(Clone, Debug)]
struct DelegationDispatchLease {
    record: DelegationDispatchRecord,
    lease_id: String,
}

/// Durable approval lifecycle status.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ApprovalStatus {
    /// Approval was requested and is waiting for a decision.
    Pending,
    /// Approval was granted.
    Approved,
    /// Approval was denied.
    Denied,
    /// Approval expired before a decision.
    Expired,
    /// Approval was revoked.
    Revoked,
}

/// Durable approval lifecycle record.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct ApprovalRecord {
    /// Original approval request.
    pub request: ApprovalRequest,
    /// Current approval status.
    pub status: ApprovalStatus,
    /// Final decision, when available.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub decision: Option<ApprovalDecision>,
    /// Every authority-verified decision contributing to policy evaluation.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub decisions: Vec<VerifiedApprovalDecision>,
    /// Creation time.
    pub created_at: OffsetDateTime,
    /// Last update time.
    pub updated_at: OffsetDateTime,
}

/// Approval decision paired with resolver-established authority evidence.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct VerifiedApprovalDecision {
    /// Canonical decision after replacing payload authority claims.
    pub decision: ApprovalDecision,
    /// Trusted authority membership used for evaluation.
    pub authority: AuthorityMembership,
    /// SHA-256 digest covering the decision and authority revision.
    pub evidence_hash: String,
    /// Time at which the runtime admitted this decision.
    pub recorded_at: OffsetDateTime,
}

/// Result of atomically applying one verified approval decision.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ApprovalDecisionApply {
    /// Identical idempotent replay; no state changed.
    Replayed,
    /// Vote was admitted but the policy is still pending.
    Pending,
    /// Vote produced a terminal approval state.
    Terminal,
}

impl ApprovalRecord {
    /// Applies one resolver-verified decision to this locked record.
    ///
    /// Storage backends call this method while holding their transaction or
    /// record lock, ensuring quorum evaluation and terminal transition are one
    /// compare-and-set operation.
    pub fn apply_verified_decision(
        &mut self,
        verified: VerifiedApprovalDecision,
    ) -> RuntimeResult<ApprovalDecisionApply> {
        let decision = &verified.decision;
        if let Some(existing) = self
            .decisions
            .iter()
            .find(|existing| decision_replay_matches(&existing.decision, decision))
        {
            return if existing == &verified {
                Ok(ApprovalDecisionApply::Replayed)
            } else {
                Err(RuntimeError::Authorization(format!(
                    "approval decision id for `{}` was replayed with different content",
                    decision.approval_id
                )))
            };
        }
        if self.status != ApprovalStatus::Pending {
            return Err(RuntimeError::Authorization(format!(
                "approval `{}` already has a terminal decision",
                decision.approval_id
            )));
        }
        self.decisions.push(verified);
        self.status = evaluate_approval_status(self)?;
        if self.status != ApprovalStatus::Pending {
            self.decision = terminal_approval_decision(self);
        }
        self.updated_at = OffsetDateTime::now_utc();
        Ok(if self.status == ApprovalStatus::Pending {
            ApprovalDecisionApply::Pending
        } else {
            ApprovalDecisionApply::Terminal
        })
    }

    /// Verifies that this record is a self-consistent approved authorization
    /// suitable for import across a trusted, authenticated runtime boundary.
    ///
    /// This check reproduces policy evaluation from the resolver-verified
    /// decisions. Authenticity of the containing transport envelope remains the
    /// caller's responsibility.
    pub fn validate_importable_authorization(&self) -> RuntimeResult<()> {
        if self.status != ApprovalStatus::Approved
            || self.decision.as_ref().is_none_or(|decision| {
                decision.decision != ApprovalDecisionKind::Approved
                    || decision.approval_id != self.request.id
                    || decision.policy_hash.as_deref() != self.request.policy_hash.as_deref()
            })
            || self.decisions.is_empty()
        {
            return Err(RuntimeError::Authorization(format!(
                "approval `{}` is not an approved terminal authorization",
                self.request.id
            )));
        }

        let mut reconstructed = Self {
            request: self.request.clone(),
            status: ApprovalStatus::Pending,
            decision: None,
            decisions: Vec::new(),
            created_at: self.created_at,
            updated_at: self.created_at,
        };
        for verified in &self.decisions {
            if verified.decision.approval_id != self.request.id
                || verified.decision.policy_hash.as_deref() != self.request.policy_hash.as_deref()
            {
                return Err(RuntimeError::Authorization(format!(
                    "approval `{}` contains an unrelated verified decision",
                    self.request.id
                )));
            }
            reconstructed.apply_verified_decision(verified.clone())?;
        }
        if reconstructed.status != ApprovalStatus::Approved
            || reconstructed.decision != self.decision
            || reconstructed.decisions != self.decisions
        {
            return Err(RuntimeError::Authorization(format!(
                "approval `{}` cannot reproduce its approved policy state",
                self.request.id
            )));
        }
        Ok(())
    }
}

fn validate_terminal_authorization_import(record: &ApprovalRecord) -> RuntimeResult<()> {
    record.validate_importable_authorization()
}

fn approval_authorization_conflict(record: &ApprovalRecord) -> RuntimeError {
    RuntimeError::Authorization(format!(
        "approval `{}` conflicts with an existing authorization record",
        record.request.id
    ))
}

/// Fenced lease for publishing one durable approval workflow transition.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct ApprovalTransitionLease {
    /// Terminal approval record to publish.
    pub record: ApprovalRecord,
    /// Worker that owns this publication attempt.
    pub worker_id: String,
    /// Fencing token for this publication attempt.
    pub lease_id: String,
    /// Time when another worker may recover the transition.
    pub expires_at: OffsetDateTime,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
struct ApprovalTransitionClaim {
    worker_id: String,
    lease_id: String,
    expires_at: OffsetDateTime,
}

/// Durable approval backend.
#[async_trait]
pub trait ApprovalBackend: Send + Sync {
    /// Inserts a pending approval request or accepts an identical pending replay.
    async fn upsert_request(&self, record: ApprovalRecord) -> RuntimeResult<()>;
    /// Imports an exact terminal authorization verified at a trusted runtime boundary.
    ///
    /// Implementations must make this operation atomic, accept only an identical
    /// replay, and must not schedule local approval workflow transitions. It is
    /// used by isolated connector hosts after authenticating the central
    /// gateway's signed execution envelope.
    async fn import_terminal_authorization(&self, record: ApprovalRecord) -> RuntimeResult<()>;
    /// Stores an approval decision and returns the updated record.
    async fn record_verified_decision(
        &self,
        decision: VerifiedApprovalDecision,
    ) -> RuntimeResult<ApprovalRecord>;
    /// Returns one approval record.
    async fn get(&self, approval_id: &ApprovalId) -> RuntimeResult<Option<ApprovalRecord>>;
    /// Returns all pending approvals.
    async fn pending(&self) -> RuntimeResult<Vec<ApprovalRecord>>;
    /// Returns all approval records.
    async fn list(&self) -> RuntimeResult<Vec<ApprovalRecord>>;
    /// Atomically claims one pending workflow transition by approval id.
    async fn claim_decision_transition(
        &self,
        approval_id: &ApprovalId,
        worker_id: &str,
        lease_ttl_ms: u64,
        now: OffsetDateTime,
    ) -> RuntimeResult<Option<ApprovalTransitionLease>>;
    /// Atomically claims recoverable workflow transitions for a worker.
    async fn claim_pending_decision_transitions(
        &self,
        worker_id: &str,
        lease_ttl_ms: u64,
        now: OffsetDateTime,
    ) -> RuntimeResult<Vec<ApprovalTransitionLease>>;
    /// Completes a workflow transition only for the current fencing token.
    async fn complete_decision_transition(
        &self,
        approval_id: &ApprovalId,
        lease_id: &str,
    ) -> RuntimeResult<bool>;
}

/// In-memory approval backend.
#[derive(Clone, Debug, Default)]
pub struct InMemoryApprovalBackend {
    state: Arc<RwLock<InMemoryApprovalState>>,
}

#[derive(Clone, Debug, Default)]
struct InMemoryApprovalState {
    records: HashMap<ApprovalId, ApprovalRecord>,
    pending_transitions: HashMap<ApprovalId, Option<ApprovalTransitionClaim>>,
}

#[async_trait]
impl ApprovalBackend for InMemoryApprovalBackend {
    async fn upsert_request(&self, record: ApprovalRecord) -> RuntimeResult<()> {
        let mut state = self.state.write().await;
        if let Some(existing) = state.records.get(&record.request.id) {
            if existing.request == record.request
                && existing.status == ApprovalStatus::Pending
                && existing.decision.is_none()
            {
                return Ok(());
            }
            return Err(RuntimeError::Authorization(format!(
                "approval `{}` already exists and cannot be replaced",
                record.request.id
            )));
        }
        state.records.insert(record.request.id.clone(), record);
        Ok(())
    }

    async fn import_terminal_authorization(&self, record: ApprovalRecord) -> RuntimeResult<()> {
        validate_terminal_authorization_import(&record)?;
        let mut state = self.state.write().await;
        if let Some(existing) = state.records.get(&record.request.id) {
            return if existing == &record {
                Ok(())
            } else {
                Err(approval_authorization_conflict(&record))
            };
        }
        state.records.insert(record.request.id.clone(), record);
        Ok(())
    }

    async fn record_verified_decision(
        &self,
        verified: VerifiedApprovalDecision,
    ) -> RuntimeResult<ApprovalRecord> {
        let mut state = self.state.write().await;
        let decision = &verified.decision;
        let record = state
            .records
            .get_mut(&decision.approval_id)
            .ok_or_else(|| {
                RuntimeError::Handler(format!("approval `{}` was not found", decision.approval_id))
            })?;
        let apply = record.apply_verified_decision(verified)?;
        let updated = record.clone();
        if apply == ApprovalDecisionApply::Terminal {
            state
                .pending_transitions
                .insert(updated.request.id.clone(), None);
        }
        Ok(updated)
    }

    async fn get(&self, approval_id: &ApprovalId) -> RuntimeResult<Option<ApprovalRecord>> {
        Ok(self.state.read().await.records.get(approval_id).cloned())
    }

    async fn pending(&self) -> RuntimeResult<Vec<ApprovalRecord>> {
        Ok(self
            .state
            .read()
            .await
            .records
            .values()
            .filter(|record| record.status == ApprovalStatus::Pending)
            .cloned()
            .collect())
    }

    async fn list(&self) -> RuntimeResult<Vec<ApprovalRecord>> {
        let mut records = self
            .state
            .read()
            .await
            .records
            .values()
            .cloned()
            .collect::<Vec<_>>();
        records.sort_by_key(|record| record.created_at);
        Ok(records)
    }

    async fn claim_decision_transition(
        &self,
        approval_id: &ApprovalId,
        worker_id: &str,
        lease_ttl_ms: u64,
        now: OffsetDateTime,
    ) -> RuntimeResult<Option<ApprovalTransitionLease>> {
        let mut state = self.state.write().await;
        claim_in_memory_approval_transition(&mut state, approval_id, worker_id, lease_ttl_ms, now)
    }

    async fn claim_pending_decision_transitions(
        &self,
        worker_id: &str,
        lease_ttl_ms: u64,
        now: OffsetDateTime,
    ) -> RuntimeResult<Vec<ApprovalTransitionLease>> {
        let mut state = self.state.write().await;
        let ids = state
            .pending_transitions
            .keys()
            .cloned()
            .collect::<Vec<_>>();
        let mut claimed = Vec::new();
        for approval_id in ids {
            if let Some(lease) = claim_in_memory_approval_transition(
                &mut state,
                &approval_id,
                worker_id,
                lease_ttl_ms,
                now,
            )? {
                claimed.push(lease);
            }
        }
        Ok(claimed)
    }

    async fn complete_decision_transition(
        &self,
        approval_id: &ApprovalId,
        lease_id: &str,
    ) -> RuntimeResult<bool> {
        let mut state = self.state.write().await;
        if state
            .pending_transitions
            .get(approval_id)
            .and_then(Option::as_ref)
            .is_some_and(|claim| claim.lease_id == lease_id)
        {
            state.pending_transitions.remove(approval_id);
            return Ok(true);
        }
        Ok(false)
    }
}

fn claim_in_memory_approval_transition(
    state: &mut InMemoryApprovalState,
    approval_id: &ApprovalId,
    worker_id: &str,
    lease_ttl_ms: u64,
    now: OffsetDateTime,
) -> RuntimeResult<Option<ApprovalTransitionLease>> {
    let Some(current_claim) = state.pending_transitions.get(approval_id) else {
        return Ok(None);
    };
    if current_claim
        .as_ref()
        .is_some_and(|claim| claim.expires_at > now)
    {
        return Ok(None);
    }
    let record = state.records.get(approval_id).cloned().ok_or_else(|| {
        RuntimeError::Storage(format!(
            "approval transition `{approval_id}` has no approval record"
        ))
    })?;
    let claim = ApprovalTransitionClaim {
        worker_id: worker_id.to_owned(),
        lease_id: Uuid::now_v7().to_string(),
        expires_at: now
            + time::Duration::milliseconds(lease_ttl_ms.max(1).min(i64::MAX as u64) as i64),
    };
    state
        .pending_transitions
        .insert(approval_id.clone(), Some(claim.clone()));
    Ok(Some(ApprovalTransitionLease {
        record,
        worker_id: claim.worker_id,
        lease_id: claim.lease_id,
        expires_at: claim.expires_at,
    }))
}

/// Approval store backed by a pluggable backend.
#[derive(Clone)]
pub struct ApprovalStore {
    backend: Arc<dyn ApprovalBackend>,
}

impl Default for ApprovalStore {
    fn default() -> Self {
        Self::new(Arc::new(InMemoryApprovalBackend::default()))
    }
}

impl ApprovalStore {
    /// Creates an approval store backed by the supplied backend.
    #[must_use]
    pub fn new(backend: Arc<dyn ApprovalBackend>) -> Self {
        Self { backend }
    }

    /// Inserts a pending approval request or accepts an identical pending replay.
    pub async fn upsert_request(&self, record: ApprovalRecord) -> RuntimeResult<()> {
        self.backend.upsert_request(record).await
    }

    /// Imports an exact terminal authorization from a trusted runtime boundary.
    pub async fn import_terminal_authorization(&self, record: ApprovalRecord) -> RuntimeResult<()> {
        self.backend.import_terminal_authorization(record).await
    }

    /// Stores an approval decision.
    pub async fn record_verified_decision(
        &self,
        decision: VerifiedApprovalDecision,
    ) -> RuntimeResult<ApprovalRecord> {
        self.backend.record_verified_decision(decision).await
    }

    /// Returns one approval record.
    pub async fn get(&self, approval_id: &ApprovalId) -> RuntimeResult<Option<ApprovalRecord>> {
        self.backend.get(approval_id).await
    }

    /// Returns all pending approval records.
    pub async fn pending(&self) -> RuntimeResult<Vec<ApprovalRecord>> {
        self.backend.pending().await
    }

    /// Returns all approval records.
    pub async fn list(&self) -> RuntimeResult<Vec<ApprovalRecord>> {
        self.backend.list().await
    }

    /// Returns durable approval decisions whose side effects still require publication.
    pub async fn claim_decision_transition(
        &self,
        approval_id: &ApprovalId,
        worker_id: &str,
        lease_ttl_ms: u64,
    ) -> RuntimeResult<Option<ApprovalTransitionLease>> {
        self.backend
            .claim_decision_transition(
                approval_id,
                worker_id,
                lease_ttl_ms,
                OffsetDateTime::now_utc(),
            )
            .await
    }

    /// Claims all recoverable decision transitions for supervised publication.
    pub async fn claim_pending_decision_transitions(
        &self,
        worker_id: &str,
        lease_ttl_ms: u64,
    ) -> RuntimeResult<Vec<ApprovalTransitionLease>> {
        self.backend
            .claim_pending_decision_transitions(worker_id, lease_ttl_ms, OffsetDateTime::now_utc())
            .await
    }

    /// Marks an approval decision transition as completely published with fencing.
    pub async fn complete_decision_transition(
        &self,
        approval_id: &ApprovalId,
        lease_id: &str,
    ) -> RuntimeResult<bool> {
        self.backend
            .complete_decision_transition(approval_id, lease_id)
            .await
    }
}

/// Durable transaction lifecycle status.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum TransactionStatus {
    /// Dry-run validation or simulation completed without committed side effects.
    DryRunCompleted,
    /// Transaction plan was created.
    Planned,
    /// Provider accepted and prepared the operation.
    Prepared,
    /// A commit action atomically owns execution of the plan.
    Committing,
    /// Transaction was committed.
    Committed,
    /// Compensation is currently executing.
    Compensating,
    /// Compensation was executed.
    Compensated,
    /// Transaction failed.
    Failed,
    /// Commit may have reached the provider and must not be retried blindly.
    OutcomeUnknown,
    /// A worker owns provider reconciliation.
    Reconciling,
    /// Reconciliation established a terminal provider outcome.
    Reconciled,
    /// Rollback or compensation is explicitly unsupported.
    RollbackNotSupported,
}

/// Durable transaction or saga record.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct TransactionRecord {
    /// Transaction id.
    pub transaction_id: TransactionId,
    /// Action associated with this transaction.
    pub action_id: ActionId,
    /// Capability associated with this transaction.
    pub capability_id: CapabilityId,
    /// Requested transaction context.
    pub transaction: ActionTransaction,
    /// Identity context captured at transaction creation time.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub identity: Option<IdentityContext>,
    /// Current transaction status.
    pub status: TransactionStatus,
    /// Execution plan.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub plan: Option<TransactionPlan>,
    /// Terminal action result, if execution occurred.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub result: Option<ActionResult>,
    /// Durable provider operation reference.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub provider_operation: Option<ProviderOperationRef>,
    /// Opaque cursor for continuation of reconciliation.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub reconciliation_cursor: Option<String>,
    /// Earliest permitted reconciliation attempt.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub reconcile_after: Option<OffsetDateTime>,
    /// Last redacted protocol error.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub error: Option<ProtocolError>,
    /// Monotonic compare-and-set revision.
    #[serde(default)]
    pub revision: u64,
    /// Creation time.
    pub created_at: OffsetDateTime,
    /// Last update time.
    pub updated_at: OffsetDateTime,
}

/// Atomic transaction state update applied by a durable backend.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct TransactionTransition {
    /// Allowed current states.
    pub expected: Vec<TransactionStatus>,
    /// New state.
    pub status: TransactionStatus,
    /// Updated action result, when known.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub result: Option<ActionResult>,
    /// Clears a result retained from a completed execution attempt.
    ///
    /// This is used only when an exact, idempotently fenced `execute` retry
    /// reopens a transaction whose previous attempt failed before the provider
    /// accepted an operation. Keeping this explicit prevents an in-progress
    /// transaction from exposing a stale terminal result.
    #[serde(default)]
    pub clear_result: bool,
    /// Provider operation accepted before an uncertain response.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub provider_operation: Option<ProviderOperationRef>,
    /// Updated reconciliation cursor.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub reconciliation_cursor: Option<String>,
    /// Earliest next reconciliation time.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub reconcile_after: Option<OffsetDateTime>,
    /// Redacted terminal or uncertain error.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub error: Option<ProtocolError>,
}

impl TransactionRecord {
    /// Applies a validated transition while the backend holds its revision fence.
    pub fn apply_transition(&mut self, transition: TransactionTransition) -> RuntimeResult<()> {
        if transition.expected.is_empty() || !transition.expected.contains(&self.status) {
            return Err(RuntimeError::Authorization(format!(
                "transaction `{}` cannot transition from `{:?}` to `{:?}`",
                self.transaction_id, self.status, transition.status
            )));
        }
        self.status = transition.status;
        if transition.clear_result {
            self.result = None;
        } else if transition.result.is_some() {
            self.result = transition.result;
        }
        if transition.provider_operation.is_some() {
            self.provider_operation = transition.provider_operation;
        }
        if transition.reconciliation_cursor.is_some() {
            self.reconciliation_cursor = transition.reconciliation_cursor;
        }
        self.reconcile_after = transition.reconcile_after;
        self.error = transition.error;
        self.revision = self.revision.saturating_add(1);
        self.updated_at = OffsetDateTime::now_utc();
        Ok(())
    }
}

/// Durable transaction backend.
#[async_trait]
pub trait TransactionBackend: Send + Sync {
    /// Inserts or replaces a transaction record.
    async fn upsert(&self, record: TransactionRecord) -> RuntimeResult<()>;
    /// Returns a transaction record by id.
    async fn get(&self, transaction_id: &TransactionId)
    -> RuntimeResult<Option<TransactionRecord>>;
    /// Returns the transaction plan that owns a plan id.
    async fn by_plan_id(&self, plan_id: &str) -> RuntimeResult<Option<TransactionRecord>> {
        let _ = plan_id;
        Ok(None)
    }
    /// Atomically moves a plan from `planned` to `committing` for one action.
    async fn claim_plan(
        &self,
        plan_id: &str,
        commit_action_id: &ActionId,
    ) -> RuntimeResult<TransactionRecord>;
    /// Atomically creates an unplanned commit in `committing` state.
    async fn claim_direct_commit(
        &self,
        record: TransactionRecord,
    ) -> RuntimeResult<TransactionRecord>;
    /// Returns transaction records for an action.
    async fn by_action(&self, action_id: &ActionId) -> RuntimeResult<Vec<TransactionRecord>>;
    /// Returns non-terminal transaction records that should be inspected after restart.
    async fn recoverable(&self) -> RuntimeResult<Vec<TransactionRecord>>;
    /// Atomically applies a state transition with status and revision fencing.
    async fn transition(
        &self,
        transaction_id: &TransactionId,
        expected_revision: u64,
        transition: TransactionTransition,
    ) -> RuntimeResult<TransactionRecord>;
}

/// In-memory transaction backend.
#[derive(Clone, Debug, Default)]
pub struct InMemoryTransactionBackend {
    records: Arc<RwLock<HashMap<TransactionId, TransactionRecord>>>,
}

#[async_trait]
impl TransactionBackend for InMemoryTransactionBackend {
    async fn upsert(&self, record: TransactionRecord) -> RuntimeResult<()> {
        self.records
            .write()
            .await
            .insert(record.transaction_id.clone(), record);
        Ok(())
    }

    async fn get(
        &self,
        transaction_id: &TransactionId,
    ) -> RuntimeResult<Option<TransactionRecord>> {
        Ok(self.records.read().await.get(transaction_id).cloned())
    }

    async fn by_plan_id(&self, plan_id: &str) -> RuntimeResult<Option<TransactionRecord>> {
        Ok(self
            .records
            .read()
            .await
            .values()
            .find(|record| transaction_plan_id(record).as_deref() == Some(plan_id))
            .cloned())
    }

    async fn claim_plan(
        &self,
        plan_id: &str,
        commit_action_id: &ActionId,
    ) -> RuntimeResult<TransactionRecord> {
        let mut records = self.records.write().await;
        let record = records
            .values_mut()
            .find(|record| transaction_plan_id(record).as_deref() == Some(plan_id))
            .ok_or_else(|| {
                RuntimeError::Storage(format!("transaction plan `{plan_id}` not found"))
            })?;
        if record.status != TransactionStatus::Planned {
            return Err(RuntimeError::Authorization(format!(
                "transaction plan `{plan_id}` is already in state `{:?}`",
                record.status
            )));
        }
        record.status = TransactionStatus::Committing;
        record.action_id = commit_action_id.clone();
        record.revision = record.revision.saturating_add(1);
        record.updated_at = OffsetDateTime::now_utc();
        Ok(record.clone())
    }

    async fn claim_direct_commit(
        &self,
        record: TransactionRecord,
    ) -> RuntimeResult<TransactionRecord> {
        let mut records = self.records.write().await;
        if let Some(existing) = records.get(&record.transaction_id) {
            return Err(RuntimeError::Authorization(format!(
                "transaction `{}` is already in state `{:?}`",
                record.transaction_id, existing.status
            )));
        }
        records.insert(record.transaction_id.clone(), record.clone());
        Ok(record)
    }

    async fn by_action(&self, action_id: &ActionId) -> RuntimeResult<Vec<TransactionRecord>> {
        Ok(self
            .records
            .read()
            .await
            .values()
            .filter(|record| record.action_id == *action_id)
            .cloned()
            .collect())
    }

    async fn recoverable(&self) -> RuntimeResult<Vec<TransactionRecord>> {
        Ok(self
            .records
            .read()
            .await
            .values()
            .filter(|record| transaction_is_recoverable(record))
            .cloned()
            .collect())
    }

    async fn transition(
        &self,
        transaction_id: &TransactionId,
        expected_revision: u64,
        transition: TransactionTransition,
    ) -> RuntimeResult<TransactionRecord> {
        let mut records = self.records.write().await;
        let record = records.get_mut(transaction_id).ok_or_else(|| {
            RuntimeError::Storage(format!("transaction `{transaction_id}` was not found"))
        })?;
        if record.revision != expected_revision {
            return Err(RuntimeError::Storage(format!(
                "transaction `{transaction_id}` lost revision fence `{expected_revision}`"
            )));
        }
        record.apply_transition(transition)?;
        Ok(record.clone())
    }
}

/// Transaction store backed by a pluggable backend.
#[derive(Clone)]
pub struct TransactionStore {
    backend: Arc<dyn TransactionBackend>,
}

impl Default for TransactionStore {
    fn default() -> Self {
        Self::new(Arc::new(InMemoryTransactionBackend::default()))
    }
}

impl TransactionStore {
    /// Creates a transaction store backed by the supplied backend.
    #[must_use]
    pub fn new(backend: Arc<dyn TransactionBackend>) -> Self {
        Self { backend }
    }

    /// Inserts or replaces a transaction record.
    pub async fn upsert(&self, record: TransactionRecord) -> RuntimeResult<()> {
        self.backend.upsert(record).await
    }

    /// Returns a transaction record by id.
    pub async fn get(
        &self,
        transaction_id: &TransactionId,
    ) -> RuntimeResult<Option<TransactionRecord>> {
        self.backend.get(transaction_id).await
    }

    /// Returns the transaction plan that owns a plan id.
    pub async fn by_plan_id(&self, plan_id: &str) -> RuntimeResult<Option<TransactionRecord>> {
        self.backend.by_plan_id(plan_id).await
    }

    /// Atomically acquires a transaction plan for one commit action.
    pub async fn claim_plan(
        &self,
        plan_id: &str,
        commit_action_id: &ActionId,
    ) -> RuntimeResult<TransactionRecord> {
        self.backend.claim_plan(plan_id, commit_action_id).await
    }

    /// Atomically acquires a transaction id for a commit that does not require a plan.
    pub async fn claim_direct_commit(
        &self,
        record: TransactionRecord,
    ) -> RuntimeResult<TransactionRecord> {
        self.backend.claim_direct_commit(record).await
    }

    /// Returns transaction records for an action.
    pub async fn by_action(&self, action_id: &ActionId) -> RuntimeResult<Vec<TransactionRecord>> {
        self.backend.by_action(action_id).await
    }

    /// Returns non-terminal transaction records that should be inspected after restart.
    pub async fn recoverable(&self) -> RuntimeResult<Vec<TransactionRecord>> {
        self.backend.recoverable().await
    }

    /// Applies a fenced transaction transition.
    pub async fn transition(
        &self,
        transaction_id: &TransactionId,
        expected_revision: u64,
        transition: TransactionTransition,
    ) -> RuntimeResult<TransactionRecord> {
        self.backend
            .transition(transaction_id, expected_revision, transition)
            .await
    }
}

/// Retry policy stored with queued work.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct RetryPolicy {
    /// Maximum attempts including the first execution attempt.
    pub max_attempts: u32,
    /// Initial retry delay.
    pub initial_backoff_ms: u64,
    /// Maximum retry delay.
    pub max_backoff_ms: u64,
    /// Exponential backoff multiplier applied after each failed attempt.
    #[serde(default = "default_retry_backoff_multiplier")]
    pub backoff_multiplier: u32,
    /// Whether automatic retry requires the action to carry an idempotency key.
    #[serde(default)]
    pub requires_idempotency_key: bool,
    /// Maximum elapsed retry budget starting with the first execution attempt.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_elapsed_ms: Option<u64>,
    /// Error categories that may be retried when the error itself is silent.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub retryable_error_categories: Vec<ErrorCategory>,
}

impl Default for RetryPolicy {
    fn default() -> Self {
        Self {
            max_attempts: 1,
            initial_backoff_ms: 1_000,
            max_backoff_ms: 30_000,
            backoff_multiplier: default_retry_backoff_multiplier(),
            requires_idempotency_key: false,
            max_elapsed_ms: None,
            retryable_error_categories: default_retryable_error_categories(),
        }
    }
}

fn default_queue_worker_id() -> String {
    "aip-runtime-worker".to_owned()
}

fn default_queue_worker_lease_ttl_ms() -> u64 {
    30_000
}

fn default_queue_worker_idle_sleep_ms() -> u64 {
    250
}

fn default_queue_worker_max_idle_polls() -> u32 {
    1
}

fn default_true() -> bool {
    true
}

/// Configuration for a finite runtime queue worker drain.
///
/// This API is the production-safe embedding boundary for daemon workers and
/// tests. It uses the same atomic lease contract as [`ActionQueueBackend`],
/// honors retry windows, and stops after a bounded amount of idle polling.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct QueueWorkerConfig {
    /// Stable worker id used for queue leases.
    #[serde(default = "default_queue_worker_id")]
    pub worker_id: String,
    /// Lease duration granted for each claimed action.
    #[serde(default = "default_queue_worker_lease_ttl_ms")]
    pub lease_ttl_ms: u64,
    /// Sleep interval between idle polls.
    #[serde(default = "default_queue_worker_idle_sleep_ms")]
    pub idle_sleep_ms: u64,
    /// Number of consecutive idle polls before the finite worker returns.
    #[serde(default = "default_queue_worker_max_idle_polls")]
    pub max_idle_polls: u32,
    /// Optional maximum number of claimed actions for this run.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_claims: Option<u32>,
}

impl QueueWorkerConfig {
    /// Creates a worker configuration with a caller supplied stable worker id.
    #[must_use]
    pub fn new(worker_id: impl Into<String>) -> Self {
        Self {
            worker_id: worker_id.into(),
            ..Self::default()
        }
    }
}

impl Default for QueueWorkerConfig {
    fn default() -> Self {
        Self {
            worker_id: default_queue_worker_id(),
            lease_ttl_ms: default_queue_worker_lease_ttl_ms(),
            idle_sleep_ms: default_queue_worker_idle_sleep_ms(),
            max_idle_polls: default_queue_worker_max_idle_polls(),
            max_claims: None,
        }
    }
}

/// Summary returned by a finite runtime queue worker drain.
#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct QueueWorkerReport {
    /// Worker id used for leases.
    pub worker_id: String,
    /// Number of queue records claimed and executed.
    pub claimed: u32,
    /// Number of claimed attempts that reached terminal queue state.
    pub terminal_results: u32,
    /// Number of attempts that scheduled a future retry.
    pub retry_scheduled: u32,
    /// Number of failed attempt results observed by the worker.
    pub failed_attempts: u32,
    /// Number of runtime-level worker errors.
    pub worker_errors: u32,
    /// Consecutive idle polls observed at shutdown.
    pub idle_polls: u32,
    /// Last action id observed by the worker, if any.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_action_id: Option<ActionId>,
    /// Last runtime-level worker error, if any.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_error: Option<String>,
}

/// Configuration for explicit runtime state recovery after process restart.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct RuntimeRecoveryConfig {
    /// Context used when recovery emits lifecycle events.
    #[serde(default)]
    pub context: MessageContext,
    /// Whether queued or running async actions should be replayed.
    #[serde(default = "default_true")]
    pub recover_queued_actions: bool,
    /// Whether running delegation graph edges should be replayed.
    #[serde(default = "default_true")]
    pub recover_running_delegations: bool,
    /// Whether pending approval records should be included in the report.
    #[serde(default = "default_true")]
    pub include_pending_approvals: bool,
    /// Whether recoverable transaction and saga records should be included.
    #[serde(default = "default_true")]
    pub include_recoverable_transactions: bool,
    /// Whether recoverable callback deliveries should be retried.
    #[serde(default = "default_true")]
    pub recover_callback_deliveries: bool,
}

impl Default for RuntimeRecoveryConfig {
    fn default() -> Self {
        Self {
            context: MessageContext::default(),
            recover_queued_actions: true,
            recover_running_delegations: true,
            include_pending_approvals: true,
            include_recoverable_transactions: true,
            recover_callback_deliveries: true,
        }
    }
}

/// Structured runtime recovery evidence produced after process restart.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct RuntimeRecoveryReport {
    /// Time when recovery was requested.
    pub recovered_at: OffsetDateTime,
    /// Pending approval records that survived restart.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub pending_approvals: Vec<ApprovalRecord>,
    /// Recoverable transaction or saga records that survived restart.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub recoverable_transactions: Vec<TransactionRecord>,
    /// Action results produced by queued action recovery.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub queued_results: Vec<ActionResult>,
    /// Errors produced by queued action recovery.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub queued_errors: Vec<ProtocolError>,
    /// Delegation results produced by delegation recovery.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub delegation_results: Vec<DelegationResult>,
    /// Errors produced by delegation recovery.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub delegation_errors: Vec<ProtocolError>,
    /// Callback deliveries recovered or retried after restart.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub callback_deliveries: Vec<CallbackDeliveryRecord>,
}

impl Default for RuntimeRecoveryReport {
    fn default() -> Self {
        Self {
            recovered_at: OffsetDateTime::now_utc(),
            pending_approvals: Vec::new(),
            recoverable_transactions: Vec::new(),
            queued_results: Vec::new(),
            queued_errors: Vec::new(),
            delegation_results: Vec::new(),
            delegation_errors: Vec::new(),
            callback_deliveries: Vec::new(),
        }
    }
}

/// Durable dead-letter queue record for exhausted or unretryable work.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct DeadLetterRecord {
    /// Queue record that could not be completed.
    pub record: QueuedActionRecord,
    /// Terminal protocol error.
    pub error: ProtocolError,
    /// Number of attempts made.
    pub attempts: u32,
    /// Time when the record entered the dead-letter queue.
    pub failed_at: OffsetDateTime,
}

/// Durable status for an asynchronous action accepted by the runtime queue.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum QueuedActionStatus {
    /// Work has been accepted but not yet started.
    Queued,
    /// Work has been dispatched to a handler.
    Running,
    /// Work completed successfully.
    Completed,
    /// Work failed permanently.
    Failed,
    /// Work was cancelled.
    Cancelled,
    /// Work stopped because human input is required.
    RequiresHuman,
    /// Work metadata expired under retention policy.
    Expired,
}

/// Lease ownership for a queued action claimed by a runtime worker.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct ActionLease {
    /// Stable worker id that owns the lease.
    pub worker_id: String,
    /// Lease id unique to one claim attempt.
    pub lease_id: String,
    /// Time when the lease was acquired.
    pub acquired_at: OffsetDateTime,
    /// Time when another worker may reclaim the action.
    pub expires_at: OffsetDateTime,
}

/// Durable asynchronous action queue record.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct QueuedActionRecord {
    /// Action to execute.
    pub action: Action,
    /// Principal used for authorization and handler context.
    pub principal: Principal,
    /// Transport/runtime context captured at enqueue time.
    pub context: MessageContext,
    /// Durable queue status.
    pub status: QueuedActionStatus,
    /// Terminal result, when known.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub result: Option<ActionResult>,
    /// Optional cancellation reason.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub cancellation_reason: Option<String>,
    /// Number of execution attempts already made.
    #[serde(default)]
    pub attempts: u32,
    /// Retry policy for this record.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub retry_policy: Option<RetryPolicy>,
    /// Time when the first execution attempt started.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub first_attempted_at: Option<OffsetDateTime>,
    /// Time when the latest execution attempt started.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_attempted_at: Option<OffsetDateTime>,
    /// Earliest time when the queued action may be leased again.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub next_attempt_at: Option<OffsetDateTime>,
    /// Latest failed attempt error retained for scheduler, audit, and operators.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_error: Option<ProtocolError>,
    /// Dead-letter reason, if the record has been terminally parked.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub dead_letter_reason: Option<String>,
    /// Current worker lease, if the action is claimed.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub lease: Option<ActionLease>,
    /// Fenced idempotency reservation transferred to the queue worker.
    ///
    /// The reservation is persisted with the queue record so accepting an
    /// asynchronous action cannot race another node between idempotency claim
    /// and handler execution. Retry scheduling clears the reservation after a
    /// retryable result releases it; the next attempt then acquires a fresh
    /// fencing token.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub idempotency_reservation: Option<IdempotencyReservation>,
    /// Creation time.
    pub created_at: OffsetDateTime,
    /// Last update time.
    pub updated_at: OffsetDateTime,
}

/// Validates an action against the immutable contract already bound to a queue
/// record.
///
/// This function is shared by runtime preflight checks and durable storage
/// backends so a conflicting action id fails closed both before execution and
/// at the atomic persistence boundary.
pub fn validate_queued_action_identity(
    existing: &QueuedActionRecord,
    action: &Action,
    principal: &Principal,
) -> RuntimeResult<()> {
    if queued_action_identity_matches(existing, action, principal) {
        return Ok(());
    }
    Err(action_id_conflict_error(existing, action, principal))
}

/// Validates that a queue upsert only advances lifecycle state for the action
/// already stored under the same id.
pub fn validate_queued_action_replacement(
    existing: &QueuedActionRecord,
    candidate: &QueuedActionRecord,
) -> RuntimeResult<()> {
    validate_queued_action_identity(existing, &candidate.action, &candidate.principal)
}

fn queued_action_identity_matches(
    existing: &QueuedActionRecord,
    action: &Action,
    principal: &Principal,
) -> bool {
    if existing.principal != *principal {
        return false;
    }

    let existing_contract = normalized_queue_action_contract(&existing.action);
    let attempted_contract = normalized_queue_action_contract(action);
    if existing_contract == attempted_contract {
        return true;
    }

    // Releases predating the durable-contract boundary fix persisted the
    // connector-facing action after runtime context had been injected into
    // `memory_context._aip`. Reconstruct that exact historical representation
    // from the durable message context so an in-flight action can be recovered
    // after a rolling upgrade. This is deliberately one-way and narrow: only
    // an absent or object-shaped caller context without the reserved `_aip`
    // member is eligible, while every caller-owned field still participates in
    // the equality check. Primitive and array contexts remain fail-closed
    // because the old wrapper representation is otherwise ambiguous.
    let supports_legacy_context = match action.memory_context.as_ref() {
        None => true,
        Some(Value::Object(object)) => !object.contains_key("_aip"),
        Some(_) => false,
    };
    supports_legacy_context
        && existing_contract
            == normalized_queue_action_contract(&enrich_action_context(
                action.clone(),
                &existing.context,
            ))
}

fn normalized_queue_action_contract(action: &Action) -> Action {
    let mut contract = action.clone();
    contract.approval = None;
    if let Some(transaction) = contract.transaction.as_mut() {
        // A transaction id may be assigned by the runtime. The transaction
        // intent remains immutable and is represented by the remaining fields.
        transaction.transaction_id = None;
    }
    contract
}

fn action_id_conflict_error(
    existing: &QueuedActionRecord,
    action: &Action,
    principal: &Principal,
) -> RuntimeError {
    RuntimeError::Protocol(ProtocolError {
        code: "action.id_conflict".to_owned(),
        message: format!(
            "action id `{}` is already bound to a different immutable action contract",
            action.id
        ),
        category: ErrorCategory::Permanent,
        retryable: Some(false),
        retry_after_ms: None,
        details: Some(Box::new(json!({
            "action_id": action.id,
            "existing_capability_id": existing.action.capability_id,
            "attempted_capability_id": action.capability_id,
            "existing_principal_id": existing.principal.id,
            "attempted_principal_id": principal.id
        }))),
        source: Some(Box::new(json!({ "component": "aip-runtime.action-queue" }))),
    })
}

/// Atomic settlement requested by a worker that owns an action lease.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub enum QueueAttemptOutcome {
    /// Return the action to the queue for a later retry.
    Retry(QueuedActionRecord),
    /// Persist a terminal action result.
    Settle(ActionResult),
    /// Park the action in the dead-letter queue.
    DeadLetter(DeadLetterRecord),
}

/// Result of a fenced queue settlement operation.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum QueueCompletion {
    /// The outcome was committed by the current lease owner.
    Applied,
    /// The action had already been cancelled.
    Cancelled,
    /// The lease was missing, expired, or owned by another execution attempt.
    LeaseLost,
}

/// Durable asynchronous action queue backend.
#[async_trait]
pub trait ActionQueueBackend: Send + Sync {
    /// Inserts a queued action record or advances the same immutable action.
    ///
    /// Implementations must atomically reject an action id already bound to a
    /// different action contract.
    async fn enqueue(&self, record: QueuedActionRecord) -> RuntimeResult<()>;
    /// Marks an action as running.
    async fn mark_running(&self, action_id: &ActionId) -> RuntimeResult<()>;
    /// Attempts to claim one queued or expired action for a worker.
    async fn lease_next(
        &self,
        worker_id: &str,
        lease_ttl_ms: u64,
        now: OffsetDateTime,
    ) -> RuntimeResult<Option<QueuedActionRecord>>;
    /// Attempts to claim a specific queued or expired action for a worker.
    async fn lease_action(
        &self,
        action_id: &ActionId,
        worker_id: &str,
        lease_ttl_ms: u64,
        now: OffsetDateTime,
    ) -> RuntimeResult<Option<QueuedActionRecord>>;
    /// Atomically claims an approval-blocked action for resume execution.
    async fn lease_approval_action(
        &self,
        action_id: &ActionId,
        worker_id: &str,
        lease_ttl_ms: u64,
        now: OffsetDateTime,
    ) -> RuntimeResult<Option<QueuedActionRecord>>;
    /// Attempts to renew a lease owned by a worker.
    async fn renew_lease(
        &self,
        action_id: &ActionId,
        worker_id: &str,
        lease_id: &str,
        lease_ttl_ms: u64,
        now: OffsetDateTime,
    ) -> RuntimeResult<Option<QueuedActionRecord>>;
    /// Releases a lease if it is still owned by the worker.
    async fn release_lease(
        &self,
        action_id: &ActionId,
        worker_id: &str,
        lease_id: &str,
    ) -> RuntimeResult<()>;
    /// Atomically commits one retry, settlement, or dead-letter outcome when the
    /// supplied lease still owns the action.
    async fn complete_attempt(
        &self,
        action_id: &ActionId,
        lease_id: &str,
        outcome: QueueAttemptOutcome,
    ) -> RuntimeResult<QueueCompletion>;
    /// Stores a terminal result for an action.
    async fn settle(&self, result: ActionResult) -> RuntimeResult<()>;
    /// Stores an approval-expired terminal result using the distinct queue state.
    async fn expire(&self, result: ActionResult) -> RuntimeResult<()>;
    /// Marks a queued action as cancelled.
    async fn cancel(&self, action_id: &ActionId, reason: Option<String>) -> RuntimeResult<()>;
    /// Increments the attempt count for a queued action.
    async fn increment_attempts(
        &self,
        action_id: &ActionId,
    ) -> RuntimeResult<Option<QueuedActionRecord>>;
    /// Moves a record into the dead-letter queue.
    async fn dead_letter(&self, record: DeadLetterRecord) -> RuntimeResult<()>;
    /// Returns all dead-letter records.
    async fn dead_letters(&self) -> RuntimeResult<Vec<DeadLetterRecord>>;
    /// Returns queued or running work that can be recovered after restart.
    async fn recoverable(&self) -> RuntimeResult<Vec<QueuedActionRecord>>;
    /// Returns one queue record.
    async fn get(&self, action_id: &ActionId) -> RuntimeResult<Option<QueuedActionRecord>>;
    /// Returns all known queue records for the operational read model.
    async fn list(&self) -> RuntimeResult<Vec<QueuedActionRecord>>;
}

/// In-memory asynchronous action queue backend.
#[derive(Clone, Debug, Default)]
pub struct InMemoryActionQueueBackend {
    records: Arc<RwLock<HashMap<ActionId, QueuedActionRecord>>>,
    dead_letters: Arc<RwLock<Vec<DeadLetterRecord>>>,
}

#[async_trait]
impl ActionQueueBackend for InMemoryActionQueueBackend {
    async fn enqueue(&self, record: QueuedActionRecord) -> RuntimeResult<()> {
        let mut records = self.records.write().await;
        if let Some(existing) = records.get(&record.action.id) {
            validate_queued_action_replacement(existing, &record)?;
        }
        records.insert(record.action.id.clone(), record);
        Ok(())
    }

    async fn mark_running(&self, action_id: &ActionId) -> RuntimeResult<()> {
        if let Some(record) = self.records.write().await.get_mut(action_id) {
            record.status = QueuedActionStatus::Running;
            record.updated_at = OffsetDateTime::now_utc();
        }
        Ok(())
    }

    async fn lease_next(
        &self,
        worker_id: &str,
        lease_ttl_ms: u64,
        now: OffsetDateTime,
    ) -> RuntimeResult<Option<QueuedActionRecord>> {
        let mut records = self.records.write().await;
        let Some(record) = records
            .values_mut()
            .filter(|record| action_is_leaseable(record, now))
            .min_by_key(|record| record.created_at)
        else {
            return Ok(None);
        };
        apply_action_lease(record, worker_id, lease_ttl_ms, now);
        Ok(Some(record.clone()))
    }

    async fn lease_action(
        &self,
        action_id: &ActionId,
        worker_id: &str,
        lease_ttl_ms: u64,
        now: OffsetDateTime,
    ) -> RuntimeResult<Option<QueuedActionRecord>> {
        let mut records = self.records.write().await;
        let Some(record) = records.get_mut(action_id) else {
            return Ok(None);
        };
        if !action_is_leaseable(record, now) {
            return Ok(None);
        }
        apply_action_lease(record, worker_id, lease_ttl_ms, now);
        Ok(Some(record.clone()))
    }

    async fn lease_approval_action(
        &self,
        action_id: &ActionId,
        worker_id: &str,
        lease_ttl_ms: u64,
        now: OffsetDateTime,
    ) -> RuntimeResult<Option<QueuedActionRecord>> {
        let mut records = self.records.write().await;
        let Some(record) = records.get_mut(action_id) else {
            return Ok(None);
        };
        if record.status != QueuedActionStatus::RequiresHuman || record.lease.is_some() {
            return Ok(None);
        }
        apply_action_lease(record, worker_id, lease_ttl_ms, now);
        Ok(Some(record.clone()))
    }

    async fn renew_lease(
        &self,
        action_id: &ActionId,
        worker_id: &str,
        lease_id: &str,
        lease_ttl_ms: u64,
        now: OffsetDateTime,
    ) -> RuntimeResult<Option<QueuedActionRecord>> {
        let mut records = self.records.write().await;
        let Some(record) = records.get_mut(action_id) else {
            return Ok(None);
        };
        if record
            .lease
            .as_ref()
            .is_some_and(|lease| lease.worker_id == worker_id && lease.lease_id == lease_id)
        {
            extend_action_lease(record, lease_ttl_ms, now);
            return Ok(Some(record.clone()));
        }
        Ok(None)
    }

    async fn complete_attempt(
        &self,
        action_id: &ActionId,
        lease_id: &str,
        outcome: QueueAttemptOutcome,
    ) -> RuntimeResult<QueueCompletion> {
        let mut records = self.records.write().await;
        let Some(record) = records.get_mut(action_id) else {
            return Ok(QueueCompletion::LeaseLost);
        };
        if record.status == QueuedActionStatus::Cancelled {
            return Ok(QueueCompletion::Cancelled);
        }
        if record
            .lease
            .as_ref()
            .is_none_or(|lease| lease.lease_id != lease_id)
        {
            return Ok(QueueCompletion::LeaseLost);
        }
        match outcome {
            QueueAttemptOutcome::Retry(mut scheduled) => {
                scheduled.lease = None;
                *record = scheduled;
            }
            QueueAttemptOutcome::Settle(result) => {
                let error = result.error.clone();
                record.status = queued_status_from_action_result(result.status);
                record.result = Some(result);
                record.next_attempt_at = None;
                record.last_error = error;
                record.lease = None;
                record.updated_at = OffsetDateTime::now_utc();
            }
            QueueAttemptOutcome::DeadLetter(dead_letter) => {
                record.status = QueuedActionStatus::Failed;
                record.dead_letter_reason = Some(dead_letter.error.message.clone());
                record.last_error = Some(dead_letter.error.clone());
                record.next_attempt_at = None;
                record.lease = None;
                record.updated_at = OffsetDateTime::now_utc();
                self.dead_letters.write().await.push(dead_letter);
            }
        }
        Ok(QueueCompletion::Applied)
    }

    async fn release_lease(
        &self,
        action_id: &ActionId,
        worker_id: &str,
        lease_id: &str,
    ) -> RuntimeResult<()> {
        if let Some(record) = self.records.write().await.get_mut(action_id)
            && record
                .lease
                .as_ref()
                .is_some_and(|lease| lease.worker_id == worker_id && lease.lease_id == lease_id)
        {
            record.lease = None;
            record.status = QueuedActionStatus::Queued;
            record.updated_at = OffsetDateTime::now_utc();
        }
        Ok(())
    }

    async fn settle(&self, result: ActionResult) -> RuntimeResult<()> {
        if let Some(record) = self.records.write().await.get_mut(&result.action_id) {
            let error = result.error.clone();
            record.status = queued_status_from_action_result(result.status);
            record.result = Some(result);
            record.next_attempt_at = None;
            record.last_error = error;
            record.lease = None;
            record.updated_at = OffsetDateTime::now_utc();
        }
        Ok(())
    }

    async fn expire(&self, result: ActionResult) -> RuntimeResult<()> {
        if let Some(record) = self.records.write().await.get_mut(&result.action_id) {
            let error = result.error.clone();
            record.status = QueuedActionStatus::Expired;
            record.result = Some(result);
            record.next_attempt_at = None;
            record.last_error = error;
            record.lease = None;
            record.updated_at = OffsetDateTime::now_utc();
        }
        Ok(())
    }

    async fn cancel(&self, action_id: &ActionId, reason: Option<String>) -> RuntimeResult<()> {
        if let Some(record) = self.records.write().await.get_mut(action_id) {
            record.status = QueuedActionStatus::Cancelled;
            record.cancellation_reason = reason;
            record.next_attempt_at = None;
            record.lease = None;
            record.updated_at = OffsetDateTime::now_utc();
        }
        Ok(())
    }

    async fn increment_attempts(
        &self,
        action_id: &ActionId,
    ) -> RuntimeResult<Option<QueuedActionRecord>> {
        let mut records = self.records.write().await;
        let Some(record) = records.get_mut(action_id) else {
            return Ok(None);
        };
        let now = OffsetDateTime::now_utc();
        record.attempts = record.attempts.saturating_add(1);
        record.first_attempted_at.get_or_insert(now);
        record.last_attempted_at = Some(now);
        record.next_attempt_at = None;
        record.last_error = None;
        record.updated_at = now;
        Ok(Some(record.clone()))
    }

    async fn dead_letter(&self, record: DeadLetterRecord) -> RuntimeResult<()> {
        {
            let mut records = self.records.write().await;
            if let Some(queued) = records.get_mut(&record.record.action.id) {
                queued.status = QueuedActionStatus::Failed;
                queued.dead_letter_reason = Some(record.error.message.clone());
                queued.last_error = Some(record.error.clone());
                queued.next_attempt_at = None;
                queued.lease = None;
                queued.updated_at = OffsetDateTime::now_utc();
            }
        }
        self.dead_letters.write().await.push(record);
        Ok(())
    }

    async fn dead_letters(&self) -> RuntimeResult<Vec<DeadLetterRecord>> {
        Ok(self.dead_letters.read().await.clone())
    }

    async fn recoverable(&self) -> RuntimeResult<Vec<QueuedActionRecord>> {
        Ok(self
            .records
            .read()
            .await
            .values()
            .filter(|record| action_is_leaseable(record, OffsetDateTime::now_utc()))
            .cloned()
            .collect())
    }

    async fn get(&self, action_id: &ActionId) -> RuntimeResult<Option<QueuedActionRecord>> {
        Ok(self.records.read().await.get(action_id).cloned())
    }

    async fn list(&self) -> RuntimeResult<Vec<QueuedActionRecord>> {
        let mut records = self
            .records
            .read()
            .await
            .values()
            .cloned()
            .collect::<Vec<_>>();
        records.sort_by_key(|record| record.created_at);
        Ok(records)
    }
}

/// Durable asynchronous action queue.
#[derive(Clone)]
pub struct ActionQueue {
    backend: Arc<dyn ActionQueueBackend>,
}

impl Default for ActionQueue {
    fn default() -> Self {
        Self::new(Arc::new(InMemoryActionQueueBackend::default()))
    }
}

impl ActionQueue {
    /// Creates an action queue backed by the supplied backend.
    #[must_use]
    pub fn new(backend: Arc<dyn ActionQueueBackend>) -> Self {
        Self { backend }
    }

    /// Inserts a queued action record or advances the same immutable action.
    pub async fn enqueue(&self, record: QueuedActionRecord) -> RuntimeResult<()> {
        self.backend.enqueue(record).await
    }

    /// Marks an action as running.
    pub async fn mark_running(&self, action_id: &ActionId) -> RuntimeResult<()> {
        self.backend.mark_running(action_id).await
    }

    /// Claims one queued or expired action for a worker.
    pub async fn lease_next(
        &self,
        worker_id: &str,
        lease_ttl_ms: u64,
    ) -> RuntimeResult<Option<QueuedActionRecord>> {
        self.backend
            .lease_next(worker_id, lease_ttl_ms, OffsetDateTime::now_utc())
            .await
    }

    /// Claims a specific queued or expired action for a worker.
    pub async fn lease_action(
        &self,
        action_id: &ActionId,
        worker_id: &str,
        lease_ttl_ms: u64,
    ) -> RuntimeResult<Option<QueuedActionRecord>> {
        self.backend
            .lease_action(
                action_id,
                worker_id,
                lease_ttl_ms,
                OffsetDateTime::now_utc(),
            )
            .await
    }

    /// Claims an approval-blocked action for exactly one resume worker.
    pub async fn lease_approval_action(
        &self,
        action_id: &ActionId,
        worker_id: &str,
        lease_ttl_ms: u64,
    ) -> RuntimeResult<Option<QueuedActionRecord>> {
        self.backend
            .lease_approval_action(
                action_id,
                worker_id,
                lease_ttl_ms,
                OffsetDateTime::now_utc(),
            )
            .await
    }

    /// Renews a worker lease for one action.
    pub async fn renew_lease(
        &self,
        action_id: &ActionId,
        worker_id: &str,
        lease_id: &str,
        lease_ttl_ms: u64,
    ) -> RuntimeResult<Option<QueuedActionRecord>> {
        self.backend
            .renew_lease(
                action_id,
                worker_id,
                lease_id,
                lease_ttl_ms,
                OffsetDateTime::now_utc(),
            )
            .await
    }

    /// Commits a worker outcome only while its lease remains current.
    pub async fn complete_attempt(
        &self,
        action_id: &ActionId,
        lease_id: &str,
        outcome: QueueAttemptOutcome,
    ) -> RuntimeResult<QueueCompletion> {
        self.backend
            .complete_attempt(action_id, lease_id, outcome)
            .await
    }

    /// Releases a worker lease and returns the action to the queue.
    pub async fn release_lease(
        &self,
        action_id: &ActionId,
        worker_id: &str,
        lease_id: &str,
    ) -> RuntimeResult<()> {
        self.backend
            .release_lease(action_id, worker_id, lease_id)
            .await
    }

    /// Stores a terminal action result.
    pub async fn settle(&self, result: ActionResult) -> RuntimeResult<()> {
        self.backend.settle(result).await
    }

    /// Stores an approval-expired terminal result.
    pub async fn expire(&self, result: ActionResult) -> RuntimeResult<()> {
        self.backend.expire(result).await
    }

    /// Marks a queued action as cancelled.
    pub async fn cancel(&self, action_id: &ActionId, reason: Option<String>) -> RuntimeResult<()> {
        self.backend.cancel(action_id, reason).await
    }

    /// Increments the attempt count for a queued action.
    pub async fn increment_attempts(
        &self,
        action_id: &ActionId,
    ) -> RuntimeResult<Option<QueuedActionRecord>> {
        self.backend.increment_attempts(action_id).await
    }

    /// Moves a record into the dead-letter queue.
    pub async fn dead_letter(&self, record: DeadLetterRecord) -> RuntimeResult<()> {
        self.backend.dead_letter(record).await
    }

    /// Returns all dead-letter records.
    pub async fn dead_letters(&self) -> RuntimeResult<Vec<DeadLetterRecord>> {
        self.backend.dead_letters().await
    }

    /// Returns queued or running work that can be recovered after restart.
    pub async fn recoverable(&self) -> RuntimeResult<Vec<QueuedActionRecord>> {
        self.backend.recoverable().await
    }

    /// Returns one queue record.
    pub async fn get(&self, action_id: &ActionId) -> RuntimeResult<Option<QueuedActionRecord>> {
        self.backend.get(action_id).await
    }

    /// Returns all known queue records for the operational read model.
    pub async fn list(&self) -> RuntimeResult<Vec<QueuedActionRecord>> {
        self.backend.list().await
    }
}

/// Durable callback delivery state retained by the runtime scheduler.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct CallbackDeliveryStateRecord {
    /// Public read-model view.
    pub view: CallbackDeliveryRecord,
    /// Envelope payload to deliver or recover after restart.
    pub envelope: Envelope,
    /// Runtime context captured when the delivery was created.
    pub context: MessageContext,
}

/// Durable callback delivery backend.
#[async_trait]
pub trait CallbackDeliveryBackend: Send + Sync {
    /// Inserts or replaces one delivery record.
    async fn upsert(&self, record: CallbackDeliveryStateRecord) -> RuntimeResult<()>;
    /// Returns one delivery record.
    async fn get(&self, delivery_id: &str) -> RuntimeResult<Option<CallbackDeliveryStateRecord>>;
    /// Returns all delivery records for the operational read model.
    async fn list(&self) -> RuntimeResult<Vec<CallbackDeliveryStateRecord>>;
    /// Returns records that may be retried after restart or worker takeover.
    async fn recoverable(
        &self,
        now: OffsetDateTime,
    ) -> RuntimeResult<Vec<CallbackDeliveryStateRecord>>;
    /// Atomically leases recoverable records for a worker.
    async fn claim_recoverable(
        &self,
        worker_id: &str,
        lease_ttl_ms: u64,
        now: OffsetDateTime,
        limit: usize,
    ) -> RuntimeResult<Vec<CallbackDeliveryStateRecord>>;
}

/// In-memory callback delivery backend for tests and single-process runtimes.
#[derive(Clone, Debug, Default)]
pub struct InMemoryCallbackDeliveryBackend {
    records: Arc<RwLock<BTreeMap<String, CallbackDeliveryStateRecord>>>,
}

#[async_trait]
impl CallbackDeliveryBackend for InMemoryCallbackDeliveryBackend {
    async fn upsert(&self, record: CallbackDeliveryStateRecord) -> RuntimeResult<()> {
        self.records
            .write()
            .await
            .insert(record.view.delivery_id.clone(), record);
        Ok(())
    }

    async fn get(&self, delivery_id: &str) -> RuntimeResult<Option<CallbackDeliveryStateRecord>> {
        Ok(self.records.read().await.get(delivery_id).cloned())
    }

    async fn list(&self) -> RuntimeResult<Vec<CallbackDeliveryStateRecord>> {
        Ok(self.records.read().await.values().cloned().collect())
    }

    async fn recoverable(
        &self,
        now: OffsetDateTime,
    ) -> RuntimeResult<Vec<CallbackDeliveryStateRecord>> {
        Ok(self
            .records
            .read()
            .await
            .values()
            .filter(|record| callback_delivery_is_recoverable(record, now))
            .cloned()
            .collect())
    }

    async fn claim_recoverable(
        &self,
        worker_id: &str,
        lease_ttl_ms: u64,
        now: OffsetDateTime,
        limit: usize,
    ) -> RuntimeResult<Vec<CallbackDeliveryStateRecord>> {
        if limit == 0 {
            return Ok(Vec::new());
        }
        let mut records = self.records.write().await;
        let mut claimed = Vec::new();
        for record in records.values_mut() {
            if callback_delivery_is_recoverable(record, now) {
                lease_callback_delivery(record, worker_id, lease_ttl_ms, now);
                claimed.push(record.clone());
                if claimed.len() == limit {
                    break;
                }
            }
        }
        Ok(claimed)
    }
}

/// Callback delivery store backed by a pluggable backend.
#[derive(Clone)]
pub struct CallbackDeliveryStore {
    backend: Arc<dyn CallbackDeliveryBackend>,
}

impl Default for CallbackDeliveryStore {
    fn default() -> Self {
        Self::new(Arc::new(InMemoryCallbackDeliveryBackend::default()))
    }
}

impl CallbackDeliveryStore {
    /// Creates a callback delivery store backed by the supplied backend.
    #[must_use]
    pub fn new(backend: Arc<dyn CallbackDeliveryBackend>) -> Self {
        Self { backend }
    }

    /// Inserts or replaces one delivery record.
    pub async fn upsert(&self, record: CallbackDeliveryStateRecord) -> RuntimeResult<()> {
        self.backend.upsert(record).await
    }

    /// Returns one delivery record.
    pub async fn get(
        &self,
        delivery_id: &str,
    ) -> RuntimeResult<Option<CallbackDeliveryStateRecord>> {
        self.backend.get(delivery_id).await
    }

    /// Returns all delivery records.
    pub async fn list(&self) -> RuntimeResult<Vec<CallbackDeliveryStateRecord>> {
        self.backend.list().await
    }

    /// Returns delivery records that can be retried.
    pub async fn recoverable(&self) -> RuntimeResult<Vec<CallbackDeliveryStateRecord>> {
        self.backend.recoverable(OffsetDateTime::now_utc()).await
    }

    /// Atomically leases recoverable delivery records for one worker.
    pub async fn claim_recoverable(
        &self,
        worker_id: &str,
        lease_ttl_ms: u64,
        limit: usize,
    ) -> RuntimeResult<Vec<CallbackDeliveryStateRecord>> {
        self.backend
            .claim_recoverable(worker_id, lease_ttl_ms, OffsetDateTime::now_utc(), limit)
            .await
    }
}

/// File-backed runtime store for single-node durable AIP gateways.
///
/// The store persists protocol state as deterministic JSON files under a caller
/// supplied directory. It is designed for production deployments that need
/// restart durability without introducing an external database dependency. High
/// throughput or multi-writer deployments should implement the same store
/// traits against their operational database.
#[derive(Clone, Debug)]
pub struct FileRuntimeStore {
    root: Arc<PathBuf>,
    io_lock: Arc<Mutex<()>>,
}

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
struct FileApprovalState {
    records: BTreeMap<ApprovalId, ApprovalRecord>,
    pending_transitions: BTreeMap<ApprovalId, Option<ApprovalTransitionClaim>>,
}

impl FileRuntimeStore {
    /// Opens or creates a file-backed runtime store.
    pub async fn open(root: impl Into<PathBuf>) -> io::Result<Self> {
        let root = root.into();
        fs::create_dir_all(&root).await?;
        Ok(Self {
            root: Arc::new(root),
            io_lock: Arc::default(),
        })
    }

    /// Returns the storage root directory.
    #[must_use]
    pub fn root(&self) -> &Path {
        self.root.as_path()
    }

    fn path(&self, file_name: &str) -> PathBuf {
        self.root.join(file_name)
    }

    async fn read_approval_state_unlocked(&self) -> io::Result<FileApprovalState> {
        if fs::try_exists(self.path("approval_state.json")).await? {
            return self
                .read_json_unlocked::<FileApprovalState>("approval_state.json")
                .await;
        }
        let records = self
            .read_json_unlocked::<BTreeMap<ApprovalId, ApprovalRecord>>("approvals.json")
            .await?;
        let state = FileApprovalState {
            records,
            pending_transitions: BTreeMap::new(),
        };
        self.write_json_unlocked("approval_state.json", &state)
            .await?;
        Ok(state)
    }

    async fn read_session_records_unlocked(
        &self,
    ) -> io::Result<BTreeMap<SessionId, SessionRecord>> {
        let path = self.path("sessions.json");
        let content = match fs::read_to_string(&path).await {
            Ok(content) => content,
            Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(BTreeMap::new()),
            Err(error) => return Err(error),
        };
        if content.trim().is_empty() {
            return Ok(BTreeMap::new());
        }
        let value: Value = serde_json::from_str(&content).map_err(invalid_data)?;
        if let Ok(records) =
            serde_json::from_value::<BTreeMap<SessionId, SessionRecord>>(value.clone())
        {
            return Ok(records);
        }
        let legacy =
            serde_json::from_value::<BTreeMap<SessionId, Session>>(value).map_err(invalid_data)?;
        let now = OffsetDateTime::now_utc();
        let records = legacy
            .into_iter()
            .map(|(id, session)| {
                (
                    id,
                    SessionRecord {
                        owner: session.initiator.id.clone(),
                        session,
                        resume_token_hash: String::new(),
                        resume_token_expires_at: now,
                        token_revision: 0,
                        resume_revoked: true,
                        updated_at: now,
                    },
                )
            })
            .collect::<BTreeMap<_, _>>();
        self.write_json_unlocked("sessions.json", &records).await?;
        Ok(records)
    }

    async fn read_json_unlocked<T>(&self, file_name: &str) -> io::Result<T>
    where
        T: DeserializeOwned + Default,
    {
        let path = self.path(file_name);
        let content = match fs::read_to_string(&path).await {
            Ok(content) => content,
            Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(T::default()),
            Err(error) => return Err(error),
        };
        if content.trim().is_empty() {
            return Ok(T::default());
        }
        serde_json::from_str(&content).map_err(invalid_data)
    }

    async fn write_json_unlocked<T>(&self, file_name: &str, value: &T) -> io::Result<()>
    where
        T: Serialize,
    {
        let path = self.path(file_name);
        let temp_path = path.with_extension("json.tmp");
        let content = serde_json::to_vec_pretty(value).map_err(invalid_data)?;
        fs::write(&temp_path, content).await?;
        fs::rename(temp_path, path).await
    }

    async fn read_json<T>(&self, file_name: &str) -> io::Result<T>
    where
        T: DeserializeOwned + Default,
    {
        let _guard = self.io_lock.lock().await;
        self.read_json_unlocked(file_name).await
    }

    async fn mutate_json<T, F>(&self, file_name: &str, mutate: F) -> io::Result<()>
    where
        T: Serialize + DeserializeOwned + Default,
        F: FnOnce(&mut T),
    {
        let _guard = self.io_lock.lock().await;
        let mut value = self.read_json_unlocked::<T>(file_name).await?;
        mutate(&mut value);
        self.write_json_unlocked(file_name, &value).await
    }

    async fn append_json_line_unlocked<T>(&self, file_name: &str, value: &T) -> io::Result<()>
    where
        T: Serialize,
    {
        let path = self.path(file_name);
        let mut content = match fs::read_to_string(&path).await {
            Ok(content) => content,
            Err(error) if error.kind() == io::ErrorKind::NotFound => String::new(),
            Err(error) => return Err(error),
        };
        if !content.is_empty() && !content.ends_with('\n') {
            content.push('\n');
        }
        content.push_str(&serde_json::to_string(value).map_err(invalid_data)?);
        content.push('\n');
        fs::write(path, content).await
    }

    async fn read_json_lines<T>(&self, file_name: &str) -> io::Result<Vec<T>>
    where
        T: DeserializeOwned,
    {
        let _guard = self.io_lock.lock().await;
        self.read_json_lines_unlocked(file_name).await
    }

    async fn read_json_lines_unlocked<T>(&self, file_name: &str) -> io::Result<Vec<T>>
    where
        T: DeserializeOwned,
    {
        let path = self.path(file_name);
        let content = match fs::read_to_string(&path).await {
            Ok(content) => content,
            Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(Vec::new()),
            Err(error) => return Err(error),
        };
        content
            .lines()
            .filter(|line| !line.trim().is_empty())
            .map(|line| serde_json::from_str(line).map_err(invalid_data))
            .collect()
    }

    async fn write_json_lines_unlocked<T>(&self, file_name: &str, values: &[T]) -> io::Result<()>
    where
        T: Serialize,
    {
        let path = self.path(file_name);
        let temp_path = path.with_extension("jsonl.tmp");
        let mut content = String::new();
        for value in values {
            content.push_str(&serde_json::to_string(value).map_err(invalid_data)?);
            content.push('\n');
        }
        fs::write(&temp_path, content).await?;
        fs::rename(temp_path, path).await
    }
}

#[async_trait]
impl ReplayBackend for FileRuntimeStore {
    async fn claim(&self, message_id: &str, expires_at: OffsetDateTime) -> RuntimeResult<bool> {
        let _guard = self.io_lock.lock().await;
        let now = OffsetDateTime::now_utc();
        let mut claims = self
            .read_json_unlocked::<BTreeMap<String, OffsetDateTime>>("replay_registry.json")
            .await
            .map_err(storage_error)?;
        claims.retain(|_, expiry| *expiry > now);
        if claims.contains_key(message_id) {
            self.write_json_unlocked("replay_registry.json", &claims)
                .await
                .map_err(storage_error)?;
            return Ok(false);
        }
        claims.insert(message_id.to_owned(), expires_at);
        self.write_json_unlocked("replay_registry.json", &claims)
            .await
            .map_err(storage_error)?;
        Ok(true)
    }
}

fn profile_state_file_key(namespace: &str, key: &str) -> String {
    format!("{namespace}\0{key}")
}

#[async_trait]
impl ProfileStateBackend for FileRuntimeStore {
    async fn compare_and_set(
        &self,
        namespace: &str,
        key: &str,
        expected_revision: Option<u64>,
        value: Value,
    ) -> RuntimeResult<ProfileStateCasOutcome> {
        validate_profile_state_selector(namespace, key)?;
        let _guard = self.io_lock.lock().await;
        let mut entries = self
            .read_json_unlocked::<BTreeMap<String, ProfileStateEntry>>("profile_state.json")
            .await
            .map_err(storage_error)?;
        let map_key = profile_state_file_key(namespace, key);
        let current = entries.get(&map_key).cloned();
        if current.as_ref().map(|entry| entry.revision) != expected_revision {
            return Ok(ProfileStateCasOutcome::Conflict(current));
        }
        let entry = ProfileStateEntry {
            namespace: namespace.to_owned(),
            key: key.to_owned(),
            value,
            revision: expected_revision.unwrap_or(0).saturating_add(1),
            updated_at: OffsetDateTime::now_utc(),
        };
        entries.insert(map_key, entry.clone());
        self.write_json_unlocked("profile_state.json", &entries)
            .await
            .map_err(storage_error)?;
        Ok(ProfileStateCasOutcome::Applied(entry))
    }

    async fn get(&self, namespace: &str, key: &str) -> RuntimeResult<Option<ProfileStateEntry>> {
        validate_profile_state_selector(namespace, key)?;
        let entries = self
            .read_json::<BTreeMap<String, ProfileStateEntry>>("profile_state.json")
            .await
            .map_err(storage_error)?;
        Ok(entries
            .get(&profile_state_file_key(namespace, key))
            .cloned())
    }

    async fn list(
        &self,
        namespace: &str,
        key_prefix: Option<&str>,
    ) -> RuntimeResult<Vec<ProfileStateEntry>> {
        validate_profile_state_namespace(namespace)?;
        let entries = self
            .read_json::<BTreeMap<String, ProfileStateEntry>>("profile_state.json")
            .await
            .map_err(storage_error)?;
        let mut records = entries
            .into_values()
            .filter(|entry| entry.namespace == namespace)
            .filter(|entry| key_prefix.is_none_or(|prefix| entry.key.starts_with(prefix)))
            .collect::<Vec<_>>();
        records.sort_by(|left, right| left.key.cmp(&right.key));
        Ok(records)
    }

    async fn delete(
        &self,
        namespace: &str,
        key: &str,
        expected_revision: u64,
    ) -> RuntimeResult<bool> {
        validate_profile_state_selector(namespace, key)?;
        let _guard = self.io_lock.lock().await;
        let mut entries = self
            .read_json_unlocked::<BTreeMap<String, ProfileStateEntry>>("profile_state.json")
            .await
            .map_err(storage_error)?;
        let map_key = profile_state_file_key(namespace, key);
        if entries
            .get(&map_key)
            .is_none_or(|entry| entry.revision != expected_revision)
        {
            return Ok(false);
        }
        entries.remove(&map_key);
        self.write_json_unlocked("profile_state.json", &entries)
            .await
            .map_err(storage_error)?;
        Ok(true)
    }
}

#[async_trait]
impl StorageHealthBackend for FileRuntimeStore {
    async fn check(&self) -> RuntimeResult<()> {
        let _guard = self.io_lock.lock().await;
        let marker = json!({ "checked_at": OffsetDateTime::now_utc() });
        self.write_json_unlocked("readiness.json", &marker)
            .await
            .map_err(storage_error)?;
        let persisted = self
            .read_json_unlocked::<Value>("readiness.json")
            .await
            .map_err(storage_error)?;
        if persisted != marker {
            return Err(RuntimeError::Storage(
                "file storage readiness marker did not round-trip".to_owned(),
            ));
        }
        Ok(())
    }
}

#[async_trait]
impl RuntimeMaintenanceBackend for FileRuntimeStore {
    async fn apply_retention(
        &self,
        policy: RuntimeRetentionPolicy,
        now: OffsetDateTime,
    ) -> RuntimeResult<RuntimeRetentionReport> {
        let _guard = self.io_lock.lock().await;
        let event_cutoff = retention_cutoff(now, policy.event_retention_ms);
        let dead_letter_cutoff = retention_cutoff(now, policy.dead_letter_retention_ms);
        let callback_cutoff = retention_cutoff(now, policy.callback_retention_ms);
        let mut report = RuntimeRetentionReport::default();

        let mut events = self
            .read_json_lines_unlocked::<Event>("events.jsonl")
            .await
            .map_err(storage_error)?;
        let events_before = events.len();
        events.retain(|event| event.occurred_at >= event_cutoff);
        report.events_deleted = (events_before - events.len()) as u64;
        self.write_json_lines_unlocked("events.jsonl", &events)
            .await
            .map_err(storage_error)?;

        let mut replay = self
            .read_json_unlocked::<BTreeMap<String, OffsetDateTime>>("replay_registry.json")
            .await
            .map_err(storage_error)?;
        let replay_before = replay.len();
        replay.retain(|_, expires_at| *expires_at > now);
        report.replay_claims_deleted = (replay_before - replay.len()) as u64;
        self.write_json_unlocked("replay_registry.json", &replay)
            .await
            .map_err(storage_error)?;

        let mut dead_letters = self
            .read_json_unlocked::<Vec<DeadLetterRecord>>("dead_letters.json")
            .await
            .map_err(storage_error)?;
        let dead_letters_before = dead_letters.len();
        dead_letters.retain(|record| record.failed_at >= dead_letter_cutoff);
        report.dead_letters_deleted = (dead_letters_before - dead_letters.len()) as u64;
        self.write_json_unlocked("dead_letters.json", &dead_letters)
            .await
            .map_err(storage_error)?;

        let mut callbacks = self
            .read_json_unlocked::<BTreeMap<String, CallbackDeliveryStateRecord>>(
                "callback_deliveries.json",
            )
            .await
            .map_err(storage_error)?;
        let callbacks_before = callbacks.len();
        callbacks.retain(|_, record| {
            !matches!(
                record.view.status,
                CallbackDeliveryStatus::Delivered | CallbackDeliveryStatus::DeadLettered
            ) || record.view.updated_at >= callback_cutoff
        });
        report.callback_deliveries_deleted = (callbacks_before - callbacks.len()) as u64;
        self.write_json_unlocked("callback_deliveries.json", &callbacks)
            .await
            .map_err(storage_error)?;
        Ok(report)
    }
}

#[async_trait]
impl SessionStore for FileRuntimeStore {
    async fn insert(&self, record: SessionRecord) -> RuntimeResult<()> {
        let _guard = self.io_lock.lock().await;
        let mut sessions = self
            .read_session_records_unlocked()
            .await
            .map_err(storage_error)?;
        if sessions.contains_key(&record.session.id) {
            return Err(RuntimeError::Storage(format!(
                "session `{}` already exists",
                record.session.id
            )));
        }
        sessions.insert(record.session.id.clone(), record);
        self.write_json_unlocked("sessions.json", &sessions)
            .await
            .map_err(storage_error)
    }

    async fn get(&self, id: &SessionId) -> RuntimeResult<Option<SessionRecord>> {
        let _guard = self.io_lock.lock().await;
        self.read_session_records_unlocked()
            .await
            .map(|sessions| sessions.get(id).cloned())
            .map_err(storage_error)
    }

    async fn list(&self) -> RuntimeResult<Vec<SessionRecord>> {
        let _guard = self.io_lock.lock().await;
        self.read_session_records_unlocked()
            .await
            .map(|sessions| sessions.into_values().collect())
            .map_err(storage_error)
    }

    async fn transition(&self, id: &SessionId, next: SessionState) -> RuntimeResult<SessionRecord> {
        let _guard = self.io_lock.lock().await;
        let mut sessions = self
            .read_session_records_unlocked()
            .await
            .map_err(storage_error)?;
        let record = sessions
            .get_mut(id)
            .ok_or_else(|| RuntimeError::SessionNotFound(id.to_string()))?;
        if !record.session.state.can_transition_to(next) {
            return Err(RuntimeError::Handler(format!(
                "invalid transition from {} to {}",
                record.session.state.as_str(),
                next.as_str()
            )));
        }
        record.session.state = next;
        record.updated_at = OffsetDateTime::now_utc();
        let updated = record.clone();
        self.write_json_unlocked("sessions.json", &sessions)
            .await
            .map_err(storage_error)?;
        Ok(updated)
    }

    async fn rotate_resume_token(
        &self,
        id: &SessionId,
        owner: &PrincipalId,
        presented_hash: &str,
        replacement_hash: String,
        replacement_expires_at: OffsetDateTime,
        now: OffsetDateTime,
    ) -> RuntimeResult<SessionRecord> {
        let _guard = self.io_lock.lock().await;
        let mut sessions = self
            .read_session_records_unlocked()
            .await
            .map_err(storage_error)?;
        let record = sessions
            .get_mut(id)
            .ok_or_else(|| RuntimeError::SessionNotFound(id.to_string()))?;
        record.validate_resume(owner, presented_hash, now)?;
        record.resume_token_hash = replacement_hash;
        record.resume_token_expires_at = replacement_expires_at;
        record.token_revision = record.token_revision.saturating_add(1);
        record.updated_at = now;
        let updated = record.clone();
        self.write_json_unlocked("sessions.json", &sessions)
            .await
            .map_err(storage_error)?;
        Ok(updated)
    }

    async fn revoke_resume_token(
        &self,
        id: &SessionId,
        owner: &PrincipalId,
    ) -> RuntimeResult<SessionRecord> {
        let _guard = self.io_lock.lock().await;
        let mut sessions = self
            .read_session_records_unlocked()
            .await
            .map_err(storage_error)?;
        let record = sessions
            .get_mut(id)
            .ok_or_else(|| RuntimeError::SessionNotFound(id.to_string()))?;
        if &record.owner != owner {
            return Err(RuntimeError::Authorization(
                "session owner does not match authenticated principal".to_owned(),
            ));
        }
        record.resume_revoked = true;
        record.token_revision = record.token_revision.saturating_add(1);
        record.updated_at = OffsetDateTime::now_utc();
        let updated = record.clone();
        self.write_json_unlocked("sessions.json", &sessions)
            .await
            .map_err(storage_error)?;
        Ok(updated)
    }
}

#[async_trait]
impl IdempotencyBackend for FileRuntimeStore {
    async fn get_record(&self, key: &str) -> RuntimeResult<Option<IdempotencyRecord>> {
        self.read_json::<BTreeMap<String, IdempotencyRecord>>("idempotency.json")
            .await
            .map(|records| {
                records
                    .get(key)
                    .filter(|record| !idempotency_record_expired(record))
                    .cloned()
            })
            .map_err(storage_error)
    }

    async fn insert_record(&self, record: IdempotencyRecord) -> RuntimeResult<()> {
        self.mutate_json::<BTreeMap<String, IdempotencyRecord>, _>("idempotency.json", |records| {
            records.insert(record.key.clone(), record);
        })
        .await
        .map_err(storage_error)
    }

    async fn reserve(
        &self,
        reservation: IdempotencyReservation,
    ) -> RuntimeResult<IdempotencyReservationOutcome> {
        let _guard = self.io_lock.lock().await;
        let mut records = self
            .read_json_unlocked::<BTreeMap<String, IdempotencyRecord>>("idempotency.json")
            .await
            .map_err(storage_error)?;
        let mut reservations = self
            .read_json_unlocked::<BTreeMap<String, IdempotencyReservation>>(
                "idempotency_reservations.json",
            )
            .await
            .map_err(storage_error)?;
        if let Some(record) = records.get(&reservation.key).cloned() {
            if idempotency_record_expired(&record) {
                records.remove(&reservation.key);
                self.write_json_unlocked("idempotency.json", &records)
                    .await
                    .map_err(storage_error)?;
            } else if reservation_may_resume_pending(&reservation, &record) {
                records.remove(&reservation.key);
                reservations.insert(reservation.key.clone(), reservation);
                self.write_json_unlocked("idempotency.json", &records)
                    .await
                    .map_err(storage_error)?;
                self.write_json_unlocked("idempotency_reservations.json", &reservations)
                    .await
                    .map_err(storage_error)?;
                return Ok(IdempotencyReservationOutcome::Acquired);
            } else {
                return Ok(IdempotencyReservationOutcome::Settled(Box::new(record)));
            }
        }
        if let Some(existing) = reservations.get(&reservation.key)
            && existing.expires_at > OffsetDateTime::now_utc()
        {
            return Ok(IdempotencyReservationOutcome::InProgress(existing.clone()));
        }
        reservations.insert(reservation.key.clone(), reservation);
        self.write_json_unlocked("idempotency_reservations.json", &reservations)
            .await
            .map_err(storage_error)?;
        Ok(IdempotencyReservationOutcome::Acquired)
    }

    async fn settle_reservation(
        &self,
        reservation: &IdempotencyReservation,
        record: IdempotencyRecord,
    ) -> RuntimeResult<()> {
        let _guard = self.io_lock.lock().await;
        let mut reservations = self
            .read_json_unlocked::<BTreeMap<String, IdempotencyReservation>>(
                "idempotency_reservations.json",
            )
            .await
            .map_err(storage_error)?;
        if reservations
            .get(&reservation.key)
            .is_none_or(|current| current.reservation_id != reservation.reservation_id)
        {
            return Err(RuntimeError::Storage(format!(
                "idempotency reservation `{}` is no longer owned by action `{}`",
                reservation.key, reservation.action_id
            )));
        }
        let mut records = self
            .read_json_unlocked::<BTreeMap<String, IdempotencyRecord>>("idempotency.json")
            .await
            .map_err(storage_error)?;
        records.insert(record.key.clone(), record);
        reservations.remove(&reservation.key);
        self.write_json_unlocked("idempotency.json", &records)
            .await
            .map_err(storage_error)?;
        self.write_json_unlocked("idempotency_reservations.json", &reservations)
            .await
            .map_err(storage_error)
    }

    async fn renew_reservation(
        &self,
        reservation: &IdempotencyReservation,
        expires_at: OffsetDateTime,
    ) -> RuntimeResult<bool> {
        let _guard = self.io_lock.lock().await;
        let mut reservations = self
            .read_json_unlocked::<BTreeMap<String, IdempotencyReservation>>(
                "idempotency_reservations.json",
            )
            .await
            .map_err(storage_error)?;
        let Some(current) = reservations.get_mut(&reservation.key) else {
            return Ok(false);
        };
        if current.reservation_id != reservation.reservation_id
            || current.action_id != reservation.action_id
        {
            return Ok(false);
        }
        current.expires_at = expires_at;
        self.write_json_unlocked("idempotency_reservations.json", &reservations)
            .await
            .map_err(storage_error)?;
        Ok(true)
    }

    async fn release_reservation(&self, reservation: &IdempotencyReservation) -> RuntimeResult<()> {
        let _guard = self.io_lock.lock().await;
        let mut reservations = self
            .read_json_unlocked::<BTreeMap<String, IdempotencyReservation>>(
                "idempotency_reservations.json",
            )
            .await
            .map_err(storage_error)?;
        if reservations
            .get(&reservation.key)
            .is_some_and(|current| current.reservation_id == reservation.reservation_id)
        {
            reservations.remove(&reservation.key);
            self.write_json_unlocked("idempotency_reservations.json", &reservations)
                .await
                .map_err(storage_error)?;
        }
        Ok(())
    }
}

#[async_trait]
impl EventStore for FileRuntimeStore {
    async fn append(&self, event: Event) -> RuntimeResult<Event> {
        self.append_with_outcome(event)
            .await
            .map(EventAppendOutcome::into_event)
    }

    async fn append_with_outcome(&self, event: Event) -> RuntimeResult<EventAppendOutcome> {
        validate_event_record_size(&event)?;
        let _guard = self.io_lock.lock().await;
        let events = self
            .read_json_lines_unlocked::<Event>("events.jsonl")
            .await
            .map_err(storage_error)?;
        if let Some(existing) = events.iter().find(|existing| existing.id == event.id) {
            return Ok(EventAppendOutcome::Replayed(existing.clone()));
        }
        self.append_json_line_unlocked("events.jsonl", &event)
            .await
            .map_err(storage_error)?;
        Ok(EventAppendOutcome::Inserted(event))
    }

    async fn stream(&self, request: &EventStreamRequest) -> RuntimeResult<EventStream> {
        let events = self
            .read_json_lines::<Event>("events.jsonl")
            .await
            .map_err(storage_error)?;
        select_events(&events, request).map_err(|error| RuntimeError::Protocol(*error))
    }

    async fn stream_checked(&self, request: &EventStreamRequest) -> RuntimeResult<EventStream> {
        let events = self
            .read_json_lines::<Event>("events.jsonl")
            .await
            .map_err(storage_error)?;
        select_events_checked(&events, request).map_err(|error| RuntimeError::Protocol(*error))
    }

    async fn stream_tenant_checked(
        &self,
        tenant_id: &str,
        request: &EventStreamRequest,
    ) -> RuntimeResult<EventStream> {
        let events = self
            .read_json_lines::<Event>("events.jsonl")
            .await
            .map_err(storage_error)?;
        select_tenant_events_checked(&events, tenant_id, request)
            .map_err(|error| RuntimeError::Protocol(*error))
    }

    async fn stream_action_checked(
        &self,
        action_id: &ActionId,
        request: &EventStreamRequest,
    ) -> RuntimeResult<EventStream> {
        let events = self
            .read_json_lines::<Event>("events.jsonl")
            .await
            .map_err(storage_error)?;
        select_action_events_checked(&events, action_id, request)
            .map_err(|error| RuntimeError::Protocol(*error))
    }
}

