    /// Reads the event stream through the strict protocol query path.
    pub async fn event_stream_response(&self, request: EventStreamRequest) -> MessageBody {
        self.event_stream_response_with_context(request, &MessageContext::default())
            .await
    }

    /// Reads the event stream through authenticated query authorization.
    pub async fn event_stream_response_with_context(
        &self,
        request: EventStreamRequest,
        context: &MessageContext,
    ) -> MessageBody {
        let tenant_id = context
            .tenant
            .as_ref()
            .map(|tenant| tenant.tenant.id.as_str());
        let additional_scopes = if tenant_id.is_some() {
            BTreeSet::new()
        } else {
            BTreeSet::from(["events:read:any".to_owned()])
        };
        if let Err(error) = self.authorize_query(
            context,
            RuntimeQueryAuthorization::new(
                QueryObject::Event,
                QueryOperation::Read,
                None,
                None,
                tenant_id,
                additional_scopes,
                BTreeSet::from(["data".to_owned()]),
            ),
        ) {
            return MessageBody::Error(ErrorBody { error });
        }
        let result = match tenant_id {
            Some(tenant_id) => self.events.stream_tenant_checked(tenant_id, &request).await,
            None => self.events.stream_checked(&request).await,
        };
        match result {
            Ok(stream) => MessageBody::EventStream(stream),
            Err(error) => runtime_error_body(&error),
        }
    }

    async fn persist_action_result(
        &self,
        result: ActionResult,
        context: &MessageContext,
    ) -> RuntimeResult<()> {
        let already_recorded = self
            .lifecycle
            .action_result(&result.action_id)
            .await?
            .is_some();
        self.lifecycle.record_action_result(result.clone()).await?;
        self.persist_action_result_audit_event(&result, context)
            .await?;
        if already_recorded {
            return Ok(());
        }
        let mut event = event_from_context(
            "aip.action.result",
            context,
            json!({
                "action_id": result.action_id,
                "status": result.status
            }),
        );
        event.action_id = Some(result.action_id);
        self.events.append(event).await?;
        Ok(())
    }

    async fn persist_action_result_audit_event(
        &self,
        result: &ActionResult,
        context: &MessageContext,
    ) -> RuntimeResult<()> {
        let audit_id = format!("audit:action:{}:result", result.action_id);
        if self.lifecycle.audit_event(&audit_id).await?.is_some() {
            return Ok(());
        }

        let actor = context
            .authenticated
            .as_ref()
            .map(|authenticated| authenticated.principal.clone())
            .or_else(|| context.actor.clone())
            .unwrap_or_else(system_principal);
        let mut data = json!({
            "action_id": result.action_id,
            "status": result.status,
            "session_id": context.session_id,
            "correlation_id": context.correlation_id,
            "error_code": result.error.as_ref().map(|error| error.code.clone())
        });
        let mut transactions = self.transactions.by_action(&result.action_id).await?;
        transactions.sort_by_key(|record| record.updated_at);
        if let Some(transaction) = transactions.last()
            && let Some(object) = data.as_object_mut()
        {
            object.insert(
                "transaction_id".to_owned(),
                json!(transaction.transaction_id),
            );
            object.insert(
                "receipt_chain_id".to_owned(),
                json!(format!("transaction:{}", transaction.transaction_id)),
            );
        }
        self.lifecycle
            .record_audit_event(redact_audit_event(AuditEvent {
                id: audit_id,
                actor,
                identity: context.resolved_identity.clone(),
                action: "aip.action.result".to_owned(),
                occurred_at: OffsetDateTime::now_utc(),
                data: Some(data),
            }))
            .await
    }

    async fn persist_terminal_action_record(
        &self,
        action: &Action,
        principal: &Principal,
        context: &MessageContext,
        result: &ActionResult,
    ) -> RuntimeResult<()> {
        let existing = self.action_queue.get(&action.id).await?;
        if let Some(existing) = existing.as_ref() {
            validate_queued_action_identity(existing, action, principal)?;
        }
        let now = OffsetDateTime::now_utc();
        self.action_queue
            .enqueue(QueuedActionRecord {
                action: action.clone(),
                principal: principal.clone(),
                context: context.clone(),
                status: queued_status_from_action_result(result.status),
                result: Some(result.clone()),
                cancellation_reason: None,
                attempts: existing
                    .as_ref()
                    .map_or(1, |record| record.attempts.saturating_add(1)),
                retry_policy: None,
                first_attempted_at: existing
                    .as_ref()
                    .and_then(|record| record.first_attempted_at)
                    .or(Some(now)),
                last_attempted_at: Some(now),
                next_attempt_at: None,
                last_error: result.error.clone(),
                dead_letter_reason: None,
                lease: None,
                idempotency_reservation: None,
                created_at: existing.as_ref().map_or(now, |record| record.created_at),
                updated_at: now,
            })
            .await
    }

