    /// This is not an operational query entrypoint. The caller must already be
    /// executing inside an authenticated profile request and must apply the
    /// profile's own session/object authorization before exposing the result.
    pub async fn profile_action_status_projection(
        &self,
        request: ActionStatusRequest,
    ) -> RuntimeResult<ActionStatus> {
        self.action_status(request).await
    }

    /// Reads one action status through the strict protocol query path.
    pub async fn action_status_response(&self, request: ActionStatusRequest) -> MessageBody {
        self.action_status_response_with_context(request, &MessageContext::default())
            .await
    }

    /// Reads one action status through the strict protocol query path using caller context.
    pub async fn action_status_response_with_context(
        &self,
        request: ActionStatusRequest,
        context: &MessageContext,
    ) -> MessageBody {
        let owner = match self.action_owner(&request.action_id).await {
            Ok(owner) => owner,
            Err(error) => return runtime_error_body(&error),
        };
        if let Err(error) = self.authorize_query(
            context,
            RuntimeQueryAuthorization::new(
                QueryObject::Action,
                QueryOperation::Read,
                owner.as_ref(),
                owner.as_ref(),
                request.tenant_id.as_deref(),
                BTreeSet::new(),
                BTreeSet::new(),
            ),
        ) {
            return MessageBody::Error(ErrorBody { error });
        }
        match self
            .action_tenant_mismatch_error(&request.action_id, request.tenant_id.as_deref())
            .await
        {
            Ok(Some(error)) => return MessageBody::Error(ErrorBody { error }),
            Ok(None) => {}
            Err(error) => return runtime_error_body(&error),
        }
        match self
            .action_visibility_error(
                &request.action_id,
                context
                    .authenticated
                    .as_ref()
                    .map(|authenticated| &authenticated.principal),
            )
            .await
        {
            Ok(Some(error)) => return MessageBody::Error(ErrorBody { error }),
            Ok(None) => {}
            Err(error) => return runtime_error_body(&error),
        }
        match self.action_status(request).await {
            Ok(status) => MessageBody::ActionStatus(Box::new(status)),
            Err(error) => runtime_error_body(&error),
        }
    }

    /// Reads the final result for one action.
    ///
    /// This lookup is intentionally strict: unknown actions and non-terminal
    /// actions return protocol errors instead of synthetic empty results.
    pub async fn action_result_lookup(&self, request: ActionResultRequest) -> MessageBody {
        self.action_result_lookup_with_context(request, &MessageContext::default())
            .await
    }

    /// Reads the final result for one action using caller context.
    pub async fn action_result_lookup_with_context(
        &self,
        request: ActionResultRequest,
        context: &MessageContext,
    ) -> MessageBody {
        let owner = match self.action_owner(&request.action_id).await {
            Ok(owner) => owner,
            Err(error) => return runtime_error_body(&error),
        };
        if let Err(error) = self.authorize_query(
            context,
            RuntimeQueryAuthorization::new(
                QueryObject::Action,
                QueryOperation::Read,
                owner.as_ref(),
                owner.as_ref(),
                request.tenant_id.as_deref(),
                BTreeSet::new(),
                BTreeSet::from(["result".to_owned(), "receipt".to_owned()]),
            ),
        ) {
            return MessageBody::Error(ErrorBody { error });
        }
        match self
            .action_tenant_mismatch_error(&request.action_id, request.tenant_id.as_deref())
            .await
        {
            Ok(Some(error)) => return MessageBody::Error(ErrorBody { error }),
            Ok(None) => {}
            Err(error) => return runtime_error_body(&error),
        }
        match self
            .action_visibility_error(
                &request.action_id,
                context
                    .authenticated
                    .as_ref()
                    .map(|authenticated| &authenticated.principal),
            )
            .await
        {
            Ok(Some(error)) => return MessageBody::Error(ErrorBody { error }),
            Ok(None) => {}
            Err(error) => return runtime_error_body(&error),
        }
        let status = match self
            .build_action_status(
                &request.action_id,
                true,
                request.include_receipt,
                request.include_terminal_events,
            )
            .await
        {
            Ok(status) => status,
            Err(error) => return runtime_error_body(&error),
        };
        let Some(result) = status.result else {
            if status.state == ActionLifecycleState::Unknown {
                return query_error_body(
                    "action.not_found",
                    format!("action `{}` was not found", request.action_id),
                    ErrorCategory::Permanent,
                    Some(json!({ "action_id": request.action_id })),
                );
            }
            if status.state == ActionLifecycleState::DeadLettered {
                return query_error_body(
                    "action.dead_lettered",
                    format!(
                        "action `{}` is parked in the dead-letter queue",
                        request.action_id
                    ),
                    ErrorCategory::Permanent,
                    Some(json!({
                        "action_id": request.action_id,
                        "state": status.state
                    })),
                );
            }
            if status.state == ActionLifecycleState::Expired {
                return query_error_body(
                    "action.gone",
                    format!("action `{}` expired by retention policy", request.action_id),
                    ErrorCategory::Permanent,
                    Some(json!({
                        "action_id": request.action_id,
                        "state": status.state
                    })),
                );
            }
            return query_error_body(
                "action.result_not_ready",
                format!("action `{}` has no terminal result yet", request.action_id),
                ErrorCategory::Temporary,
                Some(json!({
                    "action_id": request.action_id,
                    "state": status.state
                })),
            );
        };
        MessageBody::ActionResult(result)
    }

    /// Lists durable native action lifecycle views.
    #[cfg(test)]
    async fn action_list(&self, request: ActionListRequest) -> RuntimeResult<ActionList> {
        self.action_list_for_actor(request, None).await
    }

    async fn action_list_for_actor(
        &self,
        request: ActionListRequest,
        actor: Option<&Principal>,
    ) -> RuntimeResult<ActionList> {
        let mut action_ids = BTreeSet::new();
        let queued = self.action_queue.list().await?;
        let queued_by_id = queued
            .iter()
            .map(|record| (record.action.id.clone(), record.clone()))
            .collect::<BTreeMap<_, _>>();
        for record in &queued {
            action_ids.insert(record.action.id.clone());
        }
        for result in self.lifecycle.action_results().await? {
            action_ids.insert(result.action_id);
        }

        let mut actions = Vec::new();
        for action_id in action_ids {
            if !self.action_visible_to_actor(&action_id, actor).await? {
                continue;
            }
            if let Some(principal_id) = &request.principal_id
                && queued_by_id
                    .get(&action_id)
                    .is_none_or(|record| &record.principal.id != principal_id)
            {
                continue;
            }
            if let Some(tenant_id) = &request.tenant_id
                && self.action_tenant_id(&action_id).await?.as_deref() != Some(tenant_id.as_str())
            {
                continue;
            }
            let status = self
                .build_action_status(
                    &action_id,
                    request.include_results,
                    request.include_receipts,
                    false,
                )
                .await?;
            if !action_status_matches(&status, &request) {
                continue;
            }
            actions.push(status);
        }
        actions.sort_by_key(|status| status.updated_at);
        let total_size = u64::try_from(actions.len()).unwrap_or(u64::MAX);

        let start = request
            .cursor
            .as_deref()
            .and_then(parse_offset_cursor)
            .unwrap_or(0)
            .min(actions.len());
        let limit = request.limit.unwrap_or(100).clamp(1, 1000) as usize;
        let end = start.saturating_add(limit).min(actions.len());
        let cursor = (end < actions.len()).then(|| format_offset_cursor(end));
        Ok(ActionList {
            actions: actions[start..end].to_vec(),
            total_size,
            cursor,
        })
    }

    /// Lists durable native action lifecycle views through the strict protocol query path.
    pub async fn action_list_response(&self, request: ActionListRequest) -> MessageBody {
        self.action_list_response_with_context(request, &MessageContext::default())
            .await
    }

    /// Lists durable native action lifecycle views through the strict protocol query path.
    pub async fn action_list_response_with_context(
        &self,
        request: ActionListRequest,
        context: &MessageContext,
    ) -> MessageBody {
        if let Err(error) = self.authorize_query(
            context,
            RuntimeQueryAuthorization::new(
                QueryObject::Action,
                QueryOperation::Read,
                None,
                request.principal_id.as_ref(),
                request.tenant_id.as_deref(),
                BTreeSet::new(),
                BTreeSet::from(["results".to_owned(), "receipts".to_owned()]),
            ),
        ) {
            return MessageBody::Error(ErrorBody { error });
        }
        let Some(start) = checked_offset_start(request.cursor.as_deref(), "action_list") else {
            return invalid_offset_cursor_body(request.cursor.as_deref(), "action_list");
        };
        let mut request = request;
        request.cursor = Some(format_offset_cursor(start));
        match self
            .action_list_for_actor(
                request,
                context
                    .authenticated
                    .as_ref()
                    .map(|authenticated| &authenticated.principal),
            )
            .await
        {
            Ok(list) => MessageBody::ActionList(Box::new(list)),
            Err(error) => runtime_error_body(&error),
        }
    }

