    #[async_trait]
    trait RuntimeTestHandlerRegistration {
        async fn register_handler_for_test<H>(
            &self,
            capability_id: CapabilityId,
            handler: H,
        ) -> RuntimeResult<()>
        where
            H: ActionHandler + 'static;
    }

    #[async_trait]
    impl RuntimeTestHandlerRegistration for Runtime {
        async fn register_handler_for_test<H>(
            &self,
            capability_id: CapabilityId,
            handler: H,
        ) -> RuntimeResult<()>
        where
            H: ActionHandler + 'static,
        {
            let capability = self.capability_for_id(&capability_id).await?;
            let contract = capability.contract.as_ref();
            let transaction = contract.and_then(|contract| contract.transaction.as_ref());
            let support = aip_discovery::CapabilityImplementationSupport {
                invocation: true,
                cancellation: contract.is_some_and(|contract| contract.execution.supports_cancel),
                streaming: contract.is_some_and(|contract| contract.execution.supports_streaming),
                retry: contract.is_some_and(|contract| contract.execution.supports_retry),
                transaction: transaction.is_some_and(|transaction| {
                    transaction.supported_modes.iter().any(|mode| {
                        matches!(
                            mode,
                            TransactionMode::DryRun
                                | TransactionMode::Plan
                                | TransactionMode::Commit
                                | TransactionMode::Execute
                        )
                    })
                }),
                reconciliation: transaction.is_some_and(|transaction| {
                    transaction
                        .supported_modes
                        .contains(&TransactionMode::Reconcile)
                }),
                compensation: contract
                    .and_then(|contract| contract.compensation.as_ref())
                    .is_some_and(|compensation| compensation.mode == CompensationMode::Supported),
                approval: contract
                    .and_then(|contract| contract.approval.as_ref())
                    .is_some_and(|approval| approval.required),
                credentials: contract
                    .and_then(|contract| contract.credentials.as_ref())
                    .is_some_and(|credentials| credentials.required),
            };
            self.register_handler(
                capability_id,
                SupportedTestHandler {
                    inner: handler,
                    support,
                },
            )
            .await
        }
    }

    #[async_trait]
    impl DelegationRouter for DeterministicRemoteRouter {
        async fn can_route(&self, _request: &DelegationRequest) -> bool {
            true
        }

        async fn route(
            &self,
            request: &DelegationRequest,
            _context: &MessageContext,
        ) -> RuntimeResult<Option<DelegationResult>> {
            self.calls.fetch_add(1, Ordering::SeqCst);
            if !self.delay.is_zero() {
                tokio::time::sleep(self.delay).await;
            }
            if self
                .failures_remaining
                .fetch_update(Ordering::SeqCst, Ordering::SeqCst, |remaining| {
                    remaining.checked_sub(1)
                })
                .is_ok()
            {
                return Err(RuntimeError::Handler(
                    "injected remote delegation failure".to_owned(),
                ));
            }
            Ok(Some(DelegationResult {
                delegation_id: request.delegation_id.clone(),
                parent_action_id: request.parent_action_id.clone(),
                child_action_id: request.child_action.id.clone(),
                status: DelegationStatus::Completed,
                result: Some(ActionResult {
                    action_id: request.child_action.id.clone(),
                    status: ActionResultStatus::Completed,
                    output: Some(json!({ "remote": true })),
                    message: Vec::new(),
                    memory_update: None,
                    usage: None,
                    receipt: None,
                    error: None,
                }),
                error: None,
                receipt_chain: None,
                callback: None,
            }))
        }
    }

