    #[tokio::test]
    async fn tenant_catalog_capability_uses_only_the_remote_handler() {
        let principal = Principal::new(
            PrincipalId::trusted("service:remote-catalog-client"),
            PrincipalKind::Service,
        );
        let capability = Capability {
            id: CapabilityId::trusted("cap:test:remote-catalog"),
            name: "remote catalog".to_owned(),
            kind: CapabilityKind::Tool,
            input_schema: json!({ "type": "object" }),
            output_schema: Some(json!({ "type": "object" })),
            description: Some("Tenant-scoped remote test capability".to_owned()),
            risk: None,
            stability: None,
            cost: None,
            auth: None,
            bindings: Vec::new(),
            requires_human_approval: None,
            contract: None,
        };
        let handler = ContextAwareRemoteHandler::default();
        let calls = handler.calls.clone();
        let runtime = Runtime::new()
            .with_capability_catalog(TenantCatalog {
                tenant_id: "tenant-acme".to_owned(),
                definition: CapabilityDefinition {
                    capability: capability.clone(),
                    contract_digest: format!("sha256:{}", "1".repeat(64)),
                    schema_digest: format!("sha256:{}", "2".repeat(64)),
                },
            })
            .with_remote_handler(handler);

        let result = runtime
            .process_action_with_context(
                Action::new(capability.id.clone(), json!({ "value": 7 })),
                &principal,
                tenant_context(&principal, "tenant-acme", &["*"]),
            )
            .await
            .expect("tenant-visible remote action");
        assert_eq!(result.status, ActionResultStatus::Completed);
        assert_eq!(calls.load(Ordering::SeqCst), 1);

        let error = runtime
            .process_action_with_context(
                Action::new(capability.id, json!({ "value": 8 })),
                &principal,
                tenant_context(&principal, "tenant-other", &["*"]),
            )
            .await
            .expect_err("another tenant cannot resolve the capability");
        assert!(matches!(error, RuntimeError::CapabilityNotFound(_)));
        assert_eq!(calls.load(Ordering::SeqCst), 1);
    }

    #[tokio::test]
    async fn tenant_catalog_remote_handler_executes_downstream_plan_and_dry_run() {
        let principal = Principal::new(
            PrincipalId::trusted("service:remote-transaction-client"),
            PrincipalKind::Service,
        );
        let capability = Capability {
            id: CapabilityId::trusted("cap:test:remote-transaction"),
            name: "remote transaction".to_owned(),
            kind: CapabilityKind::Tool,
            input_schema: json!({ "type": "object" }),
            output_schema: Some(json!({ "type": "object" })),
            description: Some("Tenant-scoped remote transaction capability".to_owned()),
            risk: Some(RiskLevel::Medium),
            stability: None,
            cost: None,
            auth: None,
            bindings: Vec::new(),
            requires_human_approval: None,
            contract: Some(enterprise_contract(
                vec![SideEffect::Write],
                IdempotencyRequirement::Optional,
                Some(TransactionContract {
                    supported_modes: vec![
                        TransactionMode::DryRun,
                        TransactionMode::Plan,
                        TransactionMode::Commit,
                    ],
                    requires_plan_before_commit: true,
                    dry_run_fidelity: DryRunFidelity::DownstreamValidation,
                }),
            )),
        };
        let handler = ContextAwareRemoteHandler::default();
        let calls = handler.calls.clone();
        let runtime = Runtime::new()
            .with_capability_catalog(TenantCatalog {
                tenant_id: "tenant-acme".to_owned(),
                definition: CapabilityDefinition {
                    capability: capability.clone(),
                    contract_digest: format!("sha256:{}", "3".repeat(64)),
                    schema_digest: format!("sha256:{}", "4".repeat(64)),
                },
            })
            .with_remote_handler(SupportedTestHandler {
                inner: handler,
                support: aip_discovery::CapabilityImplementationSupport {
                    invocation: true,
                    transaction: true,
                    ..aip_discovery::CapabilityImplementationSupport::default()
                },
            });

        let plan_id = "plan:remote-transaction";
        let mut plan = Action::new(capability.id.clone(), json!({ "value": 7 }));
        plan.transaction = Some(ActionTransaction {
            mode: TransactionMode::Plan,
            transaction_id: None,
            plan_id: Some(plan_id.to_owned()),
            compensation_for: None,
        });
        let plan_result = runtime
            .process_action_with_context(
                plan,
                &principal,
                tenant_context(&principal, "tenant-acme", &["*"]),
            )
            .await
            .expect("remote transaction plan");

        assert_eq!(plan_result.status, ActionResultStatus::Completed);
        assert_eq!(
            plan_result.output.as_ref().and_then(
                |output| output.pointer("/plan/metadata/connector_validation/output/remote")
            ),
            Some(&json!(true))
        );
        assert_eq!(
            runtime
                .transactions
                .by_plan_id(plan_id)
                .await
                .expect("load remote transaction plan")
                .expect("stored remote transaction plan")
                .status,
            super::TransactionStatus::Planned
        );

        let mut dry_run = Action::new(capability.id, json!({ "value": 8 }));
        dry_run.transaction = Some(ActionTransaction {
            mode: TransactionMode::DryRun,
            transaction_id: None,
            plan_id: None,
            compensation_for: None,
        });
        let dry_run_result = runtime
            .process_action_with_context(
                dry_run,
                &principal,
                tenant_context(&principal, "tenant-acme", &["*"]),
            )
            .await
            .expect("remote downstream dry run");

        assert_eq!(dry_run_result.status, ActionResultStatus::Completed);
        assert_eq!(
            dry_run_result
                .output
                .as_ref()
                .and_then(|output| { output.pointer("/handler_result/output/remote") }),
            Some(&json!(true))
        );
        assert_eq!(calls.load(Ordering::SeqCst), 2);
    }

