    #[tokio::test]
    async fn manifest_admission_event_failure_publishes_nothing() {
        let mut runtime = Runtime::new();
        runtime.events = EventLog::new(Arc::new(FailingAdmissionEventStore));
        let capability_id = CapabilityId::trusted("cap:test:atomic-admission");
        let manifest = Manifest {
            manifest_version: "aip-manifest/v1".to_owned(),
            agent: Principal::new(
                PrincipalId::trusted("agent:atomic-admission"),
                PrincipalKind::Agent,
            ),
            capabilities: vec![Capability {
                id: capability_id.clone(),
                name: "atomic admission".to_owned(),
                kind: CapabilityKind::Tool,
                input_schema: json!({ "type": "object" }),
                output_schema: Some(json!({ "type": "object" })),
                description: None,
                risk: None,
                stability: None,
                cost: None,
                auth: None,
                bindings: Vec::new(),
                requires_human_approval: None,
                contract: None,
            }],
            profiles: vec![ProfileId::from("aip.native.http.v1")],
            resources: Vec::new(),
            channels: Vec::new(),
            security: None,
            governance: None,
            limits: None,
            compatibility: None,
            extensions: None,
        };
        let handlers = HashMap::from([(
            capability_id.clone(),
            Arc::new(EchoHandler) as Arc<dyn ActionHandler>,
        )]);

        runtime
            .admit_manifest_with_handlers("atomic", manifest.clone(), handlers.clone())
            .await
            .expect_err("event failure must abort admission");
        assert!(runtime.discovery.read().await.manifest("atomic").is_none());
        let action_error = runtime
            .process_action(
                Action::new(capability_id.clone(), json!({ "value": 1 })),
                &manifest.agent,
            )
            .await
            .expect_err("handler must not be visible after failed admission");
        assert!(matches!(action_error, RuntimeError::CapabilityNotFound(_)));

        runtime.events = EventLog::default();
        runtime
            .admit_manifest_with_handlers("atomic", manifest, handlers)
            .await
            .expect("admission after storage recovery");
        assert!(runtime.discovery.read().await.manifest("atomic").is_some());
        let result = runtime
            .process_action(
                Action::new(capability_id, json!({ "value": 2 })),
                &Principal::new(
                    PrincipalId::trusted("agent:atomic-admission"),
                    PrincipalKind::Agent,
                ),
            )
            .await
            .expect("admitted handler");
        assert_eq!(result.status, ActionResultStatus::Completed);
    }

