    #[tokio::test]
    async fn durable_manifest_catalog_fences_cross_runtime_collisions() {
        let stores = RuntimeStores::default();
        let first = Runtime::with_stores(stores.clone());
        let second = Runtime::with_stores(stores);
        let capability_id = CapabilityId::trusted("cap:test:cluster-collision");
        let make_manifest = |agent_id: &str| Manifest {
            manifest_version: "aip-manifest/v1".to_owned(),
            agent: Principal::new(PrincipalId::trusted(agent_id), PrincipalKind::Agent),
            capabilities: vec![Capability {
                id: capability_id.clone(),
                name: "cluster collision".to_owned(),
                kind: CapabilityKind::Tool,
                input_schema: json!({ "type": "object" }),
                output_schema: None,
                description: None,
                risk: None,
                stability: None,
                cost: None,
                auth: None,
                bindings: Vec::new(),
                requires_human_approval: None,
                contract: None,
            }],
            profiles: vec![ProfileId::from("aip.native.http.v1")],
            resources: Vec::new(),
            channels: Vec::new(),
            security: None,
            governance: None,
            limits: None,
            compatibility: None,
            extensions: None,
        };
        let first_manifest = make_manifest("agent:catalog:first");
        let second_manifest = make_manifest("agent:catalog:second");
        let first_id = capability_id.clone();
        let second_id = capability_id.clone();
        let first = tokio::spawn(async move {
            first
                .admit_manifest_with_handlers(
                    "catalog:first",
                    first_manifest,
                    HashMap::from([(first_id, Arc::new(EchoHandler) as Arc<dyn ActionHandler>)]),
                )
                .await
        });
        let second = tokio::spawn(async move {
            second
                .admit_manifest_with_handlers(
                    "catalog:second",
                    second_manifest,
                    HashMap::from([(second_id, Arc::new(EchoHandler) as Arc<dyn ActionHandler>)]),
                )
                .await
        });
        let outcomes = [
            first.await.expect("first task"),
            second.await.expect("second task"),
        ];
        assert_eq!(outcomes.iter().filter(|outcome| outcome.is_ok()).count(), 1);
        let rejected = outcomes
            .iter()
            .find_map(|outcome| outcome.as_ref().err())
            .expect("one collision");
        assert!(matches!(rejected, RuntimeError::Admission(report)
            if report.issues.iter().any(|issue| issue.code == "manifest.capability.cross_manifest_collision")));
    }

    fn authenticated(principal: &Principal) -> AuthenticatedPrincipal {
        authenticated_with_scopes(principal, &["*"])
    }

    fn authenticated_with_scopes(principal: &Principal, scopes: &[&str]) -> AuthenticatedPrincipal {
        AuthenticatedPrincipal {
            principal: principal.clone(),
            scheme: AuthScheme::DidProof,
            issuer: "aip-runtime:test-authority".to_owned(),
            audience: Some("aip-runtime".to_owned()),
            scopes: scopes.iter().map(|scope| (*scope).to_owned()).collect(),
            authenticated_at: OffsetDateTime::now_utc(),
            expires_at: None,
            credential_fingerprint: None,
        }
    }

    fn authority_membership(principal: &Principal) -> AuthorityMembership {
        AuthorityMembership {
            principal_id: principal.id.clone(),
            tenant_id: None,
            roles: BTreeSet::new(),
            groups: BTreeSet::new(),
            tenant_policies: BTreeSet::from(["test-tenant-policy".to_owned()]),
            external_systems: BTreeSet::new(),
            delegated_scopes: Vec::new(),
            revision: 1,
            expires_at: None,
            revoked: false,
        }
    }

    fn runtime_with_authorities(principals: &[&Principal]) -> Runtime {
        Runtime::new().with_approval_authority(StaticApprovalAuthorityResolver::new(
            principals
                .iter()
                .map(|principal| authority_membership(principal)),
        ))
    }

    fn authenticated_context(principal: &Principal) -> MessageContext {
        scoped_context(principal, &["*"])
    }

    fn scoped_context(principal: &Principal, scopes: &[&str]) -> MessageContext {
        MessageContext {
            actor: Some(principal.clone()),
            authenticated: Some(authenticated_with_scopes(principal, scopes)),
            ..MessageContext::default()
        }
    }

    fn tenant_context(principal: &Principal, tenant_id: &str, scopes: &[&str]) -> MessageContext {
        MessageContext {
            actor: Some(principal.clone()),
            authenticated: Some(authenticated_with_scopes(principal, scopes)),
            tenant: Some(VerifiedTenant {
                tenant: TenantRef {
                    id: tenant_id.to_owned(),
                    system: Some("aip-runtime-test".to_owned()),
                },
                membership_id: format!("membership:{tenant_id}:{}", principal.id),
                roles: BTreeSet::new(),
                groups: BTreeSet::new(),
                verified_at: OffsetDateTime::now_utc(),
                expires_at: None,
            }),
            ..MessageContext::default()
        }
    }

