    #[derive(Clone, Debug, Default)]
    struct FailFirstEventAppendStore {
        inner: InMemoryEventStore,
        attempts: Arc<AtomicUsize>,
    }

    #[async_trait::async_trait]
    impl EventStore for FailFirstEventAppendStore {
        async fn append(&self, event: Event) -> RuntimeResult<Event> {
            self.append_with_outcome(event)
                .await
                .map(EventAppendOutcome::into_event)
        }

        async fn append_with_outcome(&self, event: Event) -> RuntimeResult<EventAppendOutcome> {
            if self.attempts.fetch_add(1, Ordering::SeqCst) == 0 {
                return Err(RuntimeError::Storage(
                    "injected first event append failure".to_owned(),
                ));
            }
            self.inner.append_with_outcome(event).await
        }

        async fn stream(
            &self,
            request: &EventStreamRequest,
        ) -> RuntimeResult<aip_core::EventStream> {
            self.inner.stream(request).await
        }

        async fn stream_checked(
            &self,
            request: &EventStreamRequest,
        ) -> RuntimeResult<aip_core::EventStream> {
            self.inner.stream_checked(request).await
        }

        async fn stream_tenant_checked(
            &self,
            tenant_id: &str,
            request: &EventStreamRequest,
        ) -> RuntimeResult<aip_core::EventStream> {
            self.inner.stream_tenant_checked(tenant_id, request).await
        }

        async fn stream_action_checked(
            &self,
            action_id: &ActionId,
            request: &EventStreamRequest,
        ) -> RuntimeResult<aip_core::EventStream> {
            self.inner.stream_action_checked(action_id, request).await
        }
    }

