    #[derive(Clone, Debug)]
    struct ObservableSlowHandler {
        calls: Arc<AtomicUsize>,
        completions: Arc<AtomicUsize>,
        cancellations: Arc<AtomicUsize>,
        started: Arc<tokio::sync::Notify>,
        sleep_ms: u64,
    }

    #[derive(Clone, Debug)]
    struct CheckpointingTransactionHandler {
        calls: Arc<AtomicUsize>,
        cancellations: Arc<AtomicUsize>,
        commit_sleep_ms: u64,
    }

    #[derive(Clone, Debug)]
    struct SchemaHandler {
        calls: Arc<AtomicUsize>,
    }

    #[async_trait::async_trait]
    impl ActionHandler for SchemaHandler {
        async fn handle(&self, action: Action) -> RuntimeResult<ActionResult> {
            self.calls.fetch_add(1, Ordering::SeqCst);
            Ok(ActionResult {
                action_id: action.id,
                status: ActionResultStatus::Completed,
                output: Some(json!({ "ok": true })),
                message: Vec::new(),
                memory_update: None,
                usage: None,
                receipt: None,
                error: None,
            })
        }
    }

    #[async_trait::async_trait]
    impl ActionHandler for ObservableSlowHandler {
        async fn handle(&self, action: Action) -> RuntimeResult<ActionResult> {
            self.handle_with_context(action, test_execution_context())
                .await
        }

        async fn handle_with_context(
            &self,
            action: Action,
            context: ActionExecutionContext,
        ) -> RuntimeResult<ActionResult> {
            self.calls.fetch_add(1, Ordering::SeqCst);
            self.started.notify_waiters();
            tokio::select! {
                () = context.cancellation.cancelled() => {
                    Ok(super::cancelled_result(action.id, "handler observed cancellation"))
                }
                () = tokio::time::sleep(Duration::from_millis(self.sleep_ms)) => {
                    self.completions.fetch_add(1, Ordering::SeqCst);
                    Ok(ActionResult {
                        action_id: action.id,
                        status: ActionResultStatus::Completed,
                        output: Some(json!({ "completed": true })),
                        message: Vec::new(),
                        memory_update: None,
                        usage: None,
                        receipt: None,
                        error: None,
                    })
                }
            }
        }

        async fn cancel(&self, _action: &Action) -> RuntimeResult<()> {
            self.cancellations.fetch_add(1, Ordering::SeqCst);
            Ok(())
        }
    }

    #[async_trait::async_trait]
    impl ActionHandler for CheckpointingTransactionHandler {
        async fn handle(&self, action: Action) -> RuntimeResult<ActionResult> {
            self.handle_with_context(action, test_execution_context())
                .await
        }

        async fn handle_with_context(
            &self,
            action: Action,
            context: ActionExecutionContext,
        ) -> RuntimeResult<ActionResult> {
            self.calls.fetch_add(1, Ordering::SeqCst);
            if action
                .transaction
                .as_ref()
                .is_some_and(|transaction| transaction.mode == TransactionMode::Commit)
            {
                context
                    .transaction_checkpoint
                    .checkpoint(
                        ProviderOperationRef {
                            provider: "payments:test".to_owned(),
                            operation_id: "provider-operation-42".to_owned(),
                            request_id: Some("provider-request-42".to_owned()),
                        },
                        Some("cursor:provider-operation-42".to_owned()),
                    )
                    .await?;
                tokio::time::sleep(Duration::from_millis(self.commit_sleep_ms)).await;
            }
            Ok(ActionResult {
                action_id: action.id,
                status: ActionResultStatus::Completed,
                output: Some(json!({
                    "reconciled": action.transaction.as_ref().is_some_and(|transaction| {
                        transaction.mode == TransactionMode::Reconcile
                    }),
                    "reconciliation_cursor": "cursor:terminal"
                })),
                message: Vec::new(),
                memory_update: None,
                usage: None,
                receipt: None,
                error: None,
            })
        }

        async fn cancel_with_context(
            &self,
            _action: &Action,
            _context: &ActionExecutionContext,
        ) -> RuntimeResult<()> {
            self.cancellations.fetch_add(1, Ordering::SeqCst);
            Ok(())
        }
    }

    #[derive(Clone, Debug)]
    struct CapabilityIdHandler;

    #[async_trait::async_trait]
