    #[tokio::test]
    async fn runtime_emits_discovery_events_for_manifest_updates() {
        let runtime = Runtime::new();
        let capability_id = CapabilityId::parse("cap:discovery-event").expect("cap id");
        let resource_id = "resource:discovery-event".to_owned();
        let principal = Principal::new(
            PrincipalId::parse("agent:discovery-event").expect("principal"),
            PrincipalKind::Agent,
        );
        let manifest = |capability_id: CapabilityId, resource_id: String, version: &str| Manifest {
            manifest_version: "aip-manifest/v1".to_owned(),
            agent: principal.clone(),
            capabilities: vec![Capability {
                id: capability_id.clone(),
                name: format!("discovery event {version}"),
                kind: CapabilityKind::Tool,
                input_schema: json!({"type": "object"}),
                output_schema: None,
                description: None,
                risk: None,
                stability: None,
                cost: None,
                auth: None,
                bindings: Vec::new(),
                requires_human_approval: None,
                contract: None,
            }],
            profiles: vec![ProfileId::from("aip.native.http.v1")],
            resources: vec![Resource {
                id: resource_id,
                name: format!("discovery event resource {version}"),
                kind: Some("document".to_owned()),
                capability_id: Some(capability_id),
                description: None,
                mime_type: Some("application/json".to_owned()),
                tenant_id: None,
                access: None,
                expires_at: None,
            }],
            channels: Vec::new(),
            security: None,
            governance: None,
            limits: None,
            compatibility: None,
            extensions: None,
        };
        runtime
            .admit_manifest_with_handlers(
                "discovery-event",
                manifest(capability_id.clone(), resource_id.clone(), "v1"),
                HashMap::from([(
                    capability_id.clone(),
                    Arc::new(EchoHandler) as Arc<dyn ActionHandler>,
                )]),
            )
            .await
            .expect("manifest");

        let events = runtime
            .event_stream(&EventStreamRequest {
                cursor: None,
                limit: Some(10),
                kinds: vec!["aip.discovery.manifest_admitted".to_owned()],
            })
            .await
            .expect("discovery events");
        assert_eq!(events.events.len(), 1);
        assert_eq!(events.events[0].kind, "aip.discovery.manifest_admitted");
        assert_eq!(
            events.events[0]
                .data
                .as_ref()
                .and_then(|data| data.pointer("/capability_ids/0")),
            Some(&json!(capability_id))
        );
        assert_eq!(
            events.events[0]
                .data
                .as_ref()
                .and_then(|data| data.pointer("/resource_ids/0")),
            Some(&json!(resource_id))
        );

        let replacement_capability_id =
            CapabilityId::parse("cap:discovery-event-v2").expect("cap id");
        let replacement_resource_id = "resource:discovery-event-v2".to_owned();
        runtime
            .admit_manifest_with_handlers(
                "discovery-event",
                manifest(
                    replacement_capability_id.clone(),
                    replacement_resource_id.clone(),
                    "v2",
                ),
                HashMap::from([(
                    replacement_capability_id.clone(),
                    Arc::new(EchoHandler) as Arc<dyn ActionHandler>,
                )]),
            )
            .await
            .expect("replacement manifest");

        let manifest_events = runtime
            .event_stream(&EventStreamRequest {
                cursor: None,
                limit: Some(10),
                kinds: vec!["aip.discovery.manifest_admitted".to_owned()],
            })
            .await
            .expect("replacement manifest events");
        let replacement_event = manifest_events.events.last().expect("replacement event");
        let replacement_data = replacement_event.data.as_ref().expect("event data");
        assert_eq!(
            replacement_data.pointer("/added_capability_ids/0"),
            Some(&json!(replacement_capability_id))
        );
        assert_eq!(
            replacement_data.pointer("/removed_capability_ids/0"),
            Some(&json!(capability_id))
        );
        assert_eq!(
            replacement_data.pointer("/added_resource_ids/0"),
            Some(&json!(replacement_resource_id))
        );
        assert_eq!(
            replacement_data.pointer("/removed_resource_ids/0"),
            Some(&json!(resource_id))
        );

        assert!(
            runtime
                .discovery
                .read()
                .await
                .capability(&capability_id)
                .is_none(),
            "replaced manifests must remove stale capabilities from lookup"
        );
        assert!(
            runtime
                .discovery
                .read()
                .await
                .capability(&replacement_capability_id)
                .is_some()
        );
    }

    #[tokio::test]
