    #[tokio::test]
    async fn session_resume_tokens_are_owner_bound_single_use_and_atomically_rotated() {
        let manager = super::SessionManager::default().with_resume_token_ttl(60_000);
        let owner = Principal::new(
            PrincipalId::trusted("agent:session-owner"),
            PrincipalKind::Agent,
        );
        let responder = Principal::new(
            PrincipalId::trusted("agent:session-responder"),
            PrincipalKind::Agent,
        );
        let attacker = PrincipalId::trusted("agent:session-attacker");
        let created = manager
            .create_secure(owner.clone(), responder)
            .await
            .expect("create secure session");
        assert!(
            manager
                .resume(&created.session.id, &attacker, &created.resume_token)
                .await
                .is_err()
        );

        let left = {
            let manager = manager.clone();
            let session_id = created.session.id.clone();
            let owner_id = owner.id.clone();
            let token = created.resume_token.clone();
            tokio::spawn(async move { manager.resume(&session_id, &owner_id, &token).await })
        };
        let right = {
            let manager = manager.clone();
            let session_id = created.session.id.clone();
            let owner_id = owner.id.clone();
            let token = created.resume_token.clone();
            tokio::spawn(async move { manager.resume(&session_id, &owner_id, &token).await })
        };
        let outcomes = [
            left.await.expect("left task"),
            right.await.expect("right task"),
        ];
        assert_eq!(outcomes.iter().filter(|outcome| outcome.is_ok()).count(), 1);
        assert_eq!(
            outcomes.iter().filter(|outcome| outcome.is_err()).count(),
            1
        );
        let rotated = outcomes
            .into_iter()
            .find_map(Result::ok)
            .expect("one rotated credential");
        assert!(
            manager
                .resume(&created.session.id, &owner.id, &created.resume_token)
                .await
                .is_err()
        );
        assert!(
            manager
                .resume(&created.session.id, &owner.id, &rotated.resume_token)
                .await
                .is_ok()
        );
    }

