    #[tokio::test]
    async fn runtime_records_callback_delivery_events_and_receipts() {
        let calls = Arc::new(AtomicUsize::new(0));
        let observer = RecordingExecutionObserver::default();
        let observed = observer.stages.clone();
        let runtime = Runtime::new()
            .with_execution_checkpoint_observer(Arc::new(observer))
            .with_callback_dispatcher(FailOnceCallbackDispatcher {
                calls: Arc::clone(&calls),
            });
        let capability_id = CapabilityId::parse("cap:callback-contract").expect("cap id");
        let principal = Principal::new(
            PrincipalId::parse("agent:callback-contract").expect("principal"),
            PrincipalKind::Agent,
        );
        register_echo_capability(&runtime, &principal, capability_id.clone()).await;
        let now = OffsetDateTime::now_utc();
        let mut action = Action::new(capability_id, json!({ "callback": true }));
        action.mode = Some(ActionMode::Async);
        action.callback = Some(Callback {
            profile: ProfileId::from("aip.native.http.v1"),
            target: "https://callback.example/aip/v1/messages".to_owned(),
            metadata: None,
        });
        let action_id = action.id.clone();
        runtime
            .action_queue
            .enqueue(QueuedActionRecord {
                action,
                principal: principal.clone(),
                context: authenticated_context(&principal),
                status: QueuedActionStatus::Queued,
                result: None,
                cancellation_reason: None,
                attempts: 0,
                retry_policy: None,
                first_attempted_at: None,
                last_attempted_at: None,
                next_attempt_at: None,
                last_error: None,
                dead_letter_reason: None,
                lease: None,
                idempotency_reservation: None,
                created_at: now,
                updated_at: now,
            })
            .await
            .expect("enqueue callback action");

        let result = runtime
            .run_queued_action_once("worker-callback", 60_000)
            .await
            .expect("worker claim")
            .expect("result");
        assert_eq!(result.action_id, action_id);
        assert_eq!(calls.load(Ordering::SeqCst), 2);
        let events = runtime
            .event_stream(&EventStreamRequest {
                cursor: None,
                limit: Some(20),
                kinds: vec![
                    "aip.callback.delivery_attempted".to_owned(),
                    "aip.callback.dispatched".to_owned(),
                ],
            })
            .await
            .expect("callback lifecycle events");
        assert_eq!(
            events
                .events
                .iter()
                .filter(|event| event.kind == "aip.callback.delivery_attempted")
                .count(),
            2
        );
        assert!(
            events
                .events
                .iter()
                .any(|event| event.kind == "aip.callback.dispatched")
        );
        let receipt_types = runtime
            .lifecycle
            .receipt_chains()
            .await
            .expect("callback receipt chains")
            .into_iter()
            .flat_map(|chain| chain.receipts)
            .map(|receipt| receipt.receipt_type)
            .collect::<Vec<_>>();
        assert!(receipt_types.contains(&ReceiptType::CallbackDeliveryAttempted));
        assert!(receipt_types.contains(&ReceiptType::CallbackDelivered));

        let deliveries = runtime
            .callback_delivery_list(
                CallbackDeliveryListRequest {
                    action_id: Some(action_id.clone()),
                    status: Some(CallbackDeliveryStatus::Delivered),
                    profile: None,
                    target: None,
                    tenant_id: None,
                    cursor: None,
                    limit: Some(10),
                    include_receipts: true,
                },
                None,
            )
            .await
            .expect("callback delivery list");
        assert_eq!(deliveries.deliveries.len(), 1);
        let delivery = &deliveries.deliveries[0];
        assert_eq!(delivery.status, CallbackDeliveryStatus::Delivered);
        assert_eq!(delivery.action_id.as_ref(), Some(&action_id));
        assert_eq!(delivery.attempts.len(), 2);
        assert!(delivery.receipt_chain.is_some());
        let callback_stages = observed
            .lock()
            .await
            .iter()
            .copied()
            .filter(|stage| {
                matches!(
                    stage,
                    ExecutionCheckpointStage::CallbackDispatchStarted
                        | ExecutionCheckpointStage::CallbackDelivered
                )
            })
            .collect::<Vec<_>>();
        assert_eq!(
            callback_stages,
            vec![
                ExecutionCheckpointStage::CallbackDispatchStarted,
                ExecutionCheckpointStage::CallbackDispatchStarted,
                ExecutionCheckpointStage::CallbackDelivered,
            ]
        );

        let response = runtime
            .callback_delivery_query_with_context(
                CallbackDeliveryQueryRequest {
                    delivery_id: delivery.delivery_id.clone(),
                    tenant_id: None,
                    include_receipts: true,
                },
                &scoped_context(&principal, &["callback:read"]),
            )
            .await;
        assert!(matches!(
            response,
            MessageBody::CallbackDeliveryRecord(record)
                if record.status == CallbackDeliveryStatus::Delivered
                    && record.attempts.len() == 2
                    && record.receipt_chain.is_some()
        ));
    }

    #[tokio::test]
    async fn runtime_keeps_callback_and_reconciliation_budgets_independent() {
        let started = Arc::new(tokio::sync::Notify::new());
        let release = Arc::new(tokio::sync::Notify::new());
        let runtime = Runtime::new()
            .with_work_budgets(super::RuntimeWorkBudgets {
                callback_max_in_flight: 1,
                callback_recovery_batch: 1,
                reconciliation_max_in_flight: 1,
            })
            .expect("valid work budgets")
            .with_callback_dispatcher(BlockingCallbackDispatcher {
                started: started.clone(),
                release: release.clone(),
            });
        let callback = Callback {
            profile: ProfileId::from("aip.native.http.v1"),
            target: "https://callback.example/aip/v1/messages".to_owned(),
            metadata: None,
        };
        let first_runtime = runtime.clone();
        let first_callback = callback.clone();
        let first = tokio::spawn(async move {
            first_runtime
                .dispatch_profile_callback(
                    &first_callback,
                    Envelope::new(MessageBody::Heartbeat(aip_core::Heartbeat {
                        sequence: 1,
                        status: None,
                        progress: None,
                    })),
                    MessageContext::default(),
                )
                .await
        });
        started.notified().await;

        let second = runtime
            .dispatch_profile_callback(
                &callback,
                Envelope::new(MessageBody::Heartbeat(aip_core::Heartbeat {
                    sequence: 2,
                    status: None,
                    progress: None,
                })),
                MessageContext::default(),
            )
            .await
            .expect_err("second callback must not bypass its capacity budget");
        assert!(matches!(
            second,
            RuntimeError::Protocol(ProtocolError { code, .. })
                if code == "callback.delivery_capacity"
        ));

        let reconciliation_permit = runtime
            .reconciliation_budget
            .clone()
            .try_acquire_owned()
            .expect("reserve reconciliation capacity");
        let principal = Principal::new(
            PrincipalId::trusted("agent:budget-test"),
            PrincipalKind::Agent,
        );
        let mut reconciliation = Action::new(
            CapabilityId::trusted("cap:budget-test"),
            json!({ "operation": "reconcile" }),
        );
        reconciliation.transaction = Some(ActionTransaction {
            mode: TransactionMode::Reconcile,
            transaction_id: Some(TransactionId::new()),
            plan_id: None,
            compensation_for: None,
        });
        let error = runtime
            .process_action(reconciliation, &principal)
            .await
            .expect_err("reconciliation must not use callback capacity");
        assert!(matches!(
            error,
            RuntimeError::Protocol(ProtocolError { code, .. })
                if code == "transaction.reconciliation_capacity"
        ));
        drop(reconciliation_permit);

        release.notify_one();
        first
            .await
            .expect("callback task")
            .expect("first callback succeeds");
        assert_eq!(runtime.work_budget_snapshot().callback_available, 1);
        assert_eq!(runtime.work_budget_snapshot().reconciliation_available, 1);
    }

