    #[tokio::test]
    async fn approval_quorum_requires_distinct_verified_principals() {
        let requester = Principal::new(
            PrincipalId::trusted("agent:quorum-requester"),
            PrincipalKind::Agent,
        );
        let left = Principal::new(
            PrincipalId::trusted("human:quorum-left"),
            PrincipalKind::Human,
        );
        let right = Principal::new(
            PrincipalId::trusted("human:quorum-right"),
            PrincipalKind::Human,
        );
        let runtime = runtime_with_authorities(&[&left, &right]);
        let policy = ApprovalPolicy {
            required: true,
            reason: Some("two-person control".to_owned()),
            approver_selector: ApproverSelector::TenantPolicy,
            ttl_ms: Some(60_000),
            evidence_requirements: Vec::new(),
            delegated_authority: None,
            rule: Some(ApprovalRule::Quorum {
                required: 2,
                rules: vec![
                    ApprovalRule::Principal {
                        id: left.id.clone(),
                    },
                    ApprovalRule::Principal {
                        id: right.id.clone(),
                    },
                ],
                distinct_principals: true,
            }),
            minimum_distinct_principals: 2,
            separation_of_duties: aip_core::SeparationOfDuties {
                requester_must_differ: true,
                operator_must_differ: true,
                allow_self_approval: false,
            },
            policy_version: Some("quorum-policy/v1".to_owned()),
        };
        let request = ApprovalRequest {
            id: ApprovalId::new(),
            action_id: ActionId::new(),
            capability_id: CapabilityId::trusted("cap:test:quorum"),
            requester: requester.clone(),
            subject: requester.clone(),
            approver_selector: ApproverSelector::TenantPolicy,
            reason: "two-person control".to_owned(),
            evidence: Vec::new(),
            expires_at: Some(OffsetDateTime::now_utc() + time::Duration::minutes(1)),
            policy_decision_id: Some("policy-decision:quorum".to_owned()),
            identity: None,
            policy_snapshot: Some(policy),
            policy_hash: Some("sha256:quorum-policy".to_owned()),
            operator: Some(requester.clone()),
            risk: Some(RiskLevel::High),
            governed_value: Some(10_000),
        };
        runtime
            .record_approval_request(request.clone(), authenticated_context(&requester))
            .await
            .expect("request");

        let first = runtime
            .record_approval_decision(
                approval_decision(&request, left.clone(), ApprovalDecisionKind::Approved),
                authenticated_context(&left),
            )
            .await
            .expect("first vote");
        assert_eq!(first.events[0].kind, "aip.approval.vote_recorded");
        assert_eq!(
            runtime
                .approvals
                .get(&request.id)
                .await
                .expect("approval")
                .expect("record")
                .status,
            super::ApprovalStatus::Pending
        );

        let mut duplicate_principal =
            approval_decision(&request, left.clone(), ApprovalDecisionKind::Approved);
        duplicate_principal.decision_id = Some("decision:left:second-vote".to_owned());
        runtime
            .record_approval_decision(duplicate_principal, authenticated_context(&left))
            .await
            .expect("second vote by same principal remains pending");
        assert_eq!(
            runtime
                .approvals
                .get(&request.id)
                .await
                .expect("approval")
                .expect("record")
                .status,
            super::ApprovalStatus::Pending
        );

        let terminal = runtime
            .record_approval_decision(
                approval_decision(&request, right.clone(), ApprovalDecisionKind::Approved),
                authenticated_context(&right),
            )
            .await
            .expect("independent second approver");
        assert_eq!(terminal.events[0].kind, "aip.approval.granted");
        let record = runtime
            .approvals
            .get(&request.id)
            .await
            .expect("approval")
            .expect("record");
        assert_eq!(record.status, super::ApprovalStatus::Approved);
        assert_eq!(
            record
                .decisions
                .iter()
                .map(|decision| &decision.authority.principal_id)
                .collect::<BTreeSet<_>>()
                .len(),
            2
        );
    }

    #[tokio::test]
    async fn approval_all_requires_independent_decisions_unless_reuse_is_explicit() {
        let requester = Principal::new(
            PrincipalId::trusted("agent:all-requester"),
            PrincipalKind::Agent,
        );
        let dual_role = Principal::new(
            PrincipalId::trusted("human:dual-role"),
            PrincipalKind::Human,
        );
        let compliance = Principal::new(
            PrincipalId::trusted("human:compliance"),
            PrincipalKind::Human,
        );
        let mut dual_authority = authority_membership(&dual_role);
        dual_authority.roles = BTreeSet::from(["finance".to_owned(), "compliance".to_owned()]);
        let mut compliance_authority = authority_membership(&compliance);
        compliance_authority.roles = BTreeSet::from(["compliance".to_owned()]);
        let runtime =
            Runtime::new().with_approval_authority(StaticApprovalAuthorityResolver::new([
                dual_authority,
                compliance_authority,
            ]));
        let policy = ApprovalPolicy {
            required: true,
            reason: Some("independent finance and compliance control".to_owned()),
            approver_selector: ApproverSelector::TenantPolicy,
            ttl_ms: Some(60_000),
            evidence_requirements: Vec::new(),
            delegated_authority: None,
            rule: Some(ApprovalRule::All {
                rules: vec![
                    ApprovalRule::Role {
                        name: "finance".to_owned(),
                    },
                    ApprovalRule::Role {
                        name: "compliance".to_owned(),
                    },
                ],
                allow_decision_reuse: false,
            }),
            minimum_distinct_principals: 1,
            separation_of_duties: aip_core::SeparationOfDuties {
                requester_must_differ: true,
                operator_must_differ: false,
                allow_self_approval: false,
            },
            policy_version: Some("independent-all/v1".to_owned()),
        };
        let request = ApprovalRequest {
            id: ApprovalId::new(),
            action_id: ActionId::new(),
            capability_id: CapabilityId::trusted("cap:test:independent-all"),
            requester: requester.clone(),
            subject: requester.clone(),
            approver_selector: ApproverSelector::TenantPolicy,
            reason: "independent control".to_owned(),
            evidence: Vec::new(),
            expires_at: Some(OffsetDateTime::now_utc() + time::Duration::minutes(1)),
            policy_decision_id: Some("policy-decision:independent-all".to_owned()),
            identity: None,
            policy_snapshot: Some(policy),
            policy_hash: Some("sha256:independent-all".to_owned()),
            operator: Some(requester.clone()),
            risk: Some(RiskLevel::High),
            governed_value: Some(50_000),
        };
        runtime
            .record_approval_request(request.clone(), authenticated_context(&requester))
            .await
            .expect("request");

        runtime
            .record_approval_decision(
                approval_decision(&request, dual_role.clone(), ApprovalDecisionKind::Approved),
                authenticated_context(&dual_role),
            )
            .await
            .expect("dual-role vote");
        assert_eq!(
            runtime
                .approvals
                .get(&request.id)
                .await
                .expect("approval")
                .expect("record")
                .status,
            super::ApprovalStatus::Pending,
            "one decision must not satisfy both independent branches"
        );

        let terminal = runtime
            .record_approval_decision(
                approval_decision(&request, compliance.clone(), ApprovalDecisionKind::Approved),
                authenticated_context(&compliance),
            )
            .await
            .expect("independent compliance vote");
        assert_eq!(terminal.events[0].kind, "aip.approval.granted");
    }

    #[test]
    fn delegation_path_rejects_self_hops_discontinuity_and_cycles() {
        let requester = Principal::new(
            PrincipalId::trusted("agent:requester"),
            PrincipalKind::Agent,
        );
        let delegate = Principal::new(PrincipalId::trusted("agent:delegate"), PrincipalKind::Agent);
        let request = DelegationRequest {
            delegation_id: DelegationId::new(),
            parent_action_id: ActionId::new(),
            child_action: Action::new(CapabilityId::trusted("cap:delegation:path"), json!({})),
            requested_by: requester.clone(),
            delegate: delegate.clone(),
            scope: "work.execute".to_owned(),
            callback: None,
            metadata: None,
        };
        validate_delegation_path(&request).expect("first delegation hop");

        let mut routed_wire_request = request.clone();
        routed_wire_request
            .child_action
            .delegation_chain
            .push(DelegationEntry {
                from: requester.clone(),
                to: delegate.clone(),
                scope: request.scope.clone(),
                delegated_at: OffsetDateTime::now_utc(),
            });
        assert!(current_delegation_hop_is_recorded(&routed_wire_request));
        validate_delegation_path(&routed_wire_request)
            .expect("a remote peer may receive the already-recorded current hop");

        let mut self_hop = request.clone();
        self_hop.delegate = requester.clone();
        assert!(validate_delegation_path(&self_hop).is_err());

        let origin = Principal::new(PrincipalId::trusted("agent:origin"), PrincipalKind::Agent);
        let now = OffsetDateTime::now_utc();
        let mut chained = request.clone();
        chained.child_action.delegation_chain = vec![DelegationEntry {
            from: origin.clone(),
            to: requester.clone(),
            scope: "work.plan".to_owned(),
            delegated_at: now,
        }];
        validate_delegation_path(&chained).expect("contiguous acyclic path");

        let mut cycle = chained.clone();
        cycle.delegate = origin;
        assert!(validate_delegation_path(&cycle).is_err());

        let mut discontinuous = chained;
        discontinuous
            .child_action
            .delegation_chain
            .push(DelegationEntry {
                from: delegate.clone(),
                to: Principal::new(PrincipalId::trusted("agent:other"), PrincipalKind::Agent),
                scope: "work.review".to_owned(),
                delegated_at: now,
            });
        assert!(validate_delegation_path(&discontinuous).is_err());
    }

    #[tokio::test]
    async fn runtime_schedules_async_child_delegation_and_settles_graph() {
        let runtime = Runtime::new();
        let capability_id = CapabilityId::parse("cap:delegated-async").expect("cap id");
        let requester = Principal::new(
            PrincipalId::parse("agent:requester").expect("principal"),
            PrincipalKind::Agent,
        );
        let delegate = Principal::new(
            PrincipalId::parse("agent:delegate").expect("principal"),
            PrincipalKind::Agent,
        );
        register_echo_capability(&runtime, &delegate, capability_id.clone()).await;

        let mut child_action = Action::new(capability_id, json!({ "task": "background" }));
        child_action.mode = Some(ActionMode::Async);
        let child_action_id = child_action.id.clone();
        let delegation_id = DelegationId::new();
        let result = runtime
            .process_delegation_request(
                DelegationRequest {
                    delegation_id: delegation_id.clone(),
                    parent_action_id: ActionId::new(),
                    child_action,
                    requested_by: requester.clone(),
                    delegate,
                    scope: "execute delegated async test".to_owned(),
                    callback: None,
                    metadata: None,
                },
                &requester,
                authenticated_context(&requester),
            )
            .await
            .expect("delegation");

        assert_eq!(result.status, DelegationStatus::Running);
        assert_eq!(result.child_action_id, child_action_id);
        assert!(result.result.is_none());

        for _ in 0..50 {
            if let Some(record) = runtime
                .delegations
                .get(&delegation_id)
                .await
                .expect("load delegation")
                && record.status == DelegationStatus::Completed
            {
                let settled = record.result.expect("settled result");
                assert_eq!(settled.status, DelegationStatus::Completed);
                assert_eq!(
                    settled
                        .result
                        .as_ref()
                        .and_then(|action_result| action_result.output.as_ref())
                        .and_then(|output| output.pointer("/echo/task")),
                    Some(&json!("background"))
                );
                return;
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
        panic!("delegated async child action did not settle");
    }

