    #[tokio::test]
    async fn runtime_recovers_stream_event_after_chunk_event_crash_gap() {
        let stores = RuntimeStores {
            events: EventLog::new(Arc::new(FailFirstEventAppendStore::default())),
            ..RuntimeStores::default()
        };
        let runtime = Runtime::with_stores(stores);
        let chunk = StreamChunk {
            action_id: ActionId::new(),
            sequence: 4,
            kind: StreamChunkKind::Data,
            data: Some(json!({ "delta": "durable" })),
            part: None,
        };

        let first = runtime
            .record_stream_chunk(chunk.clone(), MessageContext::default())
            .await
            .expect_err("first event append must fail after the chunk is stored");
        assert!(matches!(first, RuntimeError::Storage(_)));
        assert_eq!(
            runtime
                .lifecycle
                .stream_chunks(&chunk.action_id)
                .await
                .expect("durable chunk after event failure"),
            vec![chunk.clone()]
        );

        let recovered = runtime
            .record_stream_chunk(chunk.clone(), MessageContext::default())
            .await
            .expect("replay repairs the missing event");
        assert_eq!(recovered.events.len(), 1);
        let recovered_id = recovered.events[0].id.clone();
        let replayed = runtime
            .record_stream_chunk(chunk.clone(), MessageContext::default())
            .await
            .expect("subsequent replay is idempotent");
        assert!(replayed.events.is_empty());

        let stored = runtime
            .events
            .stream_action_checked(
                &chunk.action_id,
                &EventStreamRequest {
                    cursor: None,
                    limit: Some(10),
                    kinds: vec!["aip.stream.chunk".to_owned()],
                },
            )
            .await
            .expect("read repaired stream event");
        assert_eq!(stored.events.len(), 1);
        assert_eq!(stored.events[0].id, recovered_id);
    }

    #[tokio::test]
    async fn runtime_accepts_connector_chunks_only_for_active_streaming_execution() {
        let callback_calls = Arc::new(AtomicUsize::new(0));
        let runtime = Runtime::new().with_callback_dispatcher(RecordingCallbackDispatcher {
            calls: callback_calls.clone(),
        });
        let principal = Principal::new(
            PrincipalId::trusted("service:connector-stream-client"),
            PrincipalKind::Service,
        );
        let capability_id = CapabilityId::trusted("cap:test:connector-stream");
        let mut contract = enterprise_contract(
            vec![SideEffect::Read],
            IdempotencyRequirement::Optional,
            None,
        );
        contract.execution.supports_streaming = true;
        contract.execution.expected_completion = ExpectedCompletionMode::Streaming;
        let capability = Capability {
            id: capability_id.clone(),
            name: "connector stream".to_owned(),
            kind: CapabilityKind::Tool,
            input_schema: json!({ "type": "object" }),
            output_schema: Some(json!({ "type": "object" })),
            description: None,
            risk: None,
            stability: None,
            cost: None,
            auth: None,
            bindings: Vec::new(),
            requires_human_approval: None,
            contract: Some(contract),
        };
        let started = Arc::new(tokio::sync::Notify::new());
        let handler = ObservableSlowHandler {
            calls: Arc::new(AtomicUsize::new(0)),
            completions: Arc::new(AtomicUsize::new(0)),
            cancellations: Arc::new(AtomicUsize::new(0)),
            started: started.clone(),
            sleep_ms: 200,
        };
        runtime
            .admit_manifest_with_handlers(
                "test:connector-stream",
                Manifest {
                    manifest_version: "aip-manifest/v1".to_owned(),
                    agent: principal.clone(),
                    capabilities: vec![capability],
                    profiles: vec![ProfileId::from("aip.native.http.v1")],
                    resources: Vec::new(),
                    channels: Vec::new(),
                    security: None,
                    governance: None,
                    limits: None,
                    compatibility: None,
                    extensions: None,
                },
                HashMap::from([(
                    capability_id.clone(),
                    Arc::new(SupportedTestHandler {
                        inner: handler,
                        support: aip_discovery::CapabilityImplementationSupport {
                            invocation: true,
                            cancellation: true,
                            streaming: true,
                            retry: true,
                            ..aip_discovery::CapabilityImplementationSupport::default()
                        },
                    }) as Arc<dyn ActionHandler>,
                )]),
            )
            .await
            .expect("streaming capability admission");
        let mut action = Action::new(capability_id, json!({ "stream": true }));
        action.mode = Some(ActionMode::Streaming);
        action.callback = Some(Callback {
            profile: ProfileId::from("aip.native.http.v1"),
            target: "https://client.test/aip/v1/callbacks".to_owned(),
            metadata: None,
        });
        let action_id = action.id.clone();
        let task_runtime = runtime.clone();
        let task_principal = principal.clone();
        let task = tokio::spawn(async move {
            task_runtime
                .process_action_with_context(
                    action,
                    &task_principal,
                    authenticated_context(&task_principal),
                )
                .await
        });
        for _ in 0..50 {
            if runtime.active_actions.read().await.contains_key(&action_id) {
                break;
            }
            tokio::time::sleep(Duration::from_millis(2)).await;
        }
        assert!(runtime.active_actions.read().await.contains_key(&action_id));

        let chunk = StreamChunk {
            action_id: action_id.clone(),
            sequence: 1,
            kind: StreamChunkKind::Progress,
            data: Some(json!({ "progress": 50 })),
            part: None,
        };
        let left_runtime = runtime.clone();
        let right_runtime = runtime.clone();
        let context = MessageContext {
            actor: Some(Principal::new(
                PrincipalId::trusted("service:connector-host"),
                PrincipalKind::Service,
            )),
            ..MessageContext::default()
        };
        let event_only = runtime
            .record_stream_chunk(chunk.clone(), context.clone())
            .await
            .expect("simulate a crash after event publication and before callback delivery");
        assert_eq!(event_only.events.len(), 1);
        assert_eq!(callback_calls.load(Ordering::SeqCst), 0);
        let (left, right) = tokio::join!(
            left_runtime.ingest_assigned_connector_stream_chunk(chunk.clone(), context.clone()),
            right_runtime.ingest_assigned_connector_stream_chunk(chunk.clone(), context),
        );
        let left = left.expect("first concurrent connector stream chunk replay");
        let right = right.expect("second concurrent connector stream chunk replay");
        assert!(left.events.is_empty());
        assert!(right.events.is_empty());
        assert_eq!(
            runtime
                .lifecycle
                .stream_chunks(&action_id)
                .await
                .expect("stored chunks"),
            vec![chunk.clone()]
        );
        assert_eq!(callback_calls.load(Ordering::SeqCst), 1);
        runtime
            .ingest_assigned_connector_stream_chunk(chunk.clone(), MessageContext::default())
            .await
            .expect("identical connector chunk replay");
        assert_eq!(
            runtime
                .lifecycle
                .stream_chunks(&action_id)
                .await
                .expect("deduplicated chunks"),
            vec![chunk.clone()]
        );
        assert_eq!(callback_calls.load(Ordering::SeqCst), 1);
        let result = task.await.expect("stream task").expect("stream result");
        assert_eq!(result.status, ActionResultStatus::Completed);
        let inactive = runtime
            .ingest_assigned_connector_stream_chunk(
                StreamChunk {
                    sequence: 2,
                    ..chunk
                },
                MessageContext::default(),
            )
            .await
            .expect_err("inactive connector callback must fail");
        assert!(matches!(inactive, RuntimeError::Authorization(_)));
    }

