    #[tokio::test]
    async fn remote_delegation_settles_permanent_policy_failure_without_retry() {
        let calls = Arc::new(AtomicUsize::new(0));
        let runtime = Runtime::new().with_delegation_router(PermanentFailureRouter {
            calls: calls.clone(),
        });
        let requester = Principal::new(
            PrincipalId::trusted("agent:policy-requester"),
            PrincipalKind::Agent,
        );
        let request = DelegationRequest {
            delegation_id: DelegationId::new(),
            parent_action_id: ActionId::new(),
            child_action: Action::new(CapabilityId::trusted("cap:test:policy-denied"), json!({})),
            requested_by: requester.clone(),
            delegate: Principal::new(
                PrincipalId::trusted("agent:policy-target"),
                PrincipalKind::Agent,
            ),
            scope: "policy.denied".to_owned(),
            callback: None,
            metadata: None,
        };
        let delegation_id = request.delegation_id.clone();

        let result = runtime
            .process_delegation_request(request, &requester, authenticated_context(&requester))
            .await
            .expect("permanent failure result");

        assert_eq!(result.status, DelegationStatus::Failed);
        assert_eq!(calls.load(Ordering::SeqCst), 1);
        let receipt_chain = result
            .receipt_chain
            .as_ref()
            .expect("runtime-generated delegation receipt chain");
        assert!(
            runtime
                .lifecycle
                .receipt_chain(&receipt_chain.chain_id)
                .await
                .expect("receipt lookup")
                .is_some()
        );
        let dispatch = runtime
            .delegation_dispatch(&delegation_id)
            .await
            .expect("dispatch")
            .expect("dispatch record");
        assert_eq!(dispatch.status, DelegationDispatchStatus::Delivered);
        assert_eq!(dispatch.attempts, 1);
        assert!(dispatch.last_error.is_none());
    }

    #[tokio::test]
    async fn remote_delegation_replay_reuses_the_runtime_assigned_hop() {
        let calls = Arc::new(AtomicUsize::new(0));
        let runtime = Runtime::new().with_delegation_router(PermanentFailureRouter {
            calls: calls.clone(),
        });
        let requester = Principal::new(
            PrincipalId::trusted("agent:replay-requester"),
            PrincipalKind::Agent,
        );
        let request = DelegationRequest {
            delegation_id: DelegationId::new(),
            parent_action_id: ActionId::new(),
            child_action: Action::new(
                CapabilityId::trusted("cap:test:replay-policy-denied"),
                json!({ "stable": true }),
            ),
            requested_by: requester.clone(),
            delegate: Principal::new(
                PrincipalId::trusted("agent:replay-target"),
                PrincipalKind::Agent,
            ),
            scope: "policy.denied".to_owned(),
            callback: None,
            metadata: Some(json!({ "workflow": "replay" })),
        };

        let first = runtime
            .process_delegation_request(
                request.clone(),
                &requester,
                authenticated_context(&requester),
            )
            .await
            .expect("first terminal delegation result");
        let first_record = runtime
            .delegations
            .get(&request.delegation_id)
            .await
            .expect("first graph lookup")
            .expect("first graph record");
        assert_eq!(first_record.status, DelegationStatus::Failed);
        assert_eq!(first_record.request.child_action.delegation_chain.len(), 1);

        tokio::time::sleep(Duration::from_millis(2)).await;
        let replay = runtime
            .process_delegation_request(
                request.clone(),
                &requester,
                authenticated_context(&requester),
            )
            .await
            .expect("idempotent delegation replay");

        assert_eq!(replay, first);
        assert_eq!(calls.load(Ordering::SeqCst), 1);
        let replayed_record = runtime
            .delegations
            .get(&request.delegation_id)
            .await
            .expect("replayed graph lookup")
            .expect("replayed graph record");
        assert_eq!(replayed_record.status, DelegationStatus::Failed);
        assert_eq!(replayed_record.request, first_record.request);
    }

