    #[tokio::test]
    async fn runtime_revalidates_idempotency_input_hash_on_collision() {
        let runtime = Runtime::new();
        let capability_id = CapabilityId::parse("cap:idempotency-hash").expect("cap id");
        let principal = Principal::new(
            PrincipalId::parse("agent:idempotency").expect("principal"),
            PrincipalKind::Agent,
        );
        let mut contract = enterprise_contract(
            vec![SideEffect::Write],
            IdempotencyRequirement::Required,
            None,
        );
        contract.idempotency.collision_behavior = IdempotencyCollisionBehavior::RevalidateInputHash;
        contract.approval = None;
        register_capability_with_contract(
            &runtime,
            &principal,
            Capability {
                id: capability_id.clone(),
                name: "idempotent write".to_owned(),
                kind: CapabilityKind::Tool,
                input_schema: json!({"type": "object"}),
                output_schema: None,
                description: None,
                risk: None,
                stability: None,
                cost: None,
                auth: None,
                bindings: Vec::new(),
                requires_human_approval: None,
                contract: Some(contract),
            },
        )
        .await;
        runtime
            .register_handler_for_test(capability_id.clone(), EchoHandler)
            .await
            .expect("replace admitted handler");

        let mut first = Action::new(capability_id.clone(), json!({ "amount": 10 }));
        first.idempotency_key = Some("idem:test".to_owned());
        let first_result = runtime
            .process_action(first, &principal)
            .await
            .expect("first result");
        assert_eq!(first_result.status, ActionResultStatus::Completed);

        let mut second = Action::new(capability_id, json!({ "amount": 11 }));
        second.idempotency_key = Some("idem:test".to_owned());
        let second_result = runtime
            .process_action(second, &principal)
            .await
            .expect("second result");
        assert_eq!(second_result.status, ActionResultStatus::Failed);
        assert_eq!(
            second_result
                .error
                .as_ref()
                .map(|error| error.code.as_str()),
            Some("idempotency.input_hash_mismatch")
        );
    }

