    #[tokio::test]
    async fn runtime_reopens_exact_idempotent_execute_after_retryable_failure() {
        let runtime = Runtime::new();
        let capability_id = CapabilityId::trusted("cap:idempotent-execute-retry");
        let principal = Principal::new(
            PrincipalId::trusted("agent:idempotent-execute-retry"),
            PrincipalKind::Agent,
        );
        let mut contract = enterprise_contract(
            vec![SideEffect::Write],
            IdempotencyRequirement::Required,
            Some(TransactionContract {
                supported_modes: vec![TransactionMode::Execute],
                requires_plan_before_commit: false,
                dry_run_fidelity: DryRunFidelity::PolicyAndSchema,
            }),
        );
        contract.approval = None;
        register_capability_with_contract(
            &runtime,
            &principal,
            Capability {
                id: capability_id.clone(),
                name: "idempotent execute retry".to_owned(),
                kind: CapabilityKind::Tool,
                input_schema: json!({"type": "object"}),
                output_schema: None,
                description: None,
                risk: None,
                stability: None,
                cost: None,
                auth: None,
                bindings: Vec::new(),
                requires_human_approval: None,
                contract: Some(contract),
            },
        )
        .await;
        let calls = Arc::new(AtomicUsize::new(0));
        runtime
            .register_handler_for_test(
                capability_id.clone(),
                CountingHandler {
                    calls: calls.clone(),
                    fail_times: 1,
                },
            )
            .await
            .expect("replace admitted handler");

        let transaction_id =
            TransactionId::parse("txn_idempotent_execute_retry").expect("transaction id");
        let mut action = Action::new(capability_id, json!({ "amount": 10 }));
        action.id = ActionId::parse("act_idempotent_execute_retry").expect("action id");
        action.idempotency_key = Some("idem:idempotent-execute-retry".to_owned());
        action.transaction = Some(ActionTransaction {
            mode: TransactionMode::Execute,
            transaction_id: Some(transaction_id.clone()),
            plan_id: None,
            compensation_for: None,
        });

        let first = runtime
            .process_action(action.clone(), &principal)
            .await
            .expect("first execute attempt");
        assert_eq!(first.status, ActionResultStatus::Failed);
        assert_eq!(
            runtime
                .transactions
                .get(&transaction_id)
                .await
                .expect("load failed transaction")
                .expect("failed transaction")
                .status,
            TransactionStatus::Failed
        );

        let second = runtime
            .process_action(action.clone(), &principal)
            .await
            .expect("retry exact execute attempt");
        assert_eq!(second.status, ActionResultStatus::Completed);
        assert_eq!(calls.load(Ordering::SeqCst), 2);
        let transaction = runtime
            .transactions
            .get(&transaction_id)
            .await
            .expect("load committed transaction")
            .expect("committed transaction");
        assert_eq!(transaction.status, TransactionStatus::Committed);
        assert_eq!(transaction.result.as_ref(), Some(&second));
        let queued = runtime
            .action_queue
            .get(&action.id)
            .await
            .expect("load terminal action record")
            .expect("terminal action record");
        assert_eq!(queued.status, QueuedActionStatus::Completed);
        assert_eq!(queued.result.as_ref(), Some(&second));
        assert_eq!(queued.attempts, 2);

        let replay = runtime
            .process_action(action, &principal)
            .await
            .expect("settled execute replay");
        assert_eq!(replay.status, ActionResultStatus::Completed);
        assert_eq!(calls.load(Ordering::SeqCst), 2);
    }

    #[tokio::test]
    async fn runtime_commits_existing_transaction_plan_and_preserves_plan_record() {
        let runtime = Runtime::new();
        let capability_id = CapabilityId::parse("cap:transaction-commit").expect("cap id");
        let principal = Principal::new(
            PrincipalId::parse("agent:transaction").expect("principal"),
            PrincipalKind::Agent,
        );
        register_capability_with_contract(
            &runtime,
            &principal,
            Capability {
                id: capability_id.clone(),
                name: "transaction commit".to_owned(),
                kind: CapabilityKind::Tool,
                input_schema: json!({"type": "object"}),
                output_schema: None,
                description: None,
                risk: None,
                stability: None,
                cost: None,
                auth: None,
                bindings: Vec::new(),
                requires_human_approval: None,
                contract: Some(enterprise_contract(
                    vec![SideEffect::Write],
                    IdempotencyRequirement::Optional,
                    Some(TransactionContract {
                        supported_modes: vec![
                            TransactionMode::Plan,
                            TransactionMode::Commit,
                            TransactionMode::Compensate,
                        ],
                        requires_plan_before_commit: true,
                        dry_run_fidelity: DryRunFidelity::PolicyAndSchema,
                    }),
                )),
            },
        )
        .await;
        runtime
            .register_handler_for_test(capability_id.clone(), EchoHandler)
            .await
            .expect("replace admitted handler");

        let mut plan = Action::new(capability_id.clone(), json!({ "case_id": "C-1" }));
        plan.transaction = Some(ActionTransaction {
            mode: TransactionMode::Plan,
            transaction_id: None,
            plan_id: Some("plan:case-update".to_owned()),
            compensation_for: None,
        });
        let plan_result = runtime
            .process_action(plan, &principal)
            .await
            .expect("plan result");
        assert_eq!(plan_result.status, ActionResultStatus::Completed);
        let planned = runtime
            .transactions
            .by_plan_id("plan:case-update")
            .await
            .expect("load planned transaction")
            .expect("planned transaction");
        assert_eq!(planned.status, super::TransactionStatus::Planned);

        let mut commit = Action::new(capability_id, json!({ "case_id": "C-1" }));
        let commit_action_id = commit.id.clone();
        commit.transaction = Some(ActionTransaction {
            mode: TransactionMode::Commit,
            transaction_id: None,
            plan_id: Some("plan:case-update".to_owned()),
            compensation_for: None,
        });
        let commit_result = runtime
            .process_action(commit, &principal)
            .await
            .expect("commit result");
        assert_eq!(commit_result.status, ActionResultStatus::Completed);
        let committed = runtime
            .transactions
            .get(&planned.transaction_id)
            .await
            .expect("load committed transaction")
            .expect("committed transaction");
        assert_eq!(committed.status, super::TransactionStatus::Committed);
        assert_eq!(committed.action_id, commit_action_id);
        assert!(committed.plan.is_some());
        assert_eq!(
            committed
                .result
                .as_ref()
                .and_then(|result| result.output.as_ref())
                .and_then(|output| output.pointer("/echo/case_id")),
            Some(&json!("C-1"))
        );
    }

