    #[tokio::test]
    async fn terminal_action_result_persists_one_authenticated_audit_projection() {
        let runtime = Runtime::new();
        let actor = Principal::new(
            PrincipalId::trusted("service:audit-action-owner"),
            PrincipalKind::Service,
        );
        let untrusted_wire_actor = Principal::new(
            PrincipalId::trusted("agent:untrusted-wire-actor"),
            PrincipalKind::Agent,
        );
        let action_id = ActionId::new();
        let result = ActionResult {
            action_id: action_id.clone(),
            status: ActionResultStatus::Completed,
            output: Some(json!({ "safe": true })),
            message: Vec::new(),
            memory_update: None,
            usage: None,
            receipt: None,
            error: None,
        };
        let mut context = authenticated_context(&actor);
        context.actor = Some(untrusted_wire_actor);

        runtime
            .persist_action_result(result.clone(), &context)
            .await
            .expect("persist first action result");
        runtime
            .persist_action_result(result, &context)
            .await
            .expect("replay action result");

        let page = runtime
            .audit_query(AuditQueryRequest {
                action_id: Some(action_id.clone()),
                limit: Some(10),
                ..AuditQueryRequest::default()
            })
            .await
            .expect("query action audit events");
        assert_eq!(page.events.len(), 1);
        assert_eq!(page.events[0].actor.id, actor.id);
        assert_eq!(page.events[0].action, "aip.action.result");
        assert_eq!(
            page.events[0]
                .data
                .as_ref()
                .and_then(|data| data.get("action_id")),
            Some(&json!(action_id))
        );
    }

