    #[tokio::test]
    async fn uncertain_commit_is_checkpointed_deduplicated_and_reconciled() {
        let observer = RecordingExecutionObserver::default();
        let observed = observer.stages.clone();
        let runtime = Runtime::new().with_execution_checkpoint_observer(Arc::new(observer));
        let capability_id = CapabilityId::trusted("cap:transaction-uncertain-commit");
        let principal = Principal::new(
            PrincipalId::trusted("agent:transaction-uncertain-owner"),
            PrincipalKind::Agent,
        );
        let mut contract = enterprise_contract(
            vec![SideEffect::Financial, SideEffect::Write],
            IdempotencyRequirement::Required,
            Some(TransactionContract {
                supported_modes: vec![TransactionMode::Commit, TransactionMode::Reconcile],
                requires_plan_before_commit: false,
                dry_run_fidelity: DryRunFidelity::PolicyAndSchema,
            }),
        );
        contract.approval = None;
        contract.sla = Some(ServiceLevelContract {
            expected_latency_ms: Some(1),
            timeout_ms: Some(5),
            async_expected: false,
            max_queue_delay_ms: None,
            availability_target: None,
        });
        register_capability_with_contract(
            &runtime,
            &principal,
            Capability {
                id: capability_id.clone(),
                name: "uncertain transaction commit".to_owned(),
                kind: CapabilityKind::Tool,
                input_schema: json!({"type": "object"}),
                output_schema: None,
                description: None,
                risk: Some(RiskLevel::Medium),
                stability: None,
                cost: None,
                auth: None,
                bindings: Vec::new(),
                requires_human_approval: None,
                contract: Some(contract),
            },
        )
        .await;
        let calls = Arc::new(AtomicUsize::new(0));
        let cancellations = Arc::new(AtomicUsize::new(0));
        runtime
            .register_handler_for_test(
                capability_id.clone(),
                CheckpointingTransactionHandler {
                    calls: calls.clone(),
                    cancellations: cancellations.clone(),
                    commit_sleep_ms: 50,
                },
            )
            .await
            .expect("replace admitted handler");

        let transaction_id = TransactionId::new();
        let mut commit = Action::new(capability_id.clone(), json!({ "amount": 1250 }));
        commit.idempotency_key = Some("idempotency:uncertain-commit-42".to_owned());
        commit.transaction = Some(ActionTransaction {
            mode: TransactionMode::Commit,
            transaction_id: Some(transaction_id.clone()),
            plan_id: None,
            compensation_for: None,
        });
        let replay = commit.clone();
        let result = runtime
            .process_action(commit, &principal)
            .await
            .expect("uncertain commit result");
        assert_eq!(result.status, ActionResultStatus::Failed);
        let error = result.error.as_ref().expect("timeout error");
        assert_eq!(error.code, "sla.timeout_exceeded");
        assert_eq!(error.retryable, Some(false));
        assert_eq!(calls.load(Ordering::SeqCst), 1);
        assert_eq!(cancellations.load(Ordering::SeqCst), 1);

        let uncertain = runtime
            .transactions
            .get(&transaction_id)
            .await
            .expect("load transaction")
            .expect("transaction record");
        assert_eq!(uncertain.status, super::TransactionStatus::OutcomeUnknown);
        assert_eq!(
            uncertain
                .provider_operation
                .as_ref()
                .map(|operation| operation.operation_id.as_str()),
            Some("provider-operation-42")
        );
        assert_eq!(
            uncertain.reconciliation_cursor.as_deref(),
            Some("cursor:provider-operation-42")
        );
        assert!(uncertain.reconcile_after.is_some());

        let replayed = runtime
            .process_action(replay, &principal)
            .await
            .expect("idempotent uncertain replay");
        assert_eq!(replayed.status, ActionResultStatus::Failed);
        assert_eq!(calls.load(Ordering::SeqCst), 1);

        let mut reconcile = Action::new(capability_id, json!({ "amount": 1250 }));
        reconcile.idempotency_key = Some("idempotency:reconcile-42".to_owned());
        reconcile.transaction = Some(ActionTransaction {
            mode: TransactionMode::Reconcile,
            transaction_id: Some(transaction_id.clone()),
            plan_id: None,
            compensation_for: None,
        });
        let reconciled = runtime
            .process_action(reconcile, &principal)
            .await
            .expect("reconciliation result");
        assert_eq!(
            reconciled.status,
            ActionResultStatus::Completed,
            "reconciliation failed: {:?}",
            reconciled.error
        );
        assert_eq!(calls.load(Ordering::SeqCst), 2);
        let record = runtime
            .transactions
            .get(&transaction_id)
            .await
            .expect("load reconciled transaction")
            .expect("reconciled transaction");
        assert_eq!(record.status, super::TransactionStatus::Reconciled);
        assert_eq!(
            record.reconciliation_cursor.as_deref(),
            Some("cursor:terminal")
        );
        let reconciliation_stages = observed
            .lock()
            .await
            .iter()
            .copied()
            .filter(|stage| {
                matches!(
                    stage,
                    ExecutionCheckpointStage::ReconciliationStarted
                        | ExecutionCheckpointStage::ReconciliationCompleted
                )
            })
            .collect::<Vec<_>>();
        assert_eq!(
            reconciliation_stages,
            vec![
                ExecutionCheckpointStage::ReconciliationStarted,
                ExecutionCheckpointStage::ReconciliationCompleted,
            ]
        );
    }

