    #[tokio::test]
    async fn runtime_reschedules_retryable_queued_failure_before_terminal_settlement() {
        let runtime = Runtime::new();
        let capability_id = CapabilityId::parse("cap:retry-reschedule").expect("cap id");
        let principal = Principal::new(
            PrincipalId::parse("agent:retry-reschedule").expect("principal"),
            PrincipalKind::Agent,
        );
        register_echo_capability(&runtime, &principal, capability_id.clone()).await;
        runtime
            .register_handler_for_test(
                capability_id.clone(),
                FlakyHandler {
                    failures_remaining: Arc::new(AtomicUsize::new(1)),
                },
            )
            .await
            .expect("replace admitted handler");

        let now = OffsetDateTime::now_utc();
        let mut action = Action::new(capability_id, json!({ "retry": true }));
        action.mode = Some(ActionMode::Async);
        action.idempotency_key = Some("retry-key-1".to_owned());
        let action_id = action.id.clone();
        runtime
            .action_queue
            .enqueue(QueuedActionRecord {
                action,
                principal,
                context: MessageContext::default(),
                status: QueuedActionStatus::Queued,
                result: None,
                cancellation_reason: None,
                attempts: 0,
                retry_policy: Some(test_retry_policy(3)),
                first_attempted_at: None,
                last_attempted_at: None,
                next_attempt_at: None,
                last_error: None,
                dead_letter_reason: None,
                lease: None,
                idempotency_reservation: None,
                created_at: now,
                updated_at: now,
            })
            .await
            .expect("enqueue retryable action");

        let first = runtime
            .run_queued_action_once("worker-a", 60_000)
            .await
            .expect("first worker claim")
            .expect("first attempt result");
        assert_eq!(first.status, ActionResultStatus::Failed);
        assert!(
            runtime
                .lifecycle
                .action_result(&action_id)
                .await
                .expect("load retryable action result")
                .is_none(),
            "retryable failure is not a terminal action result"
        );
        let queued = runtime
            .action_queue
            .get(&action_id)
            .await
            .expect("load rescheduled queue record")
            .expect("rescheduled record");
        assert_eq!(queued.status, QueuedActionStatus::Queued);
        assert_eq!(queued.attempts, 1);
        assert!(queued.next_attempt_at.is_some());
        assert!(queued.lease.is_none());
        assert!(queued.result.is_none());
        assert!(
            runtime
                .action_queue
                .dead_letters()
                .await
                .expect("load dead letters")
                .is_empty()
        );

        tokio::time::sleep(Duration::from_millis(2)).await;
        let second = runtime
            .run_queued_action_once("worker-b", 60_000)
            .await
            .expect("second worker claim")
            .expect("second attempt result");
        assert_eq!(second.status, ActionResultStatus::Completed);
        let settled = runtime
            .action_queue
            .get(&action_id)
            .await
            .expect("load settled queue record")
            .expect("settled record");
        assert_eq!(settled.status, QueuedActionStatus::Completed);
        assert_eq!(settled.attempts, 2);
        assert!(settled.next_attempt_at.is_none());
        assert!(settled.result.is_some());
        assert!(
            runtime
                .action_queue
                .dead_letters()
                .await
                .expect("load dead letters")
                .is_empty()
        );
    }

