    #[tokio::test]
    async fn runtime_rejects_approval_approver_spoofing_against_authenticated_actor() {
        let runtime = Runtime::new();
        let capability_id = CapabilityId::trusted("cap:approval-actor-binding");
        let requester = Principal::new(
            PrincipalId::trusted("agent:approval-requester"),
            PrincipalKind::Agent,
        );
        let approver = Principal::new(
            PrincipalId::trusted("human:authorized-approver"),
            PrincipalKind::Human,
        );
        let attacker = Principal::new(
            PrincipalId::trusted("agent:spoofing-client"),
            PrincipalKind::Agent,
        );
        register_capability_with_contract(
            &runtime,
            &requester,
            Capability {
                id: capability_id.clone(),
                name: "actor-bound approval".to_owned(),
                kind: CapabilityKind::Tool,
                input_schema: json!({ "type": "object" }),
                output_schema: None,
                description: None,
                risk: Some(RiskLevel::High),
                stability: None,
                cost: None,
                auth: None,
                bindings: Vec::new(),
                requires_human_approval: Some(true),
                contract: Some(approval_contract(ApproverSelector::Principal {
                    id: approver.id.clone(),
                })),
            },
        )
        .await;
        runtime
            .register_handler_for_test(capability_id.clone(), EchoHandler)
            .await
            .expect("replace admitted handler");
        let action = Action::new(capability_id, json!({ "amount": 50 }));
        let action_id = action.id.clone();
        let blocked = runtime
            .process_action(action, &requester)
            .await
            .expect("approval-blocked result");
        assert_eq!(blocked.status, ActionResultStatus::PendingApproval);
        let approval_request = runtime
            .approvals
            .pending()
            .await
            .expect("pending approvals")[0]
            .request
            .clone();
        let approval_id = approval_request.id.clone();

        let error = runtime
            .record_approval_decision(
                approval_decision(&approval_request, approver, ApprovalDecisionKind::Approved),
                MessageContext {
                    actor: Some(attacker),
                    ..MessageContext::default()
                },
            )
            .await
            .expect_err("payload approver must be bound to authenticated actor");
        assert!(error.to_string().contains("transport-established identity"));
        assert_eq!(
            runtime
                .approvals
                .get(&approval_id)
                .await
                .expect("approval lookup")
                .expect("approval record")
                .status,
            super::ApprovalStatus::Pending
        );
        assert_eq!(
            runtime
                .action_queue
                .get(&action_id)
                .await
                .expect("queue lookup")
                .expect("queue record")
                .status,
            QueuedActionStatus::RequiresHuman
        );
    }

    #[tokio::test]
    async fn runtime_executes_concurrent_idempotent_calls_exactly_once() {
        let runtime = Runtime::new();
        let capability_id = CapabilityId::trusted("cap:idempotency-concurrent");
        let principal = Principal::new(
            PrincipalId::trusted("agent:idempotency-concurrent"),
            PrincipalKind::Agent,
        );
        register_capability_with_contract(
            &runtime,
            &principal,
            Capability {
                id: capability_id.clone(),
                name: "concurrent idempotent mutation".to_owned(),
                kind: CapabilityKind::Tool,
                input_schema: json!({ "type": "object" }),
                output_schema: None,
                description: None,
                risk: None,
                stability: None,
                cost: None,
                auth: None,
                bindings: Vec::new(),
                requires_human_approval: None,
                contract: Some(enterprise_contract(
                    vec![SideEffect::Write],
                    IdempotencyRequirement::Required,
                    None,
                )),
            },
        )
        .await;
        let calls = Arc::new(AtomicUsize::new(0));
        let started = Arc::new(tokio::sync::Notify::new());
        runtime
            .register_handler_for_test(
                capability_id.clone(),
                ObservableSlowHandler {
                    calls: calls.clone(),
                    completions: Arc::new(AtomicUsize::new(0)),
                    cancellations: Arc::new(AtomicUsize::new(0)),
                    started: started.clone(),
                    sleep_ms: 80,
                },
            )
            .await
            .expect("replace admitted handler");
        let mut first = Action::new(capability_id.clone(), json!({ "order": "O-1" }));
        first.idempotency_key = Some("order:O-1".to_owned());
        let mut second = Action::new(capability_id, json!({ "order": "O-1" }));
        second.idempotency_key = Some("order:O-1".to_owned());
        let started_wait = started.notified();
        let first_runtime = runtime.clone();
        let first_principal = principal.clone();
        let first_task =
            tokio::spawn(
                async move { first_runtime.process_action(first, &first_principal).await },
            );
        started_wait.await;
        let second_result = runtime
            .process_action(second, &principal)
            .await
            .expect("competing result");
        let first_result = first_task.await.expect("first task").expect("first result");

        assert_eq!(first_result.status, ActionResultStatus::Completed);
        assert_eq!(second_result.status, ActionResultStatus::Failed);
        assert_eq!(
            second_result
                .error
                .as_ref()
                .map(|error| error.code.as_str()),
            Some("idempotency.in_progress")
        );
        assert_eq!(calls.load(Ordering::SeqCst), 1);
    }

    #[tokio::test]
    async fn runtime_cancel_stops_active_handler_and_cannot_be_overwritten_by_completion() {
        let runtime = Runtime::new();
        let capability_id = CapabilityId::trusted("cap:cancellable-operation");
        let principal = Principal::new(
            PrincipalId::trusted("agent:cancellation-owner"),
            PrincipalKind::Agent,
        );
        register_echo_capability(&runtime, &principal, capability_id.clone()).await;
        let calls = Arc::new(AtomicUsize::new(0));
        let completions = Arc::new(AtomicUsize::new(0));
        let cancellations = Arc::new(AtomicUsize::new(0));
        let started = Arc::new(tokio::sync::Notify::new());
        runtime
            .register_handler_for_test(
                capability_id.clone(),
                ObservableSlowHandler {
                    calls: calls.clone(),
                    completions: completions.clone(),
                    cancellations: cancellations.clone(),
                    started: started.clone(),
                    sleep_ms: 150,
                },
            )
            .await
            .expect("replace admitted handler");
        let action = Action::new(capability_id, json!({ "operation": "slow" }));
        let action_id = action.id.clone();
        let started_wait = started.notified();
        let executing_runtime = runtime.clone();
        let executing_principal = principal.clone();
        let executing = tokio::spawn(async move {
            executing_runtime
                .process_action(action, &executing_principal)
                .await
        });
        started_wait.await;
        let attacker = Principal::new(
            PrincipalId::trusted("agent:cancellation-attacker"),
            PrincipalKind::Agent,
        );
        let unauthorized = runtime
            .handle_cancel(
                Cancel {
                    target: CancelTarget::Action(action_id.clone()),
                    reason: Some("forged cancellation".to_owned()),
                },
                scoped_context(&attacker, &["action:write"]),
            )
            .await
            .expect_err("non-owner cancellation must fail");
        assert!(matches!(unauthorized, RuntimeError::Authorization(_)));
        let cancel_body = runtime
            .handle_cancel(
                Cancel {
                    target: CancelTarget::Action(action_id.clone()),
                    reason: Some("operator requested cancellation".to_owned()),
                },
                scoped_context(&principal, &["action:write"]),
            )
            .await
            .expect("cancel result");
        assert!(matches!(
            cancel_body,
            MessageBody::ActionResult(ref result)
                if result.status == ActionResultStatus::Cancelled
        ));
        let execution_result = executing
            .await
            .expect("execution task")
            .expect("execution result");
        assert_eq!(execution_result.status, ActionResultStatus::Cancelled);
        tokio::time::sleep(Duration::from_millis(180)).await;
        assert_eq!(calls.load(Ordering::SeqCst), 1);
        assert_eq!(cancellations.load(Ordering::SeqCst), 1);
        assert_eq!(completions.load(Ordering::SeqCst), 0);
        assert_eq!(
            runtime
                .lifecycle
                .action_result(&action_id)
                .await
                .expect("result lookup")
                .expect("cancelled result")
                .status,
            ActionResultStatus::Cancelled
        );
    }

