    #[tokio::test]
    async fn action_queue_rejects_settlement_from_stale_fencing_token() {
        let runtime = Runtime::new();
        let action = Action::new(
            CapabilityId::trusted("cap:stale-fencing"),
            json!({ "fencing": true }),
        );
        let action_id = action.id.clone();
        let principal = Principal::new(PrincipalId::trusted("agent:fencing"), PrincipalKind::Agent);
        let now = OffsetDateTime::now_utc();
        runtime
            .action_queue
            .enqueue(QueuedActionRecord {
                action,
                principal,
                context: MessageContext::default(),
                status: QueuedActionStatus::Queued,
                result: None,
                cancellation_reason: None,
                attempts: 0,
                retry_policy: None,
                first_attempted_at: None,
                last_attempted_at: None,
                next_attempt_at: None,
                last_error: None,
                dead_letter_reason: None,
                lease: None,
                idempotency_reservation: None,
                created_at: now,
                updated_at: now,
            })
            .await
            .expect("enqueue");
        let first = runtime
            .action_queue
            .lease_next("worker-a", 1)
            .await
            .expect("first lease")
            .expect("first record");
        let first_lease = first.lease.expect("first fencing token").lease_id;
        tokio::time::sleep(Duration::from_millis(3)).await;
        let second = runtime
            .action_queue
            .lease_next("worker-b", 60_000)
            .await
            .expect("replacement lease")
            .expect("replacement record");
        let second_lease = second.lease.expect("second fencing token").lease_id;
        let stale = runtime
            .action_queue
            .complete_attempt(
                &action_id,
                &first_lease,
                QueueAttemptOutcome::Settle(ActionResult {
                    action_id: action_id.clone(),
                    status: ActionResultStatus::Completed,
                    output: Some(json!({ "worker": "stale" })),
                    message: Vec::new(),
                    memory_update: None,
                    usage: None,
                    receipt: None,
                    error: None,
                }),
            )
            .await
            .expect("stale settlement response");
        assert_eq!(stale, QueueCompletion::LeaseLost);
        let applied = runtime
            .action_queue
            .complete_attempt(
                &action_id,
                &second_lease,
                QueueAttemptOutcome::Settle(ActionResult {
                    action_id: action_id.clone(),
                    status: ActionResultStatus::Completed,
                    output: Some(json!({ "worker": "owner" })),
                    message: Vec::new(),
                    memory_update: None,
                    usage: None,
                    receipt: None,
                    error: None,
                }),
            )
            .await
            .expect("owned settlement response");
        assert_eq!(applied, QueueCompletion::Applied);
        let record = runtime
            .action_queue
            .get(&action_id)
            .await
            .expect("queue lookup")
            .expect("queue record");
        assert_eq!(record.status, QueuedActionStatus::Completed);
        assert_eq!(
            record.result.and_then(|result| result.output),
            Some(json!({ "worker": "owner" }))
        );
    }

    #[tokio::test]
    async fn action_event_cursor_filters_before_pagination_and_never_repeats_chunks() {
        let runtime = Runtime::new();
        let action_id = ActionId::new();
        let other_action_id = ActionId::new();
        for (kind, event_action_id) in [
            ("target-one", action_id.clone()),
            ("other", other_action_id),
            ("target-two", action_id.clone()),
        ] {
            let mut event = Event::new(kind);
            event.action_id = Some(event_action_id);
            runtime.events.append(event).await.expect("append event");
        }
        for sequence in [0, 1] {
            runtime
                .lifecycle
                .record_stream_chunk(StreamChunk {
                    action_id: action_id.clone(),
                    sequence,
                    kind: if sequence == 1 {
                        StreamChunkKind::Done
                    } else {
                        StreamChunkKind::Data
                    },
                    data: Some(json!({ "sequence": sequence })),
                    part: None,
                })
                .await
                .expect("record chunk");
        }
        let mut cursor = None;
        let mut event_kinds = Vec::new();
        let mut chunk_sequences = Vec::new();
        for _ in 0..5 {
            let page = runtime
                .action_events(ActionEventsRequest {
                    action_id: action_id.clone(),
                    tenant_id: None,
                    cursor: cursor.clone(),
                    limit: Some(1),
                    kinds: Vec::new(),
                    include_chunks: true,
                    follow: false,
                })
                .await
                .expect("action event page");
            event_kinds.extend(page.events.into_iter().map(|event| event.kind));
            chunk_sequences.extend(page.chunks.into_iter().map(|chunk| chunk.sequence));
            cursor = page.cursor;
        }
        assert_eq!(event_kinds, vec!["target-one", "target-two"]);
        assert_eq!(chunk_sequences, vec![0, 1]);
    }

